    scaleControl: false,
    streetViewControl: false,
    rotateControl: false,
    fullscreenControl: false,
  });

  // Fix: Cast window to any to allow assigning Popup class and resolve errors on lines 76, 509
  (window as any).Popup = class Popup extends google.maps.OverlayView {
    position;
    containerDiv;
    constructor(position, content) {
      super();
      this.position = position;
      content.classList.add('popup-bubble');

      this.containerDiv = document.createElement('div');
      this.containerDiv.classList.add('popup-container');
      this.containerDiv.appendChild(content); 
      // Fix: Call preventMapHitsAndGesturesFrom from google.maps.OverlayView to fix error on line 87
      google.maps.OverlayView.preventMapHitsAndGesturesFrom(this.containerDiv);
    }

    onAdd() {
      // Fix: Cast this to any to access OverlayView methods and fix error on line 91
      (this as any).getPanes().floatPane.appendChild(this.containerDiv);
    }

    onRemove() {
      if (this.containerDiv.parentElement) {
        this.containerDiv.parentElement.removeChild(this.containerDiv);
      }
    }

    draw() {
      // Fix: Cast this to any to access OverlayView methods and fix error on line 101
      const divPosition = (this as any).getProjection().fromLatLngToDivPixel(
        this.position,
      );
      const display =
        Math.abs(divPosition.x) < 4000 && Math.abs(divPosition.y) < 4000
          ? 'block'
          : 'none';

      if (display === 'block') {
        this.containerDiv.style.left = divPosition.x + 'px';
        this.containerDiv.style.top = divPosition.y + 'px';
      }

      if (this.containerDiv.style.display !== display) {
        this.containerDiv.style.display = display;
      }
    }
  };
}

