   * 为每个停靠点提供具体的访问时间和时长。
   * 每个地点必须包含 'time' (例如 "09:00") 和 'duration' (例如 "2小时")。
   * 每个地点必须包含 'sequence' 序号 (1, 2, 3...)。
   * 路线应包含 'transport' (交通方式) 和 'travelTime' (行驶时间)。

**重要准则:**
* 始终使用中文回复。
* 即使是复杂或抽象的查询，也要尝试在地图上可视化信息。
* 行程规划应现实可行，通常从 8:00am 开始，不晚于 9:00pm 结束。
* 对于任何查询，始终通过 'location' 函数提供地理数据。`;

const ai = new GoogleGenAI({
  apiKey: process.env.API_KEY,
});

function showTimeline() {
  if (timelineContainer) {
    timelineContainer.style.display = 'block';
    setTimeout(() => {
      timelineContainer.classList.add('visible');
      if (window.innerWidth > 768) {
        mapContainer.classList.add('map-container-shifted');
        adjustInterfaceForTimeline(true);
        window.dispatchEvent(new Event('resize'));
      } else {
        mapOverlay.classList.add('visible');
      }
    }, 10);
  }
}

function hideTimeline() {
  if (timelineContainer) {
    timelineContainer.classList.remove('visible');
    mapContainer.classList.remove('map-container-shifted');
    mapOverlay.classList.remove('visible');
    adjustInterfaceForTimeline(false);
    setTimeout(() => {
      timelineContainer.style.display = 'none';
      window.dispatchEvent(new Event('resize'));
    }, 300);
  }
}

function adjustInterfaceForTimeline(isTimelineVisible) {
  if (bounds && map) {
    setTimeout(() => {
      map.fitBounds(bounds);
    }, 350);
  }
}

const promptInput = document.querySelector(
  '#prompt-input',
) as HTMLTextAreaElement;
promptInput.addEventListener('keydown', (e: KeyboardEvent) => {
  if (e.code === 'Enter' && !e.shiftKey) {
    const buttonEl = document.getElementById('generate') as HTMLButtonElement;
    buttonEl.classList.add('loading');
    e.preventDefault();
    e.stopPropagation();

    setTimeout(() => {
      sendText(promptInput.value);
      promptInput.value = '';
    }, 10);
  }
});

generateButton.addEventListener('click', (e) => {
  const buttonEl = e.currentTarget as HTMLButtonElement;
  buttonEl.classList.add('loading');

  setTimeout(() => {
    sendText(promptInput.value);
  }, 10);
});

resetButton.addEventListener('click', (e) => {
