if (plannerModeToggle) {
  plannerModeToggle.addEventListener('change', () => {
    isPlannerMode = plannerModeToggle.checked;
    promptInput.placeholder = isPlannerMode
      ? "创建行程规划... (例如 '规划北京胡同一日游' 或 '上海浦东探索')"
      : '探索地点、历史、活动，或询问任何位置...';

    if (!isPlannerMode && timelineContainer) {
      hideTimeline();
