    properties: {
      name: { type: Type.STRING, description: '地点名称。' },
      description: { type: Type.STRING, description: '地点描述。' },
      lat: { type: Type.STRING, description: '纬度。' },
      lng: { type: Type.STRING, description: '经度。' },
      weather: { type: Type.STRING, description: '当前天气（"sunny", "rainy", "snowy", "cloudy", "stormy"）。' },
