const systemInstructions = `## 交互式天气地图助手指南
你是一个具备实时天气感知能力的地理专家。
**核心规则:**
1. 始终使用中文回复。
2. 识别地点的当前天气。例如：西安此时可能是晴天(sunny)，但延安可能是暴雪(snowy)。
3. 对于每个 location，必须包含准确的 weather 字段和模拟的 temp 温度字段。
4. 初始视图应关注中国地区。
5. 当用户询问路线或探索时，将天气状况融入描述中。`;

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

async function sendText(prompt: string) {
  if (!prompt.trim()) return;
  spinner.classList.remove('hidden');
  errorMessage.innerHTML = '';
  restart();
  const buttonEl = document.getElementById('generate') as HTMLButtonElement;

  try {
    const response = await ai.models.generateContentStream({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        systemInstruction: systemInstructions,
        tools: [{ functionDeclarations: [locationFunctionDeclaration, lineFunctionDeclaration] }],
      },
    });

    let results = false;
    for await (const chunk of response) {
      const fns = chunk.functionCalls ?? [];
      for (const fn of fns) {
        if (fn.name === 'location') { await setPin(fn.args); results = true; }
        if (fn.name === 'line') { await setLeg(fn.args); results = true; }
      }
    }

    if (!results) throw new Error('未能获取地点信息。');
    createLocationCards();
    if (popUps.length > 0) highlightCard(0);
  } catch (e) {
    errorMessage.innerHTML = `错误: ${e.message}`;
  } finally {
    buttonEl.classList.remove('loading');
    spinner.classList.add('hidden');
  }
}

async function setPin(args) {
  const point = {lat: Number(args.lat), lng: Number(args.lng)};
  points.push(point);
  bounds.extend(point);
  const marker = new AdvancedMarkerElement({ map, position: point, title: args.name });
  markers.push(marker);
  map.fitBounds(bounds);

  const content = document.createElement('div');
  content.innerHTML = `<b>${args.name}</b><br/>${args.weather === 'snowy' ? '❄️' : '☀️'} ${args.temp || ''}<br/>${args.description}`;
  const popup = new (window as any).Popup(new google.maps.LatLng(point), content);
  popup.setMap(map);

  popUps.push({
    ...args,
    position: new google.maps.LatLng(point),
    popup,
    content
  });
}

async function setLeg(args) {
  const start = { lat: Number(args.start.lat), lng: Number(args.start.lng) };
  const end = { lat: Number(args.end.lat), lng: Number(args.end.lng) };
  bounds.extend(start); bounds.extend(end);
  map.fitBounds(bounds);
  const poly = new google.maps.Polyline({
    path: [start, end],
    strokeColor: '#2196F3',
    strokeOpacity: 0.8,
    strokeWeight: 3,
    map
  });
  lines.push({ poly, name: args.name });
}

function createLocationCards() {
  cardContainer.innerHTML = '';
  carouselIndicators.innerHTML = '';
  cardCarousel.style.display = 'block';

  popUps.forEach((loc, index) => {
    const card = document.createElement('div');
    card.className = 'location-card';
    const weatherIcon = loc.weather === 'snowy' ? 'fa-snowflake' : loc.weather === 'rainy' ? 'fa-cloud-showers-heavy' : 'fa-sun';
    card.innerHTML = `
      <div class="card-weather-overlay"><i class="fas ${weatherIcon}"></i> ${loc.temp || ''}</div>
      <div class="card-content">
        <h3 class="card-title">${loc.name}</h3>
        <p class="card-description">${loc.description}</p>
        <div class="card-weather-tag">${loc.weather}</div>
      </div>
    `;
    card.onclick = () => highlightCard(index);
    cardContainer.appendChild(card);
    const dot = document.createElement('div');
    dot.className = 'carousel-dot';
    carouselIndicators.appendChild(dot);
  });
}

function highlightCard(index: number) {
  activeCardIndex = index;
  const cards = cardContainer.querySelectorAll('.location-card');
  cards.forEach((c, i) => c.classList.toggle('card-active', i === index));
  const dots = carouselIndicators.querySelectorAll('.carousel-dot');
  dots.forEach((d, i) => d.classList.toggle('active', i === index));

  const loc = popUps[index];
  if (loc) {
    map.panTo(loc.position);
    startWeatherAnimation(loc.weather);
  }
}

function restart() {
  points = [];
  bounds = new google.maps.LatLngBounds();
  markers.forEach(m => m.setMap(null));
  markers = [];
  lines.forEach(l => l.poly.setMap(null));
  lines = [];
  popUps.forEach(p => p.popup.setMap(null));
  popUps = [];
  cardContainer.innerHTML = '';
  if (animationId) cancelAnimationFrame(animationId);
  if (ctx) ctx.clearRect(0, 0, canvas.width, canvas.height);
}

promptInput.addEventListener('keydown', e => {
  if (e.key === 'Enter' && !e.shiftKey) {
    e.preventDefault();
    (generateButton as HTMLButtonElement).classList.add('loading');
    sendText(promptInput.value);
  }
});

generateButton.addEventListener('click', () => {
  generateButton.classList.add('loading');
  sendText(promptInput.value);
});

resetButton.addEventListener('click', restart);

