let isUiHidden = false;

// Weather System State
let canvas: HTMLCanvasElement;
let ctx: CanvasRenderingContext2D | null;
let animationId: number;
let particles: any[] = [];

// Drag and Drop State
let draggedItemIndex: number | null = null;

// DOM Elements
const mapContainer = document.querySelector('#map-container') as HTMLDivElement;
const searchContainer = document.querySelector('#search-container') as HTMLDivElement;
const generateButton = document.querySelector('#generate') as HTMLButtonElement;
const resetButton = document.querySelector('#reset') as HTMLButtonElement;
const cardContainer = document.querySelector('#card-container') as HTMLDivElement;
const carouselIndicators = document.querySelector('#carousel-indicators') as HTMLDivElement;
const cardCarousel = document.querySelector('.card-carousel') as HTMLDivElement;
const plannerModeToggle = document.querySelector('#planner-mode-toggle') as HTMLInputElement;
const timelineContainer = document.querySelector('#timeline-container') as HTMLDivElement;
const timeline = document.querySelector('#timeline') as HTMLDivElement;
const spinner = document.querySelector('#spinner') as HTMLDivElement;
const errorMessage = document.querySelector('#error-message') as HTMLDivElement;
const promptInput = document.querySelector('#prompt-input') as HTMLTextAreaElement;
const closeTimelineButton = document.querySelector('#close-timeline') as HTMLButtonElement;
const toggleUiBtn = document.querySelector('#toggle-search-ui') as HTMLButtonElement;
const reopenTimelineBtn = document.querySelector('#reopen-timeline') as HTMLButtonElement;
const exportBtn = document.querySelector('#export-itinerary') as HTMLButtonElement;

/**
 * 初始化天气 Canvas
 */
function initWeatherCanvas() {
  if (document.getElementById('weather-canvas')) return;
  canvas = document.createElement('canvas');
  canvas.id = 'weather-canvas';
  canvas.style.position = 'absolute';
  canvas.style.top = '0';
  canvas.style.left = '0';
  canvas.style.width = '100%';
  canvas.style.height = '100%';
  canvas.style.pointerEvents = 'none';
  canvas.style.zIndex = '5';
  document.getElementById('map-container')?.appendChild(canvas);
  ctx = canvas.getContext('2d');

  window.addEventListener('resize', () => {
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
  });
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;
}

/**
 * 天气动画渲染引擎
 */
function startWeatherAnimation(type: string) {
  if (!ctx) return;
  particles = [];
  if (animationId) cancelAnimationFrame(animationId);

  const createParticle = () => {
    if (type === 'rainy' || type === 'stormy') {
      return {
        x: Math.random() * canvas.width,
        y: Math.random() * canvas.height,
        l: Math.random() * 20 + 10,
        v: Math.random() * 10 + 10
      };
    } else if (type === 'snowy') {
      return {
        x: Math.random() * canvas.width,
        y: Math.random() * canvas.height,
        r: Math.random() * 3 + 1,
        v: Math.random() * 2 + 1,
        wind: Math.random() * 1 - 0.5
      };
    }
    return null;
  };

  if (['rainy', 'stormy', 'snowy'].includes(type)) {
    for (let i = 0; i < 150; i++) {
      const p = createParticle();
      if (p) particles.push(p);
    }
  }

  function animate() {
    if (!ctx) return;
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (type === 'rainy' || type === 'stormy') {
      ctx.strokeStyle = 'rgba(174, 194, 224, 0.6)';
      ctx.lineWidth = 1;
      particles.forEach(p => {
        ctx.beginPath();
        ctx.moveTo(p.x, p.y);
        ctx.lineTo(p.x, p.y + p.l);
        ctx.stroke();
        p.y += p.v;
        if (p.y > canvas.height) p.y = -p.l;
      });
      if (type === 'stormy' && Math.random() > 0.97) {
        ctx.fillStyle = 'rgba(255, 255, 255, 0.3)';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
      }
    } else if (type === 'snowy') {
      ctx.fillStyle = 'rgba(255, 255, 255, 0.9)';
      particles.forEach(p => {
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
        ctx.fill();
        p.y += p.v;
        p.x += p.wind;
        if (p.y > canvas.height) p.y = -p.r;
        if (p.x > canvas.width) p.x = 0;
        if (p.x < 0) p.x = canvas.width;
      });
    } else if (type === 'sunny') {
      const gradient = ctx.createRadialGradient(canvas.width / 2, 100, 0, canvas.width / 2, 100, 400);
      gradient.addColorStop(0, 'rgba(255, 255, 180, 0.2)');
      gradient.addColorStop(1, 'rgba(255, 255, 255, 0)');
      ctx.fillStyle = gradient;
      ctx.fillRect(0, 0, canvas.width, canvas.height);
    } else if (type === 'cloudy') {
      ctx.fillStyle = 'rgba(100, 100, 100, 0.08)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
    }

    animationId = requestAnimationFrame(animate);
  }
  animate();
}

/**
 * 初始化地图应用
 */
async function initApp() {
  try {
    const { Map } = await google.maps.importLibrary('maps');
    const { LatLngBounds } = await google.maps.importLibrary('core');

    bounds = new LatLngBounds();
    map = new Map(document.getElementById('map'), {
      center: { lat: 22.3193, lng: 114.1694 },
      zoom: 12,
      mapId: '4504f8b37365c3d0',
      gestureHandling: 'greedy',
      disableDefaultUI: true
    });

    initWeatherCanvas();

    (window as any).Popup = class Popup extends google.maps.OverlayView {
      position: any; containerDiv: HTMLDivElement;
      constructor(position: any, content: HTMLElement) {
        super();
        this.position = position;
        this.containerDiv = document.createElement('div');
        this.containerDiv.classList.add('custom-map-popup');
        const anchor = document.createElement('div');
        anchor.classList.add('popup-anchor');
        const bubble = document.createElement('div');
        bubble.classList.add('popup-bubble');
        bubble.appendChild(content);
        this.containerDiv.appendChild(bubble);
        this.containerDiv.appendChild(anchor);
        google.maps.OverlayView.preventMapHitsAndGesturesFrom(this.containerDiv);
      }
      onAdd() { (this as any).getPanes().floatPane.appendChild(this.containerDiv); }
      onRemove() { if (this.containerDiv.parentElement) this.containerDiv.parentElement.removeChild(this.containerDiv); }
      draw() {
        const divPosition = (this as any).getProjection().fromLatLngToDivPixel(this.position);
        if (divPosition) {
          this.containerDiv.style.left = divPosition.x + 'px';
          this.containerDiv.style.top = divPosition.y + 'px';
        }
      }
    };
  } catch (err) {
    console.error('地图加载失败:', err);
    errorMessage.innerText = '地图初始化失败，请检查网络连接。';
  }
}

initApp();

// Gemini 配置
const locationFunctionDeclaration: FunctionDeclaration = {
  name: 'location',
  parameters: {
    type: Type.OBJECT,
    description: '核心定位函数。每当你找到一个行程中的独立地点，必须立即调用此函数。',
    properties: {
      name: { type: Type.STRING, description: '地点精确名称。' },
      description: { type: Type.STRING, description: '地点描述（50字内），需提及小红书/抖音等平台的最新口碑或避雷建议。' },
      lat: { type: Type.STRING, description: '精确纬度。' },
      lng: { type: Type.STRING, description: '精确经度。' },
      weather: { type: Type.STRING, description: '当地天气类型：sunny, rainy, snowy, cloudy, stormy' },
      temp: { type: Type.STRING, description: '当前温度。' },
      time: { type: Type.STRING, description: '具体的环节时间点（如：08:00、12:30、19:00）。' },
      sequence: { type: Type.NUMBER, description: '行程中的绝对顺序索引（1, 2, 3...）。' },
      rank: { type: Type.NUMBER, description: '综合全网热度排名。' },
    },
    required: ['name', 'description', 'lat', 'lng', 'weather', 'rank', 'sequence', 'time'],
  },
};

const systemInstructions = `你是一个顶级全网实时导游。
## 绝对禁令：
- **严禁偷懒**：如果你只调用 1 次 location 函数，即视为失败。
- **严禁概括**：严禁把一天的行程写在同一个 location 的描述里。
- **强制循环**：你必须针对行程中的【每一个】站点（如早餐店、景点1、午餐店、景点2、夜景区）分别调用 location 函数。

## 运行协议：
1. **先搜索**：利用 Google Search 搜遍小红书、抖音、马蜂窝，寻找“XX一日游详细攻略”或“XX最新必打卡清单”。
2. **定清单**：在内心确定 5 到 8 个具体地点，确保它们空间位置合理。
3. **连环发射**：按照时间顺序，连续执行 5-8 次 location 函数调用。
4. **描述真实**：描述中必须带有社交平台的气息，如“小红书爆火日落点”、“避雷：周末人极多”等。`;

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

async function sendText(prompt: string) {
  if (!prompt.trim()) return;

  spinner.classList.remove('hidden');
  generateButton.classList.add('loading');
  errorMessage.innerHTML = '正在多信源同步检索最新打卡资讯...';

  restart();

  try {
    const userPrompt = isPlannerMode 
      ? `针对"${prompt}"，请规划一个至少包含 6 个独立站点的单日完整行程。要求：每一个地点都必须有独立的经纬度和 location 函数调用。请分步调用 6 次函数。`
      : `针对"${prompt}"，请搜索并推荐至少 5-8 个最火的地点，按热度排名，每个地点必须独立调用一次 location 函数。`;

    const response = await ai.models.generateContentStream({
      model: 'gemini-3-pro-preview',
      contents: userPrompt,
      config: {
        systemInstruction: systemInstructions,
        tools: [{ googleSearch: {} }, { functionDeclarations: [locationFunctionDeclaration] }],
      },
    });

    let locationCount = 0;
    for await (const chunk of response) {
      const metadata = (chunk as any).candidates?.[0]?.groundingMetadata;
      if (metadata?.groundingChunks) {
        metadata.groundingChunks.forEach((c: any) => {
          if (c.web && !groundingSources.find(s => s.uri === c.web.uri)) {
            groundingSources.push(c.web);
          }
        });
      }

      const fns = chunk.functionCalls ?? [];
      for (const fn of fns) {
        if (fn.name === 'location') { 
          await setPin(fn.args); 
          locationCount++;
          errorMessage.innerHTML = `📍 发现并标记：${fn.args.name} (已获 ${locationCount} 个建议)`;
        }
      }
    }

    if (locationCount === 0) throw new Error('AI 未能锁定有效的地理环节，请尝试更明确的城市或区域名。');

    if (isPlannerMode) {
      dayPlanItinerary.sort((a, b) => (a.sequence || 0) - (b.sequence || 0));
      popUps = [...dayPlanItinerary];
      reopenTimelineBtn.classList.remove('hidden');
    } else {
      popUps.sort((a, b) => (a.rank || 99) - (b.rank || 99));
    }

    createLocationCards();
    renderGroundingSources();
    if (popUps.length > 0) highlightCard(0, true);

    if (isPlannerMode) {
      createTimeline();
      showTimeline();
    }
    errorMessage.innerHTML = '';
  } catch (e: any) {
    errorMessage.innerHTML = `⚠️ ${e.message || '数据解析异常'}`;
    console.error(e);
  } finally {
    spinner.classList.add('hidden');
    generateButton.classList.remove('loading');
  }
}

async function setPin(args: any) {
  const { AdvancedMarkerElement } = await google.maps.importLibrary('marker');
  const point = { lat: Number(args.lat), lng: Number(args.lng) };
  points.push(point);
  bounds.extend(point);
  const marker = new AdvancedMarkerElement({ map, position: point, title: args.name });
  markers.push(marker);
  map.fitBounds(bounds);

  const content = document.createElement('div');
  content.className = 'popup-inner-content';
  const weatherEmoji = args.weather === 'snowy' ? '❄️' : args.weather === 'rainy' ? '🌧️' : args.weather === 'cloudy' ? '☁️' : '☀️';
  content.innerHTML = `
    <div class="popup-title-row">
      <span class="popup-emoji">${weatherEmoji}</span>
      <span class="popup-name">${args.name}</span>
    </div>
    <div class="popup-body-text">${args.description}</div>
    <div class="popup-footer-tag">${args.time} · TOP ${args.rank}</div>
  `;
  const popup = new (window as any).Popup(new google.maps.LatLng(point), content);
  popup.setMap(map);
  const locInfo = { ...args, position: new google.maps.LatLng(point), popup, content };
  popUps.push(locInfo);
  if (isPlannerMode) dayPlanItinerary.push(locInfo);
}

function createLocationCards() {
  cardContainer.innerHTML = '';
  carouselIndicators.innerHTML = '';
  cardCarousel.style.display = 'block';

  popUps.forEach((loc, index) => {
    const card = document.createElement('div');
    card.className = 'location-card';
    const weatherIcon = loc.weather === 'snowy' ? 'fa-snowflake' : loc.weather === 'rainy' ? 'fa-cloud-showers-heavy' : loc.weather === 'stormy' ? 'fa-bolt' : 'fa-sun';
    card.innerHTML = `
      <div class="card-rank-badge">${isPlannerMode ? '环节 ' + loc.sequence : 'TOP ' + loc.rank}</div>
      <div class="card-weather-overlay"><i class="fas ${weatherIcon}"></i> ${loc.temp || '--'}°C</div>
      <div class="card-content">
        <h3 class="card-title">${loc.name}</h3>
        <p class="card-description">${loc.description}</p>
        <div class="card-footer-info">
           <span class="card-time-tag"><i class="far fa-clock"></i> ${loc.time}</span>
        </div>
      </div>
    `;
    card.onclick = () => highlightCard(index, true);
    cardContainer.appendChild(card);
    const dot = document.createElement('div');
    dot.className = 'carousel-dot';
    dot.onclick = (e) => { e.stopPropagation(); highlightCard(index, true); };
    carouselIndicators.appendChild(dot);
  });
}

function renderGroundingSources() {
  if (groundingSources.length === 0) return;
  const existingSourceList = timeline.querySelector('.grounding-sources-list');
  if (existingSourceList) existingSourceList.remove();

  const sourceDiv = document.createElement('div');
  sourceDiv.className = 'grounding-sources-list';
  sourceDiv.innerHTML = `<h4><i class="fas fa-search-location"></i> 深度参考源:</h4>`;
  const list = document.createElement('div');
  list.className = 'source-chips';
  groundingSources.slice(0, 12).forEach(s => {
    const chip = document.createElement('a');
    chip.href = s.uri;
    chip.target = "_blank";
    chip.className = 'source-chip';
    chip.innerHTML = `<i class="fas fa-quote-left"></i> ${s.title || '打卡笔记'}`;
    list.appendChild(chip);
  });
  sourceDiv.appendChild(list);
  timeline.prepend(sourceDiv);
}

function highlightCard(index: number, shouldScroll: boolean = false) {
  if (activeCardIndex === index && !shouldScroll) return;
  activeCardIndex = index;
  const cards = cardContainer.querySelectorAll('.location-card');
  cards.forEach((c, i) => c.classList.toggle('card-active', i === index));
  const dots = carouselIndicators.querySelectorAll('.carousel-dot');
  dots.forEach((d, i) => d.classList.toggle('active', i === index));
  const loc = popUps[index];
  if (loc) {
    map.panTo(loc.position);
    startWeatherAnimation(loc.weather);
  }
  if (shouldScroll) {
    const targetCard = cards[index] as HTMLElement;
    if (targetCard) {
      cardContainer.scrollTo({
        left: targetCard.offsetLeft - (cardContainer.offsetWidth / 2) + (targetCard.offsetWidth / 2),
        behavior: 'smooth'
      });
    }
  }
}

cardContainer.addEventListener('scroll', () => {
  const scrollTimeout = window.setTimeout(() => {
    const containerWidth = cardContainer.offsetWidth;
    const center = cardContainer.scrollLeft + containerWidth / 2;
    const cards = cardContainer.querySelectorAll('.location-card');
    let closestIndex = 0;
    let minDistance = Infinity;
    cards.forEach((card, i) => {
      const cardCenter = (card as HTMLElement).offsetLeft + (card as HTMLElement).offsetWidth / 2;
      const distance = Math.abs(center - cardCenter);
      if (distance < minDistance) { minDistance = distance; closestIndex = i; }
    });
    if (closestIndex !== activeCardIndex) highlightCard(closestIndex, false);
  }, 100);
});

function createTimeline() {
  if (!timeline) return;
  timeline.innerHTML = '';
  renderGroundingSources(); 
  dayPlanItinerary.forEach((item, index) => {
    const div = document.createElement('div');
    div.className = 'timeline-item';
    div.draggable = true;
    div.onclick = () => highlightCard(popUps.indexOf(item), true);
    div.innerHTML = `
      <div class="drag-handle"><i class="fas fa-grip-vertical"></i></div>
      <div class="timeline-time">${item.time}</div>
      <div class="timeline-connector"><div class="timeline-dot"></div><div class="timeline-line"></div></div>
      <div class="timeline-content">
        <div class="timeline-title">${item.name}</div>
        <div class="timeline-description">${item.description}</div>
      </div>
    `;
    timeline.appendChild(div);
  });
}

function showTimeline() {
  timelineContainer.style.display = 'block';
  setTimeout(() => {
    timelineContainer.classList.add('visible');
    mapContainer.classList.add('shifted');
    reopenTimelineBtn.classList.add('hidden');
  }, 10);
}

function hideTimeline() {
  timelineContainer.classList.remove('visible');
  mapContainer.classList.remove('shifted');
  setTimeout(() => { 
    timelineContainer.style.display = 'none'; 
    if (dayPlanItinerary.length > 0) reopenTimelineBtn.classList.remove('hidden');
  }, 300);
}

function exportItinerary() {
  if (dayPlanItinerary.length === 0) return;
  let text = `您的行程计划\n\n`;
  dayPlanItinerary.forEach((item, i) => {
    text += `${i + 1}. [${item.time}] ${item.name}\n`;
    text += `   描述: ${item.description}\n\n`;
  });

  const blob = new Blob([text], { type: 'text/plain' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `我的行程计划.txt`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

function restart() {
  points = [];
  bounds = new google.maps.LatLngBounds();
  markers.forEach(m => m.setMap(null));
  markers = [];
  popUps.forEach(p => p.popup.setMap(null));
  popUps = [];
  dayPlanItinerary = [];
  groundingSources = [];
  cardContainer.innerHTML = '';
  cardCarousel.style.display = 'none';
  reopenTimelineBtn.classList.add('hidden');
  if (animationId) cancelAnimationFrame(animationId);
  if (ctx) ctx.clearRect(0, 0, canvas.width, canvas.height);
  hideTimeline();
}

toggleUiBtn.addEventListener('click', () => {
  isUiHidden = !isUiHidden;
  searchContainer.classList.toggle('ui-hidden', isUiHidden);
  toggleUiBtn.innerHTML = isUiHidden ? '<i class="fas fa-eye"></i>' : '<i class="fas fa-eye-slash"></i>';
});

reopenTimelineBtn.addEventListener('click', showTimeline);
exportBtn.addEventListener('click', exportItinerary);

promptInput.addEventListener('keydown', e => {
  if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); sendText(promptInput.value); }
});

generateButton.addEventListener('click', () => sendText(promptInput.value));
resetButton.addEventListener('click', restart);
closeTimelineButton.addEventListener('click', hideTimeline);
plannerModeToggle.addEventListener('change', () => {
  isPlannerMode = plannerModeToggle.checked;
  promptInput.placeholder = isPlannerMode ? "输入目的地，生成深度行程..." : "输入目的地，发现打卡清单...";
  if (!isPlannerMode) hideTimeline();
});

