.carousel-indicators { display: flex; justify-content: center; gap: 8px; margin-top: 15px; }
.carousel-dot { width: 8px; height: 8px; background: rgba(255,255,255,0.4); border-radius: 50%; transition: 0.3s; cursor: pointer; }
.carousel-dot.active { background: #ff5722; width: 24px; border-radius: 4px; }

/* Timeline & Sources Styling */
.timeline-container {
  position: fixed; right: 0; top: 0; width: 360px; height: 100%; background: white;
  z-index: 1000; display: none; padding: 0; box-shadow: -8px 0 30px rgba(0,0,0,0.15); 
  transition: transform 0.4s cubic-bezier(0.4, 0, 0.2, 1);
  transform: translateX(100%);
}

.timeline-container.visible { transform: translateX(0); }
.timeline-header { 
  padding: 20px; 
  border-bottom: 1px solid #f0f0f0; 
  display: flex; 
  justify-content: space-between; 
  align-items: center; 
  background: #fff; 
}
.timeline-header h3 { font-size: 18px; font-weight: 800; color: #1a1a1a; }
.header-actions { display: flex; gap: 10px; }

.action-btn, .close-button {
  background: none;
  border: none;
  font-size: 18px;
  color: #666;
  cursor: pointer;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: 0.2s;
}

.action-btn:hover { background: #f5f5f5; color: #ff5722; }
.close-button:hover { background: #fee; color: #f44; }

.timeline { padding: 20px; overflow-y: auto; height: calc(100% - 80px); }
.timeline-item { 
  display: flex; 
  margin-bottom: 20px; 
  cursor: pointer; 
  transition: 0.2s; 
  position: relative;
  padding: 15px;
  border-radius: 12px;
  background: #fff;
  border: 1px solid transparent;
}
.timeline-item:hover { background: #fdfdfd; border-color: #eee; }
.timeline-item.active-item { 
  background: #fff3e0; 
  border-color: #ffccbc; 
  box-shadow: 0 4px 12px rgba(255, 87, 34, 0.1); 
}

.timeline-rank-tag {
  font-size: 10px;
  background: #ff5722;
  color: white;
  padding: 2px 8px;
  border-radius: 4px;
  margin-left: 10px;
  font-weight: 800;
}

.drag-handle {
  display: flex;
  align-items: center;
  justify-content: center;
  color: #ddd;
  cursor: grab;
  margin-right: 15px;
  font-size: 16px;
}

.timeline-time { width: 75px; font-size: 13px; font-weight: 800; text-align: right; margin-right: 18px; color: #ff5722; padding-top: 4px; }
.timeline-connector { position: relative; width: 24px; }
.timeline-dot { width: 12px; height: 12px; background: #ff5722; border-radius: 50%; position: relative; z-index: 2; border: 3px solid white; box-shadow: 0 0 0 2px #ff5722; }
.timeline-line { position: absolute; left: 5px; top: 12px; bottom: -48px; width: 2px; background: #f0f0f0; }
.timeline-item:last-child .timeline-line { display: none; }
.timeline-content { flex: 1; transition: 0.2s; }
.timeline-title { font-size: 16px; font-weight: 800; color: #1a1a1a; margin-bottom: 6px; }
.timeline-description { font-size: 13px; color: #666; line-height: 1.6; }

.spinner {
  position: fixed; top: 50%; left: 50%; transform: translate(-50%, -50%);
  width: 60px; height: 60px; border: 6px solid rgba(255,255,255,0.1);
  border-top-color: #ff5722; border-radius: 50%; animation: spin 0.8s cubic-bezier(0.5, 0, 0.5, 1) infinite; z-index: 2000;
}
.hidden { display: none; }
@keyframes spin { to { transform: translate(-50%, -50%) rotate(360deg); } }
.error { color: #fff; background: rgba(255, 87, 34, 0.9); padding: 8px 16px; border-radius: 20px; text-align: center; margin-top: 15px; font-size: 14px; font-weight: 600; backdrop-filter: blur(6px); box-shadow: 0 4px 15px rgba(255, 87, 34, 0.3); }

.reset-button {
  position: absolute; top: 20px; right: 20px; width: 48px; height: 48px; border-radius: 50%;
  background: white; border: none; box-shadow: 0 6px 15px rgba(0,0,0,0.2); cursor: pointer; z-index: 100;
  display: flex; align-items: center; justify-content: center; font-size: 20px; transition: 0.3s;
}
.reset-button:hover { transform: scale(1.1) rotate(-45deg); color: #ff5722; }

/* Switch Overlay fix */
.slider.round { border-radius: 34px; }
.slider.round:before { border-radius: 50%; }

