import { FunctionDeclaration, GoogleGenAI, Type } from '@google/genai';

declare const google: any;

// Application state
let map: any;
let points: any[] = [];
let markers: any[] = [];
let popUps: any[] = [];
let bounds: any;
let activeCardIndex = 0;
let isPlannerMode = false;
let dayPlanItinerary: any[] = [];
let groundingSources: any[] = [];
let isUiHidden = false;
let polyline: any = null; // 用于绘制行程路径

// Weather System State
let canvas: HTMLCanvasElement;
let ctx: CanvasRenderingContext2D | null;
let animationId: number;
let particles: any[] = [];

// DOM Elements
const searchContainer = document.querySelector('#search-container') as HTMLDivElement;
const generateButton = document.querySelector('#generate') as HTMLButtonElement;
const resetButton = document.querySelector('#reset') as HTMLButtonElement;
const cardContainer = document.querySelector('#card-container') as HTMLDivElement;
const carouselIndicators = document.querySelector('#carousel-indicators') as HTMLDivElement;
const cardCarousel = document.querySelector('.card-carousel') as HTMLDivElement;
const plannerModeToggle = document.querySelector('#planner-mode-toggle') as HTMLInputElement;
const timelineContainer = document.querySelector('#timeline-container') as HTMLDivElement;
const timeline = document.querySelector('#timeline') as HTMLDivElement;
const spinner = document.querySelector('#spinner') as HTMLDivElement;
const errorMessage = document.querySelector('#error-message') as HTMLDivElement;
const promptInput = document.querySelector('#prompt-input') as HTMLTextAreaElement;
const closeTimelineButton = document.querySelector('#close-timeline') as HTMLButtonElement;
const toggleUiBtn = document.querySelector('#toggle-search-ui') as HTMLButtonElement;
const reopenTimelineBtn = document.querySelector('#reopen-timeline') as HTMLButtonElement;
const exportBtn = document.querySelector('#export-itinerary') as HTMLButtonElement;

/**
 * 初始化天气渲染
 */
function initWeatherCanvas() {
  if (document.getElementById('weather-canvas')) return;
  canvas = document.createElement('canvas');
  canvas.id = 'weather-canvas';
  canvas.style.position = 'absolute';
  canvas.style.top = '0';
  canvas.style.left = '0';
  canvas.style.width = '100%';
  canvas.style.height = '100%';
  canvas.style.pointerEvents = 'none';
  canvas.style.zIndex = '5';
  document.getElementById('map-container')?.appendChild(canvas);
  ctx = canvas.getContext('2d');
  window.addEventListener('resize', () => {
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
  });
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;
}

function startWeatherAnimation(type: string) {
  if (!ctx) return;
  particles = [];
  if (animationId) cancelAnimationFrame(animationId);
  const createParticle = () => {
    if (type === 'rainy' || type === 'stormy') return { x: Math.random() * canvas.width, y: Math.random() * canvas.height, l: Math.random() * 20 + 10, v: Math.random() * 10 + 10 };
    if (type === 'snowy') return { x: Math.random() * canvas.width, y: Math.random() * canvas.height, r: Math.random() * 3 + 1, v: Math.random() * 2 + 1, wind: Math.random() * 1 - 0.5 };
    return null;
  };
  if (['rainy', 'stormy', 'snowy'].includes(type)) {
    for (let i = 0; i < 150; i++) { const p = createParticle(); if (p) particles.push(p); }
  }
  function animate() {
    if (!ctx) return;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    if (type === 'rainy' || type === 'stormy') {
      ctx.strokeStyle = 'rgba(174, 194, 224, 0.6)';
      ctx.lineWidth = 1;
      particles.forEach(p => { ctx.beginPath(); ctx.moveTo(p.x, p.y); ctx.lineTo(p.x, p.y + p.l); ctx.stroke(); p.y += p.v; if (p.y > canvas.height) p.y = -p.l; });
    } else if (type === 'snowy') {
      ctx.fillStyle = 'rgba(255, 255, 255, 0.9)';
      particles.forEach(p => { ctx.beginPath(); ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2); ctx.fill(); p.y += p.v; p.x += p.wind; if (p.y > canvas.height) p.y = -p.r; });
    }
    animationId = requestAnimationFrame(animate);
  }
  animate();
}

/**
 * 初始化地图
 */
async function initApp() {
  try {
    const { Map } = await google.maps.importLibrary('maps');
    const { LatLngBounds } = await google.maps.importLibrary('core');
    bounds = new LatLngBounds();
    map = new Map(document.getElementById('map'), {
      center: { lat: 39.9042, lng: 116.4074 }, // 默认北京
      zoom: 11,
      mapId: '4504f8b37365c3d0',
      gestureHandling: 'greedy',
      disableDefaultUI: true
    });
    initWeatherCanvas();

    (window as any).Popup = class Popup extends google.maps.OverlayView {
      position: any; containerDiv: HTMLDivElement;
      constructor(position: any, content: HTMLElement) {
        super();
        this.position = position;
        this.containerDiv = document.createElement('div');
        this.containerDiv.classList.add('custom-map-popup');
        const bubble = document.createElement('div');
        bubble.classList.add('popup-bubble');
        bubble.appendChild(content);
        this.containerDiv.appendChild(bubble);
        const anchor = document.createElement('div');
        anchor.classList.add('popup-anchor');
        this.containerDiv.appendChild(anchor);
        google.maps.OverlayView.preventMapHitsAndGesturesFrom(this.containerDiv);
      }
      onAdd() { (this as any).getPanes().floatPane.appendChild(this.containerDiv); }
      onRemove() { if (this.containerDiv.parentElement) this.containerDiv.parentElement.removeChild(this.containerDiv); }
      draw() {
        const divPosition = (this as any).getProjection().fromLatLngToDivPixel(this.position);
        if (divPosition) { this.containerDiv.style.left = divPosition.x + 'px'; this.containerDiv.style.top = divPosition.y + 'px'; }
      }
    };
  } catch (err) {
    errorMessage.innerText = '地图初始化失败，请重试。';
  }
}

initApp();

// Gemini 系统指令
const locationFunctionDeclaration: FunctionDeclaration = {
  name: 'location',
  parameters: {
    type: Type.OBJECT,
    description: '标注地点信息。行程规划时必须按时间顺序分多次调用。',
    properties: {
      name: { type: Type.STRING, description: '地点全称' },
      description: { type: Type.STRING, description: '地点介绍，必须包含来自搜索的最新评价。' },
      lat: { type: Type.STRING, description: '纬度' },
      lng: { type: Type.STRING, description: '经度' },
      weather: { type: Type.STRING, description: 'sunny, rainy, snowy, cloudy' },
      temp: { type: Type.STRING, description: '当前气温' },
      time: { type: Type.STRING, description: '建议游玩时间段' },
      sequence: { type: Type.NUMBER, description: '行程中的次序' },
      rank: { type: Type.NUMBER, description: '热度排名' },
    },
    required: ['name', 'description', 'lat', 'lng', 'weather', 'rank', 'sequence', 'time'],
  },
};

const systemInstructions = `你是一个融合了实时搜索与资深旅游达人知识的智能导游。
你的核心任务是：
1. **深度搜索优先**：先调用 googleSearch 检索目标城市（如北京）最新的社交媒体攻略（小红书/微博/抖音），寻找当前最火但“不踩雷”的地点。
2. **逻辑空间建模**：结合经典必去地标与搜索到的网红点，规划出一条空间路径最短、体验最丰富的行程。
3. **拒绝单一输出**：禁止给出一个笼统的总结，必须为每一个具体的游玩环节（如早餐、上午景点、午餐、下午景点、夜景）独立调用 location 函数。
4. **数据真实性**：所有的推荐必须有据可查，并在描述中体现搜索到的最新特色或提醒。`;

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

async function sendText(prompt: string) {
  if (!prompt.trim()) return;
  spinner.classList.remove('hidden');
  generateButton.classList.add('loading');
  errorMessage.innerHTML = '🔍 正在穿透全网检索最新真实的旅行资讯...';
  restart();

  try {
    const userPrompt = isPlannerMode 
      ? `针对"${prompt}"，请结合在线搜索，规划一个逻辑严密的 6 站式全天行程。要求：每个地点都必须独立调用 location 函数，严禁只给一个概括。`
      : `针对"${prompt}"，请搜索并推荐 5-8 个北京/当地最值得打卡的地点，包含描述和实时热度，每个地点独立调用 location 函数。`;

    const response = await ai.models.generateContentStream({
      model: 'gemini-3-pro-preview',
      contents: userPrompt,
      config: {
        systemInstruction: systemInstructions,
        tools: [{ googleSearch: {} }, { functionDeclarations: [locationFunctionDeclaration] }],
      },
    });

    let count = 0;
    for await (const chunk of response) {
      // 捕获并存储数据来源
      const metadata = (chunk as any).candidates?.[0]?.groundingMetadata;
      if (metadata?.groundingChunks) {
        metadata.groundingChunks.forEach((c: any) => {
          if (c.web && !groundingSources.find(s => s.uri === c.web.uri)) {
            groundingSources.push(c.web);
          }
        });
      }

      const fns = chunk.functionCalls ?? [];
      for (const fn of fns) {
        if (fn.name === 'location') { 
          await setPin(fn.args); 
          count++;
          errorMessage.innerHTML = `📍 已锁定第 ${count} 个目的地：${fn.args.name}`;
        }
      }
    }

    if (count === 0) throw new Error('未能获取有效推荐，请尝试输入更具体的目的地（如：北京行程建议）。');

    // 排序与渲染
    popUps.sort((a, b) => isPlannerMode ? (a.sequence - b.sequence) : (a.rank - b.rank));
    createLocationCards();
    renderGroundingSources();
    if (isPlannerMode) { drawRoute(); createTimeline(); showTimeline(); }
    highlightCard(0, true);
    errorMessage.innerHTML = '';
  } catch (e: any) {
    errorMessage.innerHTML = `⚠️ ${e.message}`;
  } finally {
    spinner.classList.add('hidden');
    generateButton.classList.remove('loading');
  }
}

async function setPin(args: any) {
  const { AdvancedMarkerElement } = await google.maps.importLibrary('marker');
  const point = { lat: Number(args.lat), lng: Number(args.lng) };
  points.push(point);
  bounds.extend(point);
  const marker = new AdvancedMarkerElement({ map, position: point, title: args.name, gmpClickable: true });
  markers.push(marker);
  map.fitBounds(bounds);

  const content = document.createElement('div');
  content.className = 'popup-inner-content';
  content.innerHTML = `
    <div class="popup-title-row">
      <span class="popup-emoji">${args.weather === 'rainy' ? '🌧️' : '☀️'}</span>
      <span class="popup-name">${args.name}</span>
    </div>
    <div class="popup-body-text">${args.description}</div>
    <div class="popup-footer-tag">建议：${args.time}</div>
  `;
  const popup = new (window as any).Popup(new google.maps.LatLng(point), content);
  const locInfo = { ...args, position: new google.maps.LatLng(point), popup, marker };
  popUps.push(locInfo);
  if (isPlannerMode) dayPlanItinerary.push(locInfo);

  marker.addListener('click', () => { highlightCard(popUps.indexOf(locInfo), true); });
}

function drawRoute() {
  if (popUps.length < 2) return;
  const path = popUps.map(p => p.position);
  polyline = new google.maps.Polyline({
    path: path,
    geodesic: true,
    strokeColor: '#ff5722',
    strokeOpacity: 0.8,
    strokeWeight: 4,
    icons: [{ icon: { path: google.maps.SymbolPath.FORWARD_CLOSED_ARROW }, offset: '100%', repeat: '100px' }],
    map: map
  });
}

function createLocationCards() {
  cardContainer.innerHTML = ''; carouselIndicators.innerHTML = '';
  cardCarousel.style.display = 'block';
  popUps.forEach((loc, index) => {
    const card = document.createElement('div');
    card.className = 'location-card';
    card.innerHTML = `
      <div class="card-rank-badge">${isPlannerMode ? '站 ' + loc.sequence : 'TOP ' + loc.rank}</div>
      <div class="card-content">
        <h3 class="card-title">${loc.name}</h3>
        <p class="card-description">${loc.description}</p>
        <div class="card-time-tag"><i class="far fa-clock"></i> ${loc.time}</div>
      </div>
    `;
    card.onclick = () => highlightCard(index, true);
    cardContainer.appendChild(card);
    const dot = document.createElement('div');
    dot.className = 'carousel-dot';
    dot.onclick = () => highlightCard(index, true);
    carouselIndicators.appendChild(dot);
  });
}

function renderGroundingSources() {
  if (groundingSources.length === 0) return;
  const existing = timeline.querySelector('.grounding-sources-section');
  if (existing) existing.remove();

  const section = document.createElement('div');
  section.className = 'grounding-sources-section';
  section.innerHTML = `<h4><i class="fas fa-shield-alt"></i> 基于全网真实数据合成:</h4>`;
  const chips = document.createElement('div');
  chips.className = 'source-chips';
  groundingSources.slice(0, 8).forEach(s => {
    const a = document.createElement('a');
    a.href = s.uri; a.target = "_blank"; a.className = 'source-chip';
    a.innerHTML = `<i class="fas fa-link"></i> ${s.title || '来源笔记'}`;
    chips.appendChild(a);
  });
  section.appendChild(chips);
  timeline.prepend(section);
}

function highlightCard(index: number, shouldScroll: boolean = false) {
  // 核心：关闭所有 Popup，防止阻挡
  popUps.forEach(p => p.popup.setMap(null));

  activeCardIndex = index;
  const cards = cardContainer.querySelectorAll('.location-card');
  cards.forEach((c, i) => c.classList.toggle('card-active', i === index));
  const dots = carouselIndicators.querySelectorAll('.carousel-dot');
  dots.forEach((d, i) => d.classList.toggle('active', i === index));

  const loc = popUps[index];
  if (loc) {
    loc.popup.setMap(map); // 只打开当前的
    map.panTo(loc.position);
    startWeatherAnimation(loc.weather);
    const timelineItems = timeline.querySelectorAll('.timeline-item');
    timelineItems.forEach((ti, i) => ti.classList.toggle('active-item', i === index));
    if (timelineContainer.classList.contains('visible') && timelineItems[index]) {
      timelineItems[index].scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
  }

  if (shouldScroll && cards[index]) {
    cardContainer.scrollTo({ left: (cards[index] as HTMLElement).offsetLeft - (cardContainer.offsetWidth / 2) + 130, behavior: 'smooth' });
  }
}

function createTimeline() {
  const list = timeline.querySelector('.timeline-list') || document.createElement('div');
  list.className = 'timeline-list';
  list.innerHTML = '';
  dayPlanItinerary.forEach((item, index) => {
    const div = document.createElement('div');
    div.className = 'timeline-item';
    div.onclick = () => highlightCard(index, true);
    div.innerHTML = `
      <div class="timeline-time">${item.time}</div>
      <div class="timeline-connector"><div class="timeline-dot"></div><div class="timeline-line"></div></div>
      <div class="timeline-content">
        <div class="timeline-title">${item.name}</div>
        <div class="timeline-description">${item.description}</div>
      </div>
    `;
    list.appendChild(div);
  });
  if (!timeline.contains(list)) timeline.appendChild(list);
}

function showTimeline() {
  timelineContainer.style.display = 'block';
  setTimeout(() => { timelineContainer.classList.add('visible'); mapContainer.classList.add('shifted'); reopenTimelineBtn.classList.add('hidden'); }, 10);
}

function hideTimeline() {
  timelineContainer.classList.remove('visible'); mapContainer.classList.remove('shifted');
  setTimeout(() => { timelineContainer.style.display = 'none'; if (dayPlanItinerary.length > 0) reopenTimelineBtn.classList.remove('hidden'); }, 300);
}

function restart() {
  points = []; markers.forEach(m => m.setMap(null)); markers = [];
  popUps.forEach(p => p.popup.setMap(null)); popUps = [];
  dayPlanItinerary = []; groundingSources = [];
  if (polyline) { polyline.setMap(null); polyline = null; }
  cardContainer.innerHTML = ''; cardCarousel.style.display = 'none';
  reopenTimelineBtn.classList.add('hidden');
  if (animationId) cancelAnimationFrame(animationId);
  hideTimeline();
  bounds = new google.maps.LatLngBounds();
}

// 事件绑定
toggleUiBtn.addEventListener('click', () => { isUiHidden = !isUiHidden; searchContainer.classList.toggle('ui-hidden', isUiHidden); toggleUiBtn.innerHTML = isUiHidden ? '<i class="fas fa-eye"></i>' : '<i class="fas fa-eye-slash"></i>'; });
reopenTimelineBtn.addEventListener('click', showTimeline);
exportBtn.addEventListener('click', () => {
  let txt = "我的行程计划\n\n";
  dayPlanItinerary.forEach((item, i) => txt += `${i + 1}. [${item.time}] ${item.name}\n   ${item.description}\n\n`);
  const blob = new Blob([txt], { type: 'text/plain' });
  const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = "行程清单.txt"; a.click();
});
closeTimelineButton.addEventListener('click', hideTimeline);
promptInput.addEventListener('keydown', e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); sendText(promptInput.value); } });
generateButton.addEventListener('click', () => sendText(promptInput.value));
resetButton.addEventListener('click', restart);
plannerModeToggle.addEventListener('change', () => { isPlannerMode = plannerModeToggle.checked; promptInput.placeholder = isPlannerMode ? "输入目的地，生成深度行程..." : "探索最火打卡清单..."; });

@import url(https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css);

* { box-sizing: border-box; padding: 0; margin: 0; font-family: 'Segoe UI', Roboto, 'PingFang SC', sans-serif; }
body { height: 100vh; overflow: hidden; background: #000; }

.map-container { position: relative; height: 100%; width: 100%; transition: 0.4s cubic-bezier(0.4, 0, 0.2, 1); }
.map-container.shifted { transform: translateX(-180px); }

/* Popup & Markers */
.custom-map-popup { position: absolute; transform: translate(-50%, -100%); padding-bottom: 15px; z-index: 2000; animation: bounceIn 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275); }
@keyframes bounceIn { from { opacity: 0; transform: translate(-50%, -80%) scale(0.8); } to { opacity: 1; transform: translate(-50%, -100%) scale(1); } }
.popup-bubble { background: white; padding: 15px; border-radius: 16px; box-shadow: 0 10px 30px rgba(0,0,0,0.3); min-width: 220px; max-width: 300px; border: 1px solid rgba(0,0,0,0.05); }
.popup-anchor { position: absolute; bottom: 0; left: 50%; transform: translateX(-50%); width: 0; height: 0; border-left: 10px solid transparent; border-right: 10px solid transparent; border-top: 15px solid white; }
.popup-name { font-weight: 800; font-size: 16px; color: #1a1a1a; margin-left: 5px; }
.popup-body-text { font-size: 13px; line-height: 1.6; color: #555; margin-top: 8px; }
.popup-footer-tag { font-size: 11px; background: #fff3e0; color: #e65100; padding: 3px 10px; border-radius: 8px; margin-top: 10px; display: inline-block; font-weight: 700; }

/* Data Sources Section */
.grounding-sources-section { background: #f8f9fa; padding: 15px; border-radius: 12px; margin-bottom: 20px; border-left: 4px solid #ff5722; }
.grounding-sources-section h4 { font-size: 13px; color: #333; margin-bottom: 10px; font-weight: 800; }
.source-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.source-chip { background: white; border: 1px solid #ddd; padding: 4px 12px; border-radius: 20px; font-size: 11px; color: #555; text-decoration: none; transition: 0.2s; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 140px; }
.source-chip:hover { border-color: #ff5722; color: #ff5722; transform: translateY(-2px); box-shadow: 0 4px 8px rgba(0,0,0,0.1); }

/* Floating UI */
.floating-control-btn { position: absolute; z-index: 105; width: 46px; height: 46px; border-radius: 50%; background: white; border: none; box-shadow: 0 4px 15px rgba(0,0,0,0.2); cursor: pointer; display: flex; align-items: center; justify-content: center; font-size: 18px; transition: 0.3s; }
.toggle-ui-btn { top: 20px; left: 20px; }
.reopen-timeline-btn { top: 80px; right: 20px; background: #ff5722; color: white; }
.search-container { position: absolute; top: 20px; left: 50%; transform: translateX(-50%); z-index: 100; width: 90%; max-width: 520px; transition: 0.4s; }
.search-container.ui-hidden { transform: translate(-50%, -150%); opacity: 0; pointer-events: none; }
.search-bar { display: flex; background: white; padding: 12px 20px; border-radius: 35px; box-shadow: 0 10px 40px rgba(0,0,0,0.4); }
#prompt-input { flex: 1; border: none; outline: none; font-size: 16px; resize: none; height: 32px; line-height: 22px; }
.search-button { background: #ff5722; color: white; border: none; width: 40px; height: 40px; border-radius: 50%; cursor: pointer; display: flex; align-items: center; justify-content: center; transition: 0.3s; }
.search-button.loading { background: #ccc; pointer-events: none; animation: pulse 1s infinite; }

/* Timeline Panel */
.timeline-container { position: fixed; right: 0; top: 0; width: 380px; height: 100%; background: white; z-index: 1000; display: none; box-shadow: -10px 0 40px rgba(0,0,0,0.2); transition: 0.4s; transform: translateX(100%); }
.timeline-container.visible { transform: translateX(0); }
.timeline-header { padding: 25px 20px; border-bottom: 1px solid #eee; display: flex; justify-content: space-between; align-items: center; }
.timeline { padding: 20px; overflow-y: auto; height: calc(100% - 85px); }
.timeline-item { display: flex; margin-bottom: 25px; cursor: pointer; padding: 15px; border-radius: 12px; transition: 0.2s; border: 1px solid transparent; }
.timeline-item.active-item { background: #fff8f1; border-color: #ffe0b2; box-shadow: 0 4px 15px rgba(255,87,34,0.1); }
.timeline-time { width: 70px; font-weight: 800; color: #ff5722; font-size: 13px; }
.timeline-connector { width: 30px; position: relative; }
.timeline-dot { width: 12px; height: 12px; background: #ff5722; border-radius: 50%; border: 3px solid white; box-shadow: 0 0 0 2px #ff5722; z-index: 2; position: relative; }
.timeline-line { position: absolute; left: 5px; top: 12px; bottom: -40px; width: 2px; background: #eee; }
.timeline-item:last-child .timeline-line { display: none; }
.timeline-title { font-weight: 800; font-size: 16px; margin-bottom: 6px; }
.timeline-description { font-size: 13px; color: #666; line-height: 1.6; }

/* Carousel */
.card-carousel { position: absolute; bottom: 35px; width: 100%; z-index: 100; display: none; }
.card-container { display: flex; overflow-x: auto; padding: 15px 0; gap: 20px; scroll-snap-type: x mandatory; padding-left: calc(50% - 130px); padding-right: calc(50% - 130px); scrollbar-width: none; }
.card-container::-webkit-scrollbar { display: none; }
.location-card { flex: 0 0 260px; background: white; border-radius: 20px; padding: 20px; box-shadow: 0 10px 30px rgba(0,0,0,0.3); cursor: pointer; scroll-snap-align: center; border: 2px solid transparent; transition: 0.3s; }
.location-card.card-active { transform: scale(1.1); border-color: #ff5722; }
.card-rank-badge { position: absolute; top: -12px; left: 15px; background: linear-gradient(135deg, #ff9800, #ff5722); color: white; padding: 4px 14px; border-radius: 20px; font-size: 12px; font-weight: 900; box-shadow: 0 4px 10px rgba(255,87,34,0.4); }
.carousel-dot { width: 8px; height: 8px; background: rgba(255,255,255,0.4); border-radius: 50%; cursor: pointer; }
.carousel-dot.active { background: #ff5722; width: 24px; border-radius: 5px; }

.spinner { position: fixed; top: 50%; left: 50%; transform: translate(-50%, -50%); border: 6px solid rgba(255,255,255,0.1); border-top-color: #ff5722; border-radius: 50%; width: 60px; height: 60px; animation: spin 0.8s linear infinite; z-index: 3000; }
@keyframes spin { to { transform: translate(-50%, -50%) rotate(360deg); } }
.error { color: #fff; background: rgba(255, 87, 34, 0.9); padding: 10px 20px; border-radius: 25px; text-align: center; margin-top: 15px; font-weight: 600; font-size: 14px; box-shadow: 0 5px 15px rgba(0,0,0,0.2); }
.reset-button { position: absolute; top: 20px; right: 20px; width: 46px; height: 46px; border-radius: 50%; background: white; border: none; box-shadow: 0 4px 15px rgba(0,0,0,0.2); cursor: pointer; z-index: 105; display: flex; align-items: center; justify-content: center; font-size: 18px; }
.hidden { display: none; }

