import { FunctionDeclaration, GoogleGenAI, Type } from '@google/genai';

declare const google: any;

// Application state
let map: any;
let points: any[] = [];
let markers: any[] = [];
let popUps: any[] = [];
let bounds: any;
let activeCardIndex = 0;
let isPlannerMode = false;
let dayPlanItinerary: any[] = [];
let groundingSources: any[] = [];
let isUiHidden = false;
let polyline: any = null;

// Weather System State
let canvas: HTMLCanvasElement;
let ctx: CanvasRenderingContext2D | null;
let animationId: number;
let particles: any[] = [];

// DOM Elements - Lazy Selectors
const getEl = <T extends HTMLElement>(id: string) => document.getElementById(id) as T;
const queryEl = <T extends HTMLElement>(selector: string) => document.querySelector(selector) as T;

/**
 * 初始化天气渲染
 */
function initWeatherCanvas() {
  const container = getEl('map-container');
  if (!container || getEl('weather-canvas')) return;

  canvas = document.createElement('canvas');
  canvas.id = 'weather-canvas';
  canvas.style.position = 'absolute';
  canvas.style.top = '0';
  canvas.style.left = '0';
  canvas.style.width = '100%';
  canvas.style.height = '100%';
  canvas.style.pointerEvents = 'none';
  canvas.style.zIndex = '5';
  container.appendChild(canvas);

  ctx = canvas.getContext('2d');
  window.addEventListener('resize', () => {
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
  });
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;
}

function startWeatherAnimation(type: string) {
  if (!ctx) return;
  particles = [];
  if (animationId) cancelAnimationFrame(animationId);
  const createParticle = () => {
    if (type === 'rainy' || type === 'stormy') return { x: Math.random() * canvas.width, y: Math.random() * canvas.height, l: Math.random() * 20 + 10, v: Math.random() * 10 + 10 };
    if (type === 'snowy') return { x: Math.random() * canvas.width, y: Math.random() * canvas.height, r: Math.random() * 3 + 1, v: Math.random() * 2 + 1, wind: Math.random() * 1 - 0.5 };
    return null;
  };
  if (['rainy', 'stormy', 'snowy'].includes(type)) {
    for (let i = 0; i < 150; i++) { const p = createParticle(); if (p) particles.push(p); }
  }
  function animate() {
    if (!ctx) return;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    if (type === 'rainy' || type === 'stormy') {
      ctx.strokeStyle = 'rgba(174, 194, 224, 0.6)';
      ctx.lineWidth = 1;
      particles.forEach(p => { ctx.beginPath(); ctx.moveTo(p.x, p.y); ctx.lineTo(p.x, p.y + p.l); ctx.stroke(); p.y += p.v; if (p.y > canvas.height) p.y = -p.l; });
    } else if (type === 'snowy') {
      ctx.fillStyle = 'rgba(255, 255, 255, 0.9)';
      particles.forEach(p => { ctx.beginPath(); ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2); ctx.fill(); p.y += p.v; p.x += p.wind; if (p.y > canvas.height) p.y = -p.r; });
    }
    animationId = requestAnimationFrame(animate);
  }
  animate();
}

/**
 * 初始化地图
 */
async function initApp() {
  const errorEl = getEl('error-message');
  try {
    // 确保加载库
    const { Map } = await google.maps.importLibrary('maps');
    const { LatLngBounds } = await google.maps.importLibrary('core');
    await google.maps.importLibrary('marker');

    bounds = new LatLngBounds();
    const mapElement = getEl('map');

    if (!mapElement) throw new Error("Map element not found");

    map = new Map(mapElement, {
      center: { lat: 39.9042, lng: 116.4074 }, 
      zoom: 11,
      mapId: '4504f8b37365c3d0', 
      gestureHandling: 'greedy',
      disableDefaultUI: true
    });

    initWeatherCanvas();
    setupPopupClass();
    bindEvents();

  } catch (err: any) {
    console.error("Map Init Error:", err);
    if (errorEl) errorEl.innerText = '地图初始化失败: ' + err.message;
  }
}

function setupPopupClass() {
  (window as any).Popup = class Popup extends google.maps.OverlayView {
    position: any; containerDiv: HTMLDivElement;
    constructor(position: any, content: HTMLElement) {
      super();
      this.position = position;
      this.containerDiv = document.createElement('div');
      this.containerDiv.classList.add('custom-map-popup');
      const bubble = document.createElement('div');
      bubble.classList.add('popup-bubble');
      bubble.appendChild(content);
      this.containerDiv.appendChild(bubble);
      const anchor = document.createElement('div');
      anchor.classList.add('popup-anchor');
      this.containerDiv.appendChild(anchor);
      google.maps.OverlayView.preventMapHitsAndGesturesFrom(this.containerDiv);
    }
    onAdd() { (this as any).getPanes().floatPane.appendChild(this.containerDiv); }
    onRemove() { if (this.containerDiv.parentElement) this.containerDiv.parentElement.removeChild(this.containerDiv); }
    draw() {
      const divPosition = (this as any).getProjection().fromLatLngToDivPixel(this.position);
      if (divPosition) { this.containerDiv.style.left = divPosition.x + 'px'; this.containerDiv.style.top = divPosition.y + 'px'; }
    }
  };
}

// Gemini 配置
const locationFunctionDeclaration: FunctionDeclaration = {
  name: 'location',
  parameters: {
    type: Type.OBJECT,
    description: '标注地点信息。行程规划时必须按时间顺序分多次调用。',
    properties: {
      name: { type: Type.STRING, description: '地点全称' },
      description: { type: Type.STRING, description: '地点介绍，包含来自搜索的最新评价。' },
      lat: { type: Type.STRING, description: '纬度' },
      lng: { type: Type.STRING, description: '经度' },
      weather: { type: Type.STRING, description: 'sunny, rainy, snowy, cloudy' },
      temp: { type: Type.STRING, description: '当前气温' },
      time: { type: Type.STRING, description: '建议游玩时间段' },
      sequence: { type: Type.NUMBER, description: '行程中的次序' },
      rank: { type: Type.NUMBER, description: '热度排名' },
    },
    required: ['name', 'description', 'lat', 'lng', 'weather', 'rank', 'sequence', 'time'],
  },
};

const systemInstructions = `你是一个融合了实时搜索与资深旅游达人知识的智能导游。
1. **深度搜索优先**：先调用 googleSearch 检索目标城市最新的社交媒体攻略（小红书/抖音等）。
2. **地理逻辑**：规划空间路径最短、体验最丰富的行程。
3. **分步标注**：为每一个具体的环节独立调用 location 函数。
4. **真实特色**：在描述中体现搜索到的最新特色或提醒。`;

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

async function sendText(prompt: string) {
  if (!prompt.trim()) return;
  const spinner = getEl('spinner');
  const generateBtn = getEl('generate') as HTMLButtonElement;
  const errorEl = getEl('error-message');

  spinner.classList.remove('hidden');
  generateBtn.classList.add('loading');
  if (errorEl) errorEl.innerHTML = '🔍 正在联网检索并规划行程...';

  restart();

  try {
    const userPrompt = isPlannerMode 
      ? `针对"${prompt}"，规划一个逻辑严密的 6 站式全天行程。每个地点必须独立调用 location 函数。`
      : `针对"${prompt}"，推荐 5-8 个当地最值得打卡的地点，每个地点独立调用 location 函数。`;

    const response = await ai.models.generateContentStream({
      model: 'gemini-3-pro-preview',
      contents: userPrompt,
      config: {
        systemInstruction: systemInstructions,
        tools: [{ googleSearch: {} }, { functionDeclarations: [locationFunctionDeclaration] }],
      },
    });

    let count = 0;
    for await (const chunk of response) {
      const metadata = (chunk as any).candidates?.[0]?.groundingMetadata;
      if (metadata?.groundingChunks) {
        metadata.groundingChunks.forEach((c: any) => {
          if (c.web && !groundingSources.find(s => s.uri === c.web.uri)) groundingSources.push(c.web);
        });
      }
      const fns = chunk.functionCalls ?? [];
      for (const fn of fns) {
        if (fn.name === 'location') { 
          await setPin(fn.args); 
          count++;
          if (errorEl) errorEl.innerHTML = `📍 已定位：${fn.args.name} (${count})`;
        }
      }
    }

    if (count === 0) throw new Error('未能获取有效推荐，请尝试更具体的目的地。');

    popUps.sort((a, b) => isPlannerMode ? (a.sequence - b.sequence) : (a.rank - b.rank));
    createLocationCards();
    renderGroundingSources();
    if (isPlannerMode) { drawRoute(); createTimeline(); showTimeline(); }
    highlightCard(0, true);
    if (errorEl) errorEl.innerHTML = '';
  } catch (e: any) {
    if (errorEl) errorEl.innerHTML = `⚠️ ${e.message}`;
  } finally {
    spinner.classList.add('hidden');
    generateBtn.classList.remove('loading');
  }
}

async function setPin(args: any) {
  const { AdvancedMarkerElement } = await google.maps.importLibrary('marker');
  const point = { lat: Number(args.lat), lng: Number(args.lng) };
  points.push(point);
  bounds.extend(point);
  const marker = new AdvancedMarkerElement({ map, position: point, title: args.name, gmpClickable: true });
  markers.push(marker);
  map.fitBounds(bounds);

  const content = document.createElement('div');
  content.className = 'popup-inner-content';
  content.innerHTML = `
    <div class="popup-title-row"><span class="popup-emoji">📍</span><span class="popup-name">${args.name}</span></div>
    <div class="popup-body-text">${args.description}</div>
  `;
  const popup = new (window as any).Popup(new google.maps.LatLng(point), content);
  const locInfo = { ...args, position: new google.maps.LatLng(point), popup, marker };
  popUps.push(locInfo);
  if (isPlannerMode) dayPlanItinerary.push(locInfo);

  marker.addListener('click', () => { highlightCard(popUps.indexOf(locInfo), true); });
}

function drawRoute() {
  if (popUps.length < 2) return;
  polyline = new google.maps.Polyline({
    path: popUps.map(p => p.position),
    geodesic: true,
    strokeColor: '#ff5722',
    strokeOpacity: 0.8,
    strokeWeight: 4,
    map: map
  });
}

function createLocationCards() {
  const container = getEl('card-container');
  const indicators = getEl('carousel-indicators');
  const carousel = queryEl('.card-carousel');
  container.innerHTML = ''; indicators.innerHTML = '';
  carousel.style.display = 'block';
  popUps.forEach((loc, index) => {
    const card = document.createElement('div');
    card.className = 'location-card';
    card.innerHTML = `
      <div class="card-rank-badge">${isPlannerMode ? '第 ' + loc.sequence + ' 站' : 'TOP ' + loc.rank}</div>
      <h3 class="card-title">${loc.name}</h3>
      <p class="card-description">${loc.description}</p>
    `;
    card.onclick = () => highlightCard(index, true);
    container.appendChild(card);
    const dot = document.createElement('div');
    dot.className = 'carousel-dot';
    dot.onclick = () => highlightCard(index, true);
    indicators.appendChild(dot);
  });
}

function renderGroundingSources() {
  const timelineEl = getEl('timeline');
  if (groundingSources.length === 0 || !timelineEl) return;
  const existing = timelineEl.querySelector('.grounding-sources-section');
  if (existing) existing.remove();
  const section = document.createElement('div');
  section.className = 'grounding-sources-section';
  section.innerHTML = `<h4>数据参考来源:</h4>`;
  const chips = document.createElement('div');
  chips.className = 'source-chips';
  groundingSources.slice(0, 6).forEach(s => {
    const a = document.createElement('a'); a.href = s.uri; a.target = "_blank"; a.className = 'source-chip';
    a.innerText = s.title || '参考网页'; chips.appendChild(a);
  });
  section.appendChild(chips);
  timelineEl.prepend(section);
}

function highlightCard(index: number, shouldScroll: boolean = false) {
  popUps.forEach(p => p.popup.setMap(null));
  activeCardIndex = index;
  const container = getEl('card-container');
  const cards = container.querySelectorAll('.location-card');
  cards.forEach((c, i) => c.classList.toggle('card-active', i === index));
  const dots = getEl('carousel-indicators').querySelectorAll('.carousel-dot');
  dots.forEach((d, i) => d.classList.toggle('active', i === index));
  const loc = popUps[index];
  if (loc) {
    loc.popup.setMap(map);
    map.panTo(loc.position);
    startWeatherAnimation(loc.weather);
  }
  if (shouldScroll && cards[index]) {
    container.scrollTo({ left: (cards[index] as HTMLElement).offsetLeft - (container.offsetWidth / 2) + 130, behavior: 'smooth' });
  }
}

function createTimeline() {
  const timelineEl = getEl('timeline');
  let list = timelineEl.querySelector('.timeline-list');
  if (!list) { list = document.createElement('div'); list.className = 'timeline-list'; timelineEl.appendChild(list); }
  list.innerHTML = '';
  dayPlanItinerary.forEach((item, index) => {
    const div = document.createElement('div');
    div.className = 'timeline-item';
    div.onclick = () => highlightCard(index, true);
    div.innerHTML = `<div class="timeline-time">${item.time}</div><div class="timeline-content"><div class="timeline-title">${item.name}</div></div>`;
    list!.appendChild(div);
  });
}

function showTimeline() {
  const container = getEl('timeline-container');
  const mapCont = getEl('map-container');
  const reopenBtn = getEl('reopen-timeline');
  container.style.display = 'block';
  setTimeout(() => { container.classList.add('visible'); mapCont.classList.add('shifted'); reopenBtn.classList.add('hidden'); }, 10);
}

function hideTimeline() {
  const container = getEl('timeline-container');
  const mapCont = getEl('map-container');
  const reopenBtn = getEl('reopen-timeline');
  container.classList.remove('visible'); mapCont.classList.remove('shifted');
  setTimeout(() => { container.style.display = 'none'; if (dayPlanItinerary.length > 0) reopenBtn.classList.remove('hidden'); }, 300);
}

function restart() {
  points = []; markers.forEach(m => m.setMap(null)); markers = [];
  popUps.forEach(p => p.popup.setMap(null)); popUps = [];
  dayPlanItinerary = []; groundingSources = [];
  if (polyline) polyline.setMap(null);
  getEl('card-container').innerHTML = ''; queryEl('.card-carousel').style.display = 'none';
  getEl('reopen-timeline').classList.add('hidden');
  if (animationId) cancelAnimationFrame(animationId);
  hideTimeline();
  bounds = new google.maps.LatLngBounds();
}

function bindEvents() {
  getEl('toggle-search-ui').onclick = () => {
    isUiHidden = !isUiHidden;
    getEl('search-container').classList.toggle('ui-hidden', isUiHidden);
    getEl('toggle-search-ui').innerHTML = isUiHidden ? '<i class="fas fa-eye"></i>' : '<i class="fas fa-eye-slash"></i>';
  };
  getEl('reopen-timeline').onclick = showTimeline;
  getEl('export-itinerary').onclick = () => {
    let txt = "游玩行程清单\n\n";
    dayPlanItinerary.forEach((item, i) => txt += `${i + 1}. [${item.time}] ${item.name}\n`);
    const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([txt])); a.download = "行程.txt"; a.click();
  };
  getEl('close-timeline').onclick = hideTimeline;
  getEl('prompt-input').onkeydown = e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); sendText((getEl('prompt-input') as HTMLTextAreaElement).value); } };
  getEl('generate').onclick = () => sendText((getEl('prompt-input') as HTMLTextAreaElement).value);
  getEl('reset').onclick = restart;
  (getEl('planner-mode-toggle') as HTMLInputElement).onchange = e => { 
    isPlannerMode = (e.target as HTMLInputElement).checked; 
    (getEl('prompt-input') as HTMLTextAreaElement).placeholder = isPlannerMode ? "输入目的地，生成深度行程..." : "探索打卡点..."; 
  };
}

// 确保 DOM 加载后运行
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initApp);
} else {
  initApp();
}

@import url(https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css);

* { box-sizing: border-box; padding: 0; margin: 0; font-family: 'Segoe UI', Roboto, 'PingFang SC', sans-serif; }

/* 关键修复：确保视口高度被撑满 */
html, body { 
  height: 100%; 
  width: 100%; 
  overflow: hidden; 
  background: #000; 
}

.map-container { 
  position: relative; 
  height: 100%; 
  width: 100%; 
  transition: transform 0.4s cubic-bezier(0.4, 0, 0.2, 1); 
}

.map-container.shifted { 
  transform: translateX(-180px); 
}

#map { 
  height: 100%; 
  width: 100%; 
  background-color: #1a1a1a; 
}

@media (max-width: 768px) {
  .map-container.shifted { transform: translateX(0); }
}

/* Popup & Markers */
.custom-map-popup { position: absolute; transform: translate(-50%, -100%); padding-bottom: 15px; z-index: 2000; animation: bounceIn 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275); }
@keyframes bounceIn { from { opacity: 0; transform: translate(-50%, -80%) scale(0.8); } to { opacity: 1; transform: translate(-50%, -100%) scale(1); } }
.popup-bubble { background: white; padding: 12px; border-radius: 12px; box-shadow: 0 8px 25px rgba(0,0,0,0.3); min-width: 180px; max-width: 260px; border: 1px solid rgba(0,0,0,0.05); }
.popup-anchor { position: absolute; bottom: 0; left: 50%; transform: translateX(-50%); width: 0; height: 0; border-left: 8px solid transparent; border-right: 8px solid transparent; border-top: 12px solid white; }
.popup-name { font-weight: 800; font-size: 15px; color: #1a1a1a; margin-left: 4px; }
.popup-body-text { font-size: 12px; line-height: 1.5; color: #555; margin-top: 6px; }

/* Data Sources Section */
.grounding-sources-section { background: #f8f9fa; padding: 12px; border-radius: 10px; margin-bottom: 15px; border-left: 4px solid #ff5722; }
.grounding-sources-section h4 { font-size: 12px; color: #333; margin-bottom: 8px; font-weight: 800; }
.source-chips { display: flex; flex-wrap: wrap; gap: 6px; }
.source-chip { background: white; border: 1px solid #ddd; padding: 3px 10px; border-radius: 15px; font-size: 10px; color: #555; text-decoration: none; transition: 0.2s; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 120px; }
.source-chip:hover { border-color: #ff5722; color: #ff5722; transform: translateY(-1px); }

/* Floating UI */
.floating-control-btn { position: absolute; z-index: 105; width: 42px; height: 42px; border-radius: 50%; background: white; border: none; box-shadow: 0 4px 15px rgba(0,0,0,0.2); cursor: pointer; display: flex; align-items: center; justify-content: center; font-size: 16px; transition: 0.3s; }
.toggle-ui-btn { top: 20px; left: 20px; }
.reopen-timeline-btn { top: 72px; right: 20px; background: #ff5722; color: white; }
.search-container { position: absolute; top: 20px; left: 50%; transform: translateX(-50%); z-index: 100; width: 90%; max-width: 500px; transition: 0.4s; }
.search-container.ui-hidden { transform: translate(-50%, -150%); opacity: 0; pointer-events: none; }
.search-bar { display: flex; background: white; padding: 10px 18px; border-radius: 30px; box-shadow: 0 10px 35px rgba(0,0,0,0.4); }
#prompt-input { flex: 1; border: none; outline: none; font-size: 15px; resize: none; height: 28px; line-height: 28px; }
.search-button { background: #ff5722; color: white; border: none; width: 36px; height: 36px; border-radius: 50%; cursor: pointer; display: flex; align-items: center; justify-content: center; transition: 0.3s; }
.search-button.loading { background: #ccc; pointer-events: none; animation: pulse 1s infinite; }

/* Timeline Panel */
.timeline-container { position: fixed; right: 0; top: 0; width: 350px; height: 100%; background: white; z-index: 1000; display: none; box-shadow: -8px 0 35px rgba(0,0,0,0.2); transition: 0.4s; transform: translateX(100%); }
.timeline-container.visible { transform: translateX(0); }
.timeline-header { padding: 20px 15px; border-bottom: 1px solid #eee; display: flex; justify-content: space-between; align-items: center; }
.timeline { padding: 15px; overflow-y: auto; height: calc(100% - 75px); }
.timeline-item { display: flex; margin-bottom: 20px; cursor: pointer; padding: 12px; border-radius: 10px; transition: 0.2s; border: 1px solid transparent; }
.timeline-item.active-item { background: #fff8f1; border-color: #ffe0b2; }
.timeline-time { width: 60px; font-weight: 800; color: #ff5722; font-size: 12px; }
.timeline-connector { width: 25px; position: relative; }
.timeline-dot { width: 10px; height: 10px; background: #ff5722; border-radius: 50%; border: 2px solid white; box-shadow: 0 0 0 2px #ff5722; z-index: 2; position: relative; }
.timeline-line { position: absolute; left: 4px; top: 10px; bottom: -35px; width: 2px; background: #eee; }
.timeline-title { font-weight: 800; font-size: 15px; margin-bottom: 4px; }
.timeline-description { font-size: 12px; color: #666; line-height: 1.5; }

/* Carousel - Compact Style */
.card-carousel { position: absolute; bottom: 25px; width: 100%; z-index: 100; display: none; }
.card-container { 
  display: flex; 
  overflow-x: auto; 
  padding: 10px 0; 
  gap: 15px; 
  scroll-snap-type: x mandatory; 
  padding-left: calc(50% - 100px); 
  padding-right: calc(50% - 100px); 
  scrollbar-width: none; 
}
.card-container::-webkit-scrollbar { display: none; }

/* 关键修改：大幅度缩小卡片尺寸 */
.location-card { 
  flex: 0 0 200px; 
  background: white; 
  border-radius: 12px; 
  padding: 12px; 
  box-shadow: 0 6px 20px rgba(0,0,0,0.25); 
  cursor: pointer; 
  scroll-snap-align: center; 
  border: 2px solid transparent; 
  transition: 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275);
