  overflow: hidden;
}
.location-card.card-active { transform: scale(1.05); border-color: #ff5722; box-shadow: 0 10px 25px rgba(255,87,34,0.3); }
.card-rank-badge { position: absolute; top: -10px; left: 10px; background: linear-gradient(135deg, #ff9800, #ff5722); color: white; padding: 2px 10px; border-radius: 15px; font-size: 10px; font-weight: 900; z-index: 2; }
.card-title { font-weight: 800; font-size: 14px; margin-bottom: 4px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.card-description { font-size: 11px; color: #666; line-height: 1.4; display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }

.carousel-indicators { display: flex; justify-content: center; gap: 6px; margin-top: 8px; }
.carousel-dot { width: 6px; height: 6px; background: rgba(255,255,255,0.4); border-radius: 50%; cursor: pointer; }
.carousel-dot.active { background: #ff5722; width: 18px; border-radius: 4px; }

.spinner { position: fixed; top: 50%; left: 50%; transform: translate(-50%, -50%); border: 5px solid rgba(255,255,255,0.1); border-top-color: #ff5722; border-radius: 50%; width: 50px; height: 50px; animation: spin 0.8s linear infinite; z-index: 3000; }
.reset-button { position: absolute; top: 20px; right: 20px; width: 42px; height: 42px; border-radius: 50%; background: white; border: none; box-shadow: 0 4px 15px rgba(0,0,0,0.2); cursor: pointer; z-index: 105; display: flex; align-items: center; justify-content: center; font-size: 16px; }
.hidden { display: none; }

