@import url(https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css);

* { box-sizing: border-box; padding: 0; margin: 0; font-family: 'Segoe UI', Roboto, 'PingFang SC', sans-serif; }

html, body { height: 100%; width: 100%; overflow: hidden; background: #121212; }

.map-container { position: relative; height: 100%; width: 100%; transition: transform 0.6s cubic-bezier(0.2, 1, 0.3, 1); }
.map-container.shifted { transform: translateX(-180px); }
#map { height: 100%; width: 100%; background-color: #1a1a1a; }

/* 搜索容器优化 */
.search-container { 
  position: absolute; top: 20px; left: 50%; transform: translateX(-50%); 
  z-index: 110; width: 95%; max-width: 540px; 
}
.search-header-group { display: flex; justify-content: space-between; align-items: center; margin-bottom: 12px; }

.mode-toggle { 
  background: rgba(255, 255, 255, 0.95); padding: 8px 16px; border-radius: 20px; 
  display: flex; align-items: center; gap: 10px; box-shadow: 0 4px 15px rgba(0,0,0,0.15); backdrop-filter: blur(10px);
}
.mode-label { font-size: 13px; font-weight: 800; color: #1a1a1a; }

.preference-group { transition: 0.3s; }
.preference-select { 
  padding: 8px 14px; border-radius: 12px; border: none; background: #ff5722; color: white; 
  font-size: 12px; font-weight: 700; outline: none; box-shadow: 0 4px 12px rgba(255,87,34,0.35); cursor: pointer;
}

.search-bar-stack { 
  background: rgba(255, 255, 255, 0.98); border-radius: 24px; padding: 12px; 
  box-shadow: 0 15px 45px rgba(0,0,0,0.35); backdrop-filter: blur(20px);
  min-height: 80px; display: flex; flex-direction: column; justify-content: center;
}

/* 输入框样式修正 */
.search-bar { display: flex; align-items: center; padding: 4px 8px; }
#prompt-input { flex: 1; border: none; outline: none; font-size: 15px; resize: none; height: 40px; line-height: 40px; background: transparent; color: #333; }

.planner-fields { display: flex; flex-direction: column; gap: 10px; }
.planner-field { 
  display: flex; align-items: center; background: #f8f8f8; border-radius: 14px; padding: 12px 18px; 
  border: 1px solid rgba(0,0,0,0.05); transition: 0.3s;
}
.planner-field:focus-within { background: white; border-color: #ff5722; box-shadow: 0 0 0 4px rgba(255,87,34,0.1); }
.planner-field input { flex: 1; border: none; background: transparent; outline: none; font-size: 14px; margin-left: 12px; color: #333; font-weight: 500; }

.plan-main-button { 
  background: linear-gradient(135deg, #ff9800, #ff5722); color: white; border: none; 
  padding: 14px; border-radius: 14px; font-weight: 800; cursor: pointer; transition: 0.3s; margin-top: 5px;
  font-size: 15px;
}
.plan-main-button:hover { transform: translateY(-2px); box-shadow: 0 8px 25px rgba(255,87,34,0.45); }
.plan-main-button:active { transform: translateY(0); }

/* 加载状态文字优化 */
.error { 
  margin-top: 12px; font-size: 13px; font-weight: 700; text-align: center; color: #ff5722; 
  background: rgba(255,255,255,0.9); padding: 8px; border-radius: 12px; box-shadow: 0 4px 10px rgba(0,0,0,0.1);
}

/* 交通间隙卡片 */
.transit-info { 
  margin: 10px 0 20px 75px; padding: 8px 16px; background: #fdf2f0; border-radius: 10px; 
  font-size: 11px; color: #ff5722; display: flex; align-items: center; gap: 10px; width: fit-content;
  border: 1px solid rgba(255,87,34,0.15); font-weight: 700; position: relative;
}
.transit-info::before { content: ''; position: absolute; left: -22px; top: -15px; bottom: -15px; width: 2px; background: #eee; }

/* 底部卡片极致优化 */
.card-carousel { position: absolute; bottom: 20px; width: 100%; z-index: 100; pointer-events: none; }
.card-container { display: flex; overflow-x: auto; padding: 15px 0; gap: 15px; padding-left: calc(50% - 90px); padding-right: calc(50% - 90px); scroll-snap-type: x mandatory; pointer-events: auto; }
.card-container::-webkit-scrollbar { display: none; }

.location-card { 
  flex: 0 0 180px; background: white; border-radius: 14px; padding: 12px; 
  box-shadow: 0 8px 25px rgba(0,0,0,0.4); cursor: pointer; transition: 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275); 
  max-height: 110px; scroll-snap-align: center; border: 2px solid transparent; 
}
.location-card.card-active { transform: scale(1.1) translateY(-10px); border-color: #ff5722; z-index: 2; }
.card-title { font-size: 14px; font-weight: 800; margin-bottom: 4px; color: #1a1a1a; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.card-description { font-size: 11px; color: #666; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; line-height: 1.4; }

/* 其他 UI */
.switch { position: relative; display: inline-block; width: 40px; height: 20px; }
.switch input { opacity: 0; width: 0; height: 0; }
.slider { position: absolute; cursor: pointer; top: 0; left: 0; right: 0; bottom: 0; background-color: #ccc; transition: .4s; border-radius: 34px; }
.slider:before { position: absolute; content: ""; height: 14px; width: 14px; left: 3px; bottom: 3px; background-color: white; transition: .4s; border-radius: 50%; }
input:checked + .slider { background-color: #ff5722; }
input:checked + .slider:before { transform: translateX(20px); }

.timeline-container { position: fixed; right: 0; top: 0; width: 380px; height: 100%; background: white; z-index: 1000; transform: translateX(100%); transition: 0.5s; box-shadow: -15px 0 50px rgba(0,0,0,0.15); }
.timeline-container.visible { transform: translateX(0); }
.timeline-header { padding: 24px 20px; border-bottom: 1px solid #f0f0f0; display: flex; justify-content: space-between; align-items: center; }
.timeline { padding: 20px; overflow-y: auto; height: calc(100% - 85px); }

.hidden { display: none !important; }
.spinner { 
  position: fixed; top: 50%; left: 50%; transform: translate(-50%, -50%); 
  border: 4px solid rgba(255,255,255,0.2); border-top-color: #ff5722; border-radius: 50%; 
  width: 50px; height: 50px; animation: spin 1s cubic-bezier(0.5, 0.1, 0.4, 0.9) infinite; z-index: 2000; 
  box-shadow: 0 0 20px rgba(255,87,34,0.3);
}
@keyframes spin { to { transform: translate(-50%, -50%) rotate(360deg); } }

.floating-control-btn { position: absolute; z-index: 120; width: 44px; height: 44px; border-radius: 50%; background: white; border: none; box-shadow: 0 4px 15px rgba(0,0,0,0.2); cursor: pointer; display: flex; align-items: center; justify-content: center; font-size: 18px; transition: 0.3s; }
.floating-control-btn:hover { background: #ff5722; color: white; transform: scale(1.1); }
.toggle-ui-btn { top: 20px; left: 20px; }
.reopen-timeline-btn { top: 20px; right: 80px; background: #ff5722; color: white; }
.reset-button { position: absolute; top: 20px; right: 20px; }

/* Timeline Item Enhancements */
.timeline-item { cursor: pointer; padding: 12px; border-radius: 12px; transition: 0.2s; border-left: 3px solid transparent; margin-bottom: 5px; }
.timeline-item:hover { background: #fef4f2; border-left-color: #ff5722; }
.timeline-time { font-weight: 800; color: #ff5722; font-size: 12px; margin-bottom: 4px; }
.timeline-title { font-weight: 800; color: #1a1a1a; margin-bottom: 4px; }
.timeline-description { font-size: 12px; color: #666; line-height: 1.5; }

