  padding: 8px 14px; border-radius: 12px; border: none; background: #ff5722; color: white; 
  font-size: 12px; font-weight: 700; outline: none; box-shadow: 0 4px 12px rgba(255,87,34,0.35); cursor: pointer;
}

.search-bar-stack { 
  background: rgba(255, 255, 255, 0.98); border-radius: 24px; padding: 12px; 
  box-shadow: 0 15px 45px rgba(0,0,0,0.5); backdrop-filter: blur(20px);
