.timeline-container { position: fixed; right: 0; top: 0; width: 380px; height: 100%; background: white; z-index: 1000; transform: translateX(100%); transition: 0.5s cubic-bezier(0.165, 0.84, 0.44, 1); box-shadow: -15px 0 50px rgba(0,0,0,0.3); }
.timeline-container.visible { transform: translateX(0); }
