.reset-button { position: absolute; top: 20px; right: 20px; }

/* Custom Popup bubble */
.custom-map-popup { position: absolute; transform: translate(-50%, -100%); padding-bottom: 15px; z-index: 2000; animation: popupFadeIn 0.3s ease-out; }
@keyframes popupFadeIn { from { opacity: 0; transform: translate(-50%, -90%) scale(0.9); } to { opacity: 1; transform: translate(-50%, -100%) scale(1); } }
.popup-bubble { background: white; padding: 12px; border-radius: 12px; box-shadow: 0 8px 25px rgba(0,0,0,0.4); border: 1px solid #eee; }
.popup-anchor { position: absolute; bottom: 0; left: 50%; transform: translateX(-50%); width: 0; height: 0; border-left: 10px solid transparent; border-right: 10px solid transparent; border-top: 15px solid white; }

