      sequence: { type: Type.NUMBER, description: '顺序编号' },
      transit_hint: { type: Type.STRING, description: '交通说明（如：乘坐高铁G123号，或滴滴预计30元）。' },
      type: { type: Type.STRING, description: '节点类型：SIGHT (景点), FOOD (餐饮), TRANSIT (交通枢纽), HOTEL (住宿)' }
    },
    required: ['name', 'description', 'lat', 'lng', 'time'],
  },
};

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

async function handleRequest() {
  const userInput = (getEl('prompt-input') as HTMLTextAreaElement).value.trim();
  if (!userInput) {
    setStatus("请输入您的想法或目的地！", "error");
    return;
  }

  restart();
  getEl('spinner').classList.remove('hidden');

  const statusMsg = isPlannerMode 
    ? "🗺️ 正在联网检索马蜂窝、小红书、大众点评的实时攻略并规划行程..." 
    : "🌟 正在为您搜寻全网最火的打卡点与避雷指南...";
  setStatus(statusMsg, "loading");

  try {
    let systemInstruction = "";
    let promptPrefix = "";

    if (isPlannerMode) {
      const pref = (getEl('route-preference') as HTMLSelectElement).value;
      systemInstruction = `你是一个顶级深度旅游行程专家。
      1. 必须联网检索最新的交通信息（高铁车次、航班建议）和景点开放状态。
      2. 参考小红书、抖音、大众点评、马蜂窝的真实反馈，提供极具细节的文案。
      3. 必须包含具体的交通建议（如：从虹桥火车站出发）。
      4. 严格调用 location 函数生成每个节点。`;

      promptPrefix = `请基于“${userInput}”规划一份硬核细节的旅游行程。
      路径偏好：${pref === 'budget' ? '特种兵/性价比' : '深度体验/最优路径'}。
      要求：
      - 必须包含具体的交通班次（高铁/飞机）建议。
      - 每个地点的描述要包含：必打卡点、推荐美食、建议拍照角度。
      - 必须联网确认景点当前的真实评分和热度。`;
    } else {
      systemInstruction = "你是一个拥有全网旅游资讯的博主。推荐内容要包含真实评价、交通便利程度和避雷提醒。";
      promptPrefix = `请推荐 5-10 个关于“${userInput}”的宝藏地点。参考大众点评和小红书的热门评价。`;
    }

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: promptPrefix,
      config: {
        thinkingConfig: { thinkingBudget: isPlannerMode ? 3000 : 1000 },
        systemInstruction,
        tools: [{ googleSearch: {} }, { functionDeclarations: [locationFunctionDeclaration] }],
      },
    });

    // Handle Function Calls
    const calls = response.candidates?.[0]?.content?.parts.filter(p => p.functionCall) || [];
    for (const part of calls) {
      const fn = part.functionCall;
      if (fn && fn.name === 'location') await setPin(fn.args);
    }

    // Handle Grounding Metadata (Sources)
    const grounding = response.candidates?.[0]?.groundingMetadata;
    if (grounding && grounding.groundingChunks) {
      displaySources(grounding.groundingChunks);
    }

    if (dayPlanItinerary.length === 0) throw new Error("AI 未能检索到有效数据，请尝试更具体的描述。");

    if (isPlannerMode) {
      dayPlanItinerary.sort((a, b) => (a.sequence || 0) - (b.sequence || 0));
      drawRoute();
      createTimeline();
      showTimeline();
    }

    createCards();
    highlightCard(0, true);
    setStatus("", "hidden");
  } catch (e: any) {
    setStatus("⚠️ " + e.message, "error");
  } finally {
    getEl('spinner').classList.add('hidden'); // Ensure spinner hides
  }
}

function displaySources(chunks: any[]) {
  const list = getEl('source-list');
  const container = getEl('grounding-sources');
  list.innerHTML = '';

  const uniqueUrls = new Set();
  chunks.forEach(chunk => {
    if (chunk.web?.uri) {
      if (!uniqueUrls.has(chunk.web.uri)) {
        uniqueUrls.add(chunk.web.uri);
        const li = document.createElement('li');
        li.innerHTML = `<a href="${chunk.web.uri}" target="_blank"><i class="fas fa-link"></i> ${chunk.web.title || chunk.web.uri}</a>`;
        list.appendChild(li);
      }
    }
  });

  if (uniqueUrls.size > 0) {
    container.classList.remove('hidden');
  }
}

