@keyframes spin { to { transform: rotate(360deg); } }

/* Cards */
.card-carousel { position: absolute; bottom: 30px; width: 100%; z-index: 100; pointer-events: none; }
.card-container { display: flex; overflow-x: auto; padding: 20px 0; gap: 20px; padding-left: calc(50% - 120px); padding-right: calc(50% - 120px); scroll-snap-type: x mandatory; pointer-events: auto; }
.card-container::-webkit-scrollbar { display: none; }

.location-card { flex: 0 0 240px; background: white; border-radius: 20px; padding: 18px; box-shadow: 0 15px 45px rgba(0,0,0,0.6); cursor: pointer; transition: 0.4s; scroll-snap-align: center; border-left: 8px solid #ff5722; position: relative; }
.location-card.type-TRANSIT { border-left-color: #2196F3; }
.location-card.type-FOOD { border-left-color: #FFC107; }
.location-card.card-active { transform: scale(1.1) translateY(-20px); border-color: #ff5722; box-shadow: 0 25px 60px rgba(0,0,0,0.8); z-index: 2; }

.card-badge { position: absolute; top: -10px; left: 15px; background: #ff5722; color: white; font-size: 10px; font-weight: 900; padding: 3px 10px; border-radius: 20px; box-shadow: 0 4px 10px rgba(255,87,34,0.3); }
.card-weather { position: absolute; top: -10px; right: 15px; background: #333; color: white; font-size: 10px; font-weight: 800; padding: 3px 10px; border-radius: 20px; }
.card-title { font-size: 16px; font-weight: 800; color: #1a1a1a; margin: 8px 0; }
.card-description { font-size: 12px; color: #666; display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; line-height: 1.6; }

.custom-map-popup { position: absolute; transform: translate(-50%, -100%); margin-top: -15px; filter: drop-shadow(0 5px 15px rgba(0,0,0,0.3)); }
.popup-bubble { background: white; padding: 12px 18px; border-radius: 12px; font-size: 13px; color: #333; line-height: 1.4; border: 1px solid #eee; }
.popup-anchor { position: absolute; width: 0; height: 0; border-left: 10px solid transparent; border-right: 10px solid transparent; border-top: 10px solid white; left: 50%; transform: translateX(-50%); }

.floating-control-btn { position: absolute; z-index: 120; width: 50px; height: 50px; border-radius: 50%; background: white; border: none; box-shadow: 0 8px 25px rgba(0,0,0,0.3); cursor: pointer; display: flex; align-items: center; justify-content: center; font-size: 20px; transition: 0.3s; }
.floating-control-btn:hover { background: #ff5722; color: white; transform: scale(1.1); }
.toggle-ui-btn { top: 25px; left: 25px; }
.reopen-timeline-btn { top: 25px; right: 90px; background: #ff5722; color: white; }
.reset-button { position: absolute; top: 25px; right: 25px; }

