import { FunctionDeclaration, GoogleGenAI, Type, GenerateContentResponse } from '@google/genai';

declare const google: any;

// Application state
let map: any;
let markers: any[] = [];
let popUps: any[] = [];
let bounds: any;
let activeCardIndex = 0;
let isPlannerMode = false;
let isUiHidden = false;
let dayPlanItinerary: any[] = [];
let itinerarySummary = "";
let polyline: any = null;

const getEl = <T extends HTMLElement>(id: string) => document.getElementById(id) as T;

/**
 * Initialize Map
 */
async function initApp() {
  try {
    const { Map } = await google.maps.importLibrary('maps');
    const { LatLngBounds } = await google.maps.importLibrary('core');

    bounds = new LatLngBounds();
    map = new Map(getEl('map'), {
      center: { lat: 39.9042, lng: 116.4074 },
      zoom: 12,
      disableDefaultUI: true,
      gestureHandling: 'greedy',
      styles: [
        { "featureType": "all", "elementType": "labels.text.fill", "stylers": [{ "color": "#ffffff" }] },
        { "featureType": "all", "elementType": "labels.text.stroke", "stylers": [{ "color": "#000000" }, { "lightness": 13 }] },
        { "featureType": "administrative", "elementType": "geometry.fill", "stylers": [{ "color": "#000000" }, { "lightness": 20 }] },
        { "featureType": "landscape", "elementType": "geometry", "stylers": [{ "color": "#000000" }, { "lightness": 20 }] },
        { "featureType": "poi", "elementType": "geometry", "stylers": [{ "color": "#000000" }, { "lightness": 21 }] },
        { "featureType": "road.highway", "elementType": "geometry.fill", "stylers": [{ "color": "#000000" }, { "lightness": 17 }] },
        { "featureType": "water", "elementType": "geometry", "stylers": [{ "color": "#0d0d0d" }, { "lightness": 17 }] }
      ]
    });

    setupPopupClass();
    bindEvents();
    setupKeyboardShortcuts();

    getEl('spinner').classList.add('hidden');
  } catch (err) {
    console.error("Map Load Failed", err);
  }
}

function setupPopupClass() {
  (window as any).Popup = class Popup extends google.maps.OverlayView {
    position: any; containerDiv: HTMLDivElement;
    constructor(position: any, content: HTMLElement) {
      super();
      this.position = position;
      this.containerDiv = document.createElement('div');
      this.containerDiv.classList.add('custom-map-popup');
      const bubble = document.createElement('div');
      bubble.classList.add('popup-bubble');
      bubble.appendChild(content);
      this.containerDiv.appendChild(bubble);
      const anchor = document.createElement('div');
      anchor.classList.add('popup-anchor');
      this.containerDiv.appendChild(anchor);
      google.maps.OverlayView.preventMapHitsAndGesturesFrom(this.containerDiv);
    }
    onAdd() { (this as any).getPanes().floatPane.appendChild(this.containerDiv); }
    onRemove() { if (this.containerDiv.parentElement) this.containerDiv.parentElement.removeChild(this.containerDiv); }
    draw() {
      const divPosition = (this as any).getProjection().fromLatLngToDivPixel(this.position);
      if (divPosition) { this.containerDiv.style.left = divPosition.x + 'px'; this.containerDiv.style.top = divPosition.y + 'px'; }
    }
  };
}

const locationFunctionDeclaration: FunctionDeclaration = {
  name: 'location',
  parameters: {
    type: Type.OBJECT,
    description: '标注地点信息。必须严格根据用户需求产出完整的多天行程。',
    properties: {
      name: { type: Type.STRING, description: '地点名称' },
      description: { type: Type.STRING, description: '详细博主级建议：必看、避雷、网红机位、必点菜。' },
      lat: { type: Type.STRING },
      lng: { type: Type.STRING },
      time: { type: Type.STRING, description: '时间段，如 14:00 - 17:00' },
      day: { type: Type.NUMBER, description: '所属天数。如果用户要N天，你必须产出 Day 1 到 Day N 的所有节点，严禁只给一天的回复。' },
      sequence: { type: Type.NUMBER, description: '当天顺序编号。' },
      transit_hint: { type: Type.STRING, description: '具体交通方式（高铁班次、打车、地铁线）。' },
      type: { type: Type.STRING, description: 'SIGHT, FOOD, TRANSIT, HOTEL' },
      weather: { type: Type.STRING, description: '通过联网检索得到的该地点当前的实时天气状况。' },
      temperature: { type: Type.STRING, description: '该地点当天的实时温度范围。' }
    },
    required: ['name', 'description', 'lat', 'lng', 'time', 'day', 'sequence', 'weather', 'temperature'],
  },
};

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

async function handleRequest() {
  const userInput = (getEl('prompt-input') as HTMLTextAreaElement).value.trim();
  const selectedModel = (getEl('model-selector') as HTMLSelectElement).value;

  if (!userInput) {
    setStatus("请输入您的想法或目的地！", "error");
    return;
  }

  restart();
  getEl('spinner').classList.remove('hidden');

  const statusMsg = isPlannerMode 
    ? `🗺️ 正在使用 ${selectedModel === 'gemini-3-pro-preview' ? 'Pro' : 'Flash'} 模型检索实时天气、高铁和多天深度方案...` 
    : "🌟 正在为您搜寻全网实时热门宝藏地点与网红机位...";
  setStatus(statusMsg, "loading");

  try {
    let systemInstruction = `你是一个顶级深度定制旅游博主。
    1. **必须联网**：使用 googleSearch 检索目的地当前真实的实时天气、气温、交通（高铁具体班次/航班）和景点开放状态。可以搜索小红书、抖音、大众点评获取最新潮流。
    2. **严格天数要求**：识别用户要求的总天数（如“3天”）。你必须在单次响应中为每一天都提供至少3个 location 节点。严禁在用户要求多天时仅回复第一天的内容。
    3. **细节至上**：描述中必须包含【必打卡点】、【避雷攻略】、【省力路线】。
    4. **天气与气温**：必须填入 location 函数的对应字段。
    5. 在 text 响应部分提供一段行程亮点总述。`;

    let promptPrefix = `用户需求：${userInput}。

    你必须：
    - 完整识别并规划用户要求的所有天数。如果是 3 天，就必须有 Day 1, Day 2, Day 3。
    - 联网查询目的地的实时天气和气温。
    - 针对交通，联网搜索最优的具体高铁班次（如：G652次）或航班建议。
    - 每一天的行程必须丰富且逻辑连贯。`;

    if (!isPlannerMode) {
      systemInstruction = "你是一个全网通的旅游挖掘博主，擅长提供最新、最真实、带实时天气的宝藏地推荐。";
      promptPrefix = `请联网搜索推荐 6-10 个关于“${userInput}”的打卡点。每个点必须包含真实的实时天气和气温。`;
    }

    const response = await ai.models.generateContent({
      model: selectedModel,
      contents: promptPrefix,
      config: {
        thinkingConfig: { thinkingBudget: selectedModel === 'gemini-3-pro-preview' ? 5500 : 0 },
        systemInstruction,
        tools: [{ googleSearch: {} }, { functionDeclarations: [locationFunctionDeclaration] }],
      },
    });

    const textPart = response.candidates?.[0]?.content?.parts.find(p => p.text);
    if (textPart) itinerarySummary = textPart.text || "";

    const calls = response.candidates?.[0]?.content?.parts.filter(p => p.functionCall) || [];
    for (const part of calls) {
      const fn = part.functionCall;
      if (fn && fn.name === 'location') await setPin(fn.args);
    }

    const grounding = response.candidates?.[0]?.groundingMetadata;
    if (grounding && grounding.groundingChunks) displaySources(grounding.groundingChunks);

    if (dayPlanItinerary.length === 0) throw new Error("AI 未能获取到实时细节，请尝试输入更具体的内容。");

    dayPlanItinerary.sort((a, b) => {
      const d1 = Number(a.day) || 1;
      const d2 = Number(b.day) || 1;
      if (d1 !== d2) return d1 - d2;
      return (Number(a.sequence) || 0) - (Number(b.sequence) || 0);
    });

    if (isPlannerMode) {
      drawRoute();
      createTimeline();
      showTimeline();
    }

    createCards();
    highlightCard(0, true);
    setStatus("", "hidden");
  } catch (e: any) {
    setStatus("⚠️ " + e.message, "error");
    console.error(e);
  } finally {
    getEl('spinner').classList.add('hidden');
  }
}

function displaySources(chunks: any[]) {
  const list = getEl('source-list');
  const container = getEl('grounding-sources');
  list.innerHTML = '';
  const uniqueUrls = new Set();
  chunks.forEach(chunk => {
    if (chunk.web?.uri && !uniqueUrls.has(chunk.web.uri)) {
      uniqueUrls.add(chunk.web.uri);
      const li = document.createElement('li');
      li.innerHTML = `<a href="${chunk.web.uri}" target="_blank"><i class="fas fa-link"></i> ${chunk.web.title || chunk.web.uri}</a>`;
      list.appendChild(li);
    }
  });
  if (uniqueUrls.size > 0) container.classList.remove('hidden');
}

async function setPin(args: any) {
  const pos = { lat: Number(args.lat), lng: Number(args.lng) };
  bounds.extend(pos);

  const marker = new google.maps.Marker({
    map: map,
    position: pos,
    title: args.name,
    animation: google.maps.Animation.DROP,
    icon: {
      path: google.maps.SymbolPath.CIRCLE,
      fillColor: args.type === 'TRANSIT' ? '#2196F3' : args.type === 'FOOD' ? '#FFC107' : '#ff5722',
      fillOpacity: 1,
      strokeWeight: 3,
      strokeColor: '#fff',
      scale: 11
    }
  });

  markers.push(marker);
  map.fitBounds(bounds);

  const content = document.createElement('div');
  content.innerHTML = `<div style="padding: 5px; min-width: 130px;"><strong>${args.name}</strong><br><small style="color:#666">Day ${args.day} | ${args.time}<br>🌡️ ${args.temperature} | ${args.weather}</small></div>`;
  const popup = new (window as any).Popup(new google.maps.LatLng(pos), content);

  const item = { ...args, position: new google.maps.LatLng(pos), popup, marker };
  dayPlanItinerary.push(item);
  popUps.push(item);

  marker.addListener('click', () => {
    highlightCard(dayPlanItinerary.indexOf(item), true);
  });
}

function drawRoute() {
  if (polyline) polyline.setMap(null);
  polyline = new google.maps.Polyline({
    path: dayPlanItinerary.map(i => i.position),
    geodesic: true,
    strokeColor: '#ff5722',
    strokeOpacity: 0.8,
    strokeWeight: 5,
    icons: [{
      icon: { path: google.maps.SymbolPath.FORWARD_CLOSED_ARROW, strokeColor: '#fff', scale: 2 },
      offset: '100%',
      repeat: '120px'
    }],
    map: map
  });
}

function createCards() {
  const container = getEl('card-container');
  const indicators = getEl('carousel-indicators');
  container.innerHTML = ''; indicators.innerHTML = '';
  document.querySelector('.card-carousel')!.classList.remove('hidden');

  dayPlanItinerary.forEach((loc, index) => {
    const card = document.createElement('div');
    card.className = `location-card type-${loc.type || 'SIGHT'}`;
    card.innerHTML = `
      <div class="card-badge">Day ${loc.day} - ${loc.sequence}</div>
      <div class="card-weather"><i class="fas fa-cloud-sun"></i> ${loc.temperature}</div>
      <div class="card-title">${loc.name}</div>
      <div class="card-description">${loc.description}</div>
    `;
    card.onclick = () => highlightCard(index, true);
    container.appendChild(card);

    const dot = document.createElement('div');
    dot.className = 'carousel-dot';
    dot.onclick = () => highlightCard(index, true);
    indicators.appendChild(dot);
  });
}

function createTimeline() {
  const t = getEl('timeline');
  t.innerHTML = '';

  if (itinerarySummary) {
    const summaryDiv = document.createElement('div');
    summaryDiv.className = 'timeline-summary';
    summaryDiv.innerHTML = `<i class="fas fa-info-circle"></i> <strong>行程总括与建议：</strong><br>${itinerarySummary.replace(/\n/g, '<br>')}`;
    t.appendChild(summaryDiv);
  }

  let currentDay = -1;
  dayPlanItinerary.forEach((item, index) => {
    if (item.day !== currentDay) {
      currentDay = item.day;
      const dayHeader = document.createElement('div');
      dayHeader.className = 'day-header';
      dayHeader.innerHTML = `<i class="fas fa-calendar-day"></i> <span>第 ${currentDay} 天行程规划 (实时天气：${item.weather} ${item.temperature})</span>`;
      t.appendChild(dayHeader);
    }

    const div = document.createElement('div');
    div.className = `timeline-item type-${item.type || 'SIGHT'}`;
    div.onclick = () => highlightCard(index, true);
    div.innerHTML = `
      <div class="timeline-time">${item.time} <span class="weather-pill">${item.temperature}</span></div>
      <div class="timeline-content">
        <div class="timeline-title">${item.name}</div>
        <div class="timeline-description">${item.description}</div>
      </div>
    `;
    t.appendChild(div);

    if (index < dayPlanItinerary.length - 1 && item.transit_hint) {
      if (dayPlanItinerary[index+1].day === item.day) {
        const transitDiv = document.createElement('div');
        transitDiv.className = 'transit-info';
        transitDiv.innerHTML = `<i class="fas fa-shuttle-van"></i> <strong>交通细节：</strong>${item.transit_hint}`;
        t.appendChild(transitDiv);
      }
    }
  });
}

function exportItinerary() {
  if (dayPlanItinerary.length === 0) return;
  let md = `# AI 深度全域旅游手册\n\n`;
  if (itinerarySummary) md += `## 行程前瞻\n${itinerarySummary}\n\n`;
  let currentDay = -1;
  dayPlanItinerary.forEach((item, i) => {
    if (item.day !== currentDay) {
      currentDay = item.day;
      md += `\n# --- DAY ${currentDay} (实时天气: ${item.weather} ${item.temperature}) ---\n\n`;
    }
    md += `### ${item.sequence}. ${item.name} (${item.time})\n`;
    md += `> **实时状况:** ${item.weather} / ${item.temperature}\n\n`;
    md += `> **深度建议:**\n${item.description}\n\n`;
    if (item.transit_hint) md += `**🚀 交通指南:** ${item.transit_hint}\n\n`;
    md += `\n`;
  });
  md += `\n---\n### 数据来源与参考:\n`;
  const sources = getEl('source-list').querySelectorAll('a');
  sources.forEach(a => md += `- [${a.innerText}](${a.getAttribute('href')})\n`);
  const blob = new Blob([md], { type: 'text/markdown' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `我的深度旅行手册_${new Date().toLocaleDateString()}.md`;
  a.click();
}

function highlightCard(index: number, scroll: boolean = false) {
  popUps.forEach(p => p.popup.setMap(null));
  activeCardIndex = Math.max(0, Math.min(index, dayPlanItinerary.length - 1));
  const cards = document.querySelectorAll('.location-card');
  const dots = document.querySelectorAll('.carousel-dot');
  cards.forEach((c, i) => c.classList.toggle('card-active', i === activeCardIndex));
  dots.forEach((d, i) => d.classList.toggle('active', i === activeCardIndex));
  const item = dayPlanItinerary[activeCardIndex];
  if (item) {
    item.popup.setMap(map);
    map.panTo(item.position);
    item.marker.setAnimation(google.maps.Animation.BOUNCE);
    setTimeout(() => item.marker.setAnimation(null), 1200);
  }
  if (scroll && cards[activeCardIndex]) {
    getEl('card-container').scrollTo({ 
      left: (cards[activeCardIndex] as HTMLElement).offsetLeft - (getEl('card-container').offsetWidth / 2) + 120, 
      behavior: 'smooth' 
    });
  }
}

function setStatus(msg: string, type: 'loading' | 'error' | 'hidden') {
  const err = getEl('error-message');
  if (type === 'hidden') {
    err.classList.add('hidden');
    return;
  }
  err.innerText = msg;
  err.className = `error ${type}`;
  err.classList.remove('hidden');
}

function showTimeline() {
  getEl('timeline-container').classList.add('visible');
  getEl('map-container').classList.add('shifted');
  getEl('reopen-timeline').classList.add('hidden');
}

function hideTimeline() {
  getEl('timeline-container').classList.remove('visible');
  getEl('map-container').classList.remove('shifted');
  if (dayPlanItinerary.length > 0 && isPlannerMode) getEl('reopen-timeline').classList.remove('hidden');
}

function restart() {
  markers.forEach(m => m.setMap(null));
  popUps.forEach(p => p.popup.setMap(null));
  if (polyline) polyline.setMap(null);
  markers = []; popUps = []; dayPlanItinerary = []; itinerarySummary = "";
  getEl('card-container').innerHTML = '';
  getEl('source-list').innerHTML = '';
  getEl('grounding-sources').classList.add('hidden');
  document.querySelector('.card-carousel')!.classList.add('hidden');
  setStatus("", "hidden");
  hideTimeline();
  bounds = new google.maps.LatLngBounds();
}

function bindEvents() {
  getEl('planner-mode-toggle').onchange = (e) => {
    isPlannerMode = (e.target as HTMLInputElement).checked;
    getEl('preference-toggle-group').classList.toggle('hidden', !isPlannerMode);
    getEl('mode-text').innerText = isPlannerMode ? "行程规划模式 (支持多天+实时天气)" : "景点发现模式";
    (getEl('prompt-input') as HTMLTextAreaElement).placeholder = isPlannerMode 
      ? "输入行程：如“下周带孩子去北京玩3天，带实时天气和具体高铁班次建议”" 
      : "输入兴趣点（如：杭州西湖看日落的网红位置）";
    restart();
  };
  getEl('generate').onclick = handleRequest;
  getEl('export-btn').onclick = exportItinerary;
  getEl('reset').onclick = restart;
  getEl('close-timeline').onclick = hideTimeline;
  getEl('reopen-timeline').onclick = showTimeline;
  getEl('toggle-search-ui').onclick = () => {
    isUiHidden = !isUiHidden;
    getEl('search-container').classList.toggle('ui-hidden', isUiHidden);
    getEl('toggle-search-ui').innerHTML = isUiHidden ? '<i class="fas fa-eye"></i>' : '<i class="fas fa-eye-slash"></i>';
  };
  getEl('prompt-input').addEventListener('keydown', (e) => {
    if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleRequest(); }
  });
}

function setupKeyboardShortcuts() {
  window.addEventListener('keydown', (e) => {
    if (["INPUT", "TEXTAREA"].includes(document.activeElement?.tagName || "")) return;
    if (e.key === 'ArrowRight') highlightCard(activeCardIndex + 1, true);
    if (e.key === 'ArrowLeft') highlightCard(activeCardIndex - 1, true);
    if (e.key.toLowerCase() === 'r') restart();
  });
}

initApp();

@import url(https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css);

* { box-sizing: border-box; padding: 0; margin: 0; font-family: 'Segoe UI', Roboto, 'PingFang SC', sans-serif; }

html, body { height: 100%; width: 100%; overflow: hidden; background: #000; }

.hidden { display: none !important; }

.map-container { position: relative; height: 100%; width: 100%; transition: transform 0.6s cubic-bezier(0.2, 1, 0.3, 1); }
.map-container.shifted { transform: translateX(-220px); }
#map { height: 100%; width: 100%; background-color: #0d0d0d; }

/* Search UI */
.search-container { 
  position: absolute; top: 20px; left: 50%; transform: translateX(-50%); 
  z-index: 110; width: 95%; max-width: 650px; 
  transition: 0.4s cubic-bezier(0.165, 0.84, 0.44, 1);
}
.search-container.ui-hidden { transform: translate(-50%, -150%); opacity: 0; }

.search-header-group { display: flex; justify-content: space-between; align-items: center; margin-bottom: 15px; }

.header-left-controls { display: flex; align-items: center; gap: 15px; }

.mode-toggle { 
  background: rgba(255, 255, 255, 0.98); padding: 8px 16px; border-radius: 24px; 
  display: flex; align-items: center; gap: 10px; box-shadow: 0 4px 15px rgba(0,0,0,0.1); backdrop-filter: blur(12px);
}
.mode-label { font-size: 13px; font-weight: 800; color: #1a1a1a; letter-spacing: 0.2px; }

.model-select {
  padding: 8px 12px; border-radius: 20px; border: 1px solid #ddd; background: white;
  font-size: 13px; font-weight: 700; color: #333; outline: none; cursor: pointer; transition: 0.2s;
}
.model-select:hover { border-color: #ff5722; }

.preference-select { 
  padding: 8px 16px; border-radius: 20px; border: none; background: #ff5722; color: white; 
  font-size: 13px; font-weight: 700; outline: none; box-shadow: 0 4px 15px rgba(255,87,34,0.3); cursor: pointer;
}

.search-bar-stack { 
  background: rgba(255, 255, 255, 0.98); border-radius: 28px; padding: 15px; 
  box-shadow: 0 15px 50px rgba(0,0,0,0.4); backdrop-filter: blur(25px);
  position: relative; border: 1px solid rgba(255,255,255,0.1);
}

.search-bar { display: flex; align-items: center; gap: 12px; }
#prompt-input { 
  flex: 1; border: none; outline: none; font-size: 16px; resize: none; 
  min-height: 52px; max-height: 200px; line-height: 24px; background: transparent; 
  color: #1a1a1a; font-weight: 500;
}
.search-button { 
  background: #ff5722; color: white; border: none; width: 44px; height: 44px; border-radius: 50%; 
  cursor: pointer; display: flex; align-items: center; justify-content: center; transition: 0.3s;
  font-size: 1.1rem; flex-shrink: 0;
}

/* Timeline */
.timeline-container { position: fixed; right: 0; top: 0; width: 480px; height: 100%; background: white; z-index: 1000; transform: translateX(100%); transition: 0.6s cubic-bezier(0.165, 0.84, 0.44, 1); box-shadow: -20px 0 60px rgba(0,0,0,0.35); display: flex; flex-direction: column; }
.timeline-container.visible { transform: translateX(0); }
.timeline-header { padding: 25px; border-bottom: 1px solid #f0f0f0; display: flex; justify-content: space-between; align-items: center; }
.timeline { padding: 20px; overflow-y: auto; flex: 1; }

.timeline-summary {
  background: #fdf2f0; padding: 20px; border-radius: 15px; border: 1px solid #ff5722;
  margin-bottom: 30px; font-size: 13px; color: #333; line-height: 1.6;
}

.day-header {
  padding: 12px 18px; background: #222; color: white; border-radius: 12px;
  font-weight: 800; font-size: 15px; margin: 35px 0 20px 0; display: flex; align-items: center; gap: 10px;
  box-shadow: 0 5px 15px rgba(0,0,0,0.1);
}

.timeline-item { cursor: pointer; padding: 18px; border-radius: 18px; transition: 0.3s; margin-bottom: 15px; border-left: 5px solid #ff5722; background: #fafafa; position: relative; }
.timeline-item.type-TRANSIT { border-left-color: #2196F3; background: #f0f7ff; }
.timeline-item.type-FOOD { border-left-color: #FFC107; background: #fffcf0; }
.timeline-item:hover { transform: translateX(8px); box-shadow: 0 8px 20px rgba(0,0,0,0.1); }

.timeline-time { display: flex; justify-content: space-between; align-items: center; color: #ff5722; font-weight: 900; font-size: 13px; margin-bottom: 8px; }
.weather-pill { background: #eee; color: #666; padding: 2px 8px; border-radius: 10px; font-size: 11px; }

.timeline-title { font-size: 17px; font-weight: 800; color: #1a1a1a; margin-bottom: 8px; }
.timeline-description { font-size: 13px; color: #555; line-height: 1.6; }

.transit-info { 
  margin: 10px 0 25px 35px; padding: 12px 20px; background: #fff5f2; border-radius: 12px; 
  font-size: 13px; color: #333; display: flex; align-items: center; gap: 12px; 
  border: 1px dashed rgba(255,87,34,0.3);
}

/* Loading */
.spinner { 
  position: fixed; top: 0; left: 0; width: 100%; height: 100%; 
  background: rgba(0,0,0,0.75); backdrop-filter: blur(10px);
  z-index: 2000; display: flex; flex-direction: column; align-items: center; justify-content: center;
}
.spinner::after {
  content: ''; width: 65px; height: 65px; border: 6px solid rgba(255,255,255,0.1);
  border-top-color: #ff5722; border-radius: 50%; animation: spin 0.8s linear infinite;
}
.loading-text { color: white; margin-top: 25px; font-weight: 800; font-size: 1.1rem; text-align: center; max-width: 85%; }

@keyframes spin { to { transform: rotate(360deg); } }

/* Cards */
.card-carousel { position: absolute; bottom: 30px; width: 100%; z-index: 100; pointer-events: none; }
.card-container { display: flex; overflow-x: auto; padding: 20px 0; gap: 20px; padding-left: calc(50% - 120px); padding-right: calc(50% - 120px); scroll-snap-type: x mandatory; pointer-events: auto; }
.card-container::-webkit-scrollbar { display: none; }

.location-card { flex: 0 0 240px; background: white; border-radius: 20px; padding: 18px; box-shadow: 0 15px 45px rgba(0,0,0,0.6); cursor: pointer; transition: 0.4s; scroll-snap-align: center; border-left: 8px solid #ff5722; position: relative; }
.location-card.type-TRANSIT { border-left-color: #2196F3; }
.location-card.type-FOOD { border-left-color: #FFC107; }
.location-card.card-active { transform: scale(1.1) translateY(-20px); border-color: #ff5722; box-shadow: 0 25px 60px rgba(0,0,0,0.8); z-index: 2; }

.card-badge { position: absolute; top: -10px; left: 15px; background: #ff5722; color: white; font-size: 10px; font-weight: 900; padding: 3px 10px; border-radius: 20px; box-shadow: 0 4px 10px rgba(255,87,34,0.3); }
.card-weather { position: absolute; top: -10px; right: 15px; background: #333; color: white; font-size: 10px; font-weight: 800; padding: 3px 10px; border-radius: 20px; }
.card-title { font-size: 16px; font-weight: 800; color: #1a1a1a; margin: 8px 0; }
.card-description { font-size: 12px; color: #666; display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; line-height: 1.6; }

.switch { position: relative; display: inline-block; width: 44px; height: 24px; }
.switch input { opacity: 0; width: 0; height: 0; }
.slider { position: absolute; cursor: pointer; top: 0; left: 0; right: 0; bottom: 0; background-color: #ddd; transition: .4s; border-radius: 34px; }
.slider:before { position: absolute; content: ""; height: 18px; width: 18px; left: 3px; bottom: 3px; background-color: white; transition: .4s; border-radius: 50%; }
input:checked + .slider { background-color: #ff5722; }
input:checked + .slider:before { transform: translateX(20px); }

.floating-control-btn { position: absolute; z-index: 120; width: 50px; height: 50px; border-radius: 50%; background: white; border: none; box-shadow: 0 8px 25px rgba(0,0,0,0.3); cursor: pointer; display: flex; align-items: center; justify-content: center; font-size: 20px; transition: 0.3s; }
.floating-control-btn:hover { background: #ff5722; color: white; transform: scale(1.1); }
.toggle-ui-btn { top: 25px; left: 25px; }
.reopen-timeline-btn { top: 25px; right: 90px; background: #ff5722; color: white; }
.reset-button { position: absolute; top: 25px; right: 25px; }

