import { FunctionDeclaration, Type } from '@google/genai';

/**
 * MCP (Model Context Protocol) 工具集定义文件
 * 
 * --- 如何新增一个工具？ ---
 * 1. 在下方定义一个新的 FunctionDeclaration 对象。
 * 2. 描述工具的 name (唯一标识), description (告诉 AI 什么时候用), parameters (数据结构)。
 * 3. 在 index.tsx 的 handleRequest 中，将新工具添加到 tools 数组中。
 * 4. 在 index.tsx 的处理逻辑中增加对该 functionCall.name 的响应逻辑。
 */

/**
 * 工具 1: 地图标注工具 (location)
 * 用于在地图上渲染旅游节点、打卡点或交通枢纽。
 */
export const locationTool: FunctionDeclaration = {
  name: 'location',
  parameters: {
    type: Type.OBJECT,
    description: '标注地点信息。必须根据用户需求产出完整的多天行程。',
    properties: {
      name: { type: Type.STRING, description: '地点名称' },
      description: { type: Type.STRING, description: '详细博主级深度建议。包含必去理由和避雷指南。' },
      lat: { type: Type.STRING, description: '纬度' },
      lng: { type: Type.STRING, description: '经度' },
      time: { type: Type.STRING, description: '建议游玩时间段' },
      day: { type: Type.NUMBER, description: '所属天数序号 (从 1 开始)' },
      sequence: { type: Type.NUMBER, description: '当天内的显示顺序' },
      transit_hint: { type: Type.STRING, description: '从上一个点到此处的交通建议' },
      type: { type: Type.STRING, description: '分类：SIGHT (景点), FOOD (食物), TRANSIT (交通), HOTEL (住宿)' },
      weather: { type: Type.STRING, description: '该地点当天的实时天气状况' },
      temperature: { type: Type.STRING, description: '该地点的实时气温' }
    },
    required: ['name', 'description', 'lat', 'lng', 'time', 'day', 'sequence', 'weather', 'temperature'],
  },
};

/**
 * 示例工具: 酒店搜索 (假设后续需要)
 * 
 * export const hotelSearchTool: FunctionDeclaration = {
 *   name: 'search_hotels',
 *   parameters: {
 *     type: Type.OBJECT,
 *     description: '根据预算和位置搜索推荐酒店',
 *     properties: {
 *       location: { type: Type.STRING },
 *       budget_range: { type: Type.STRING },
 *       rating_min: { type: Type.NUMBER }
 *     },
 *     required: ['location']
 *   }
 * };
 */

