import { GoogleGenAI, GenerateContentResponse } from '@google/genai';
import { MarkerClusterer } from "@googlemaps/markerclusterer";
import { locationTool, xhsSearchTool } from './mcp-tools';

declare const google: any;

// Application state
let map: any;
let markers: any[] = [];
let popUps: any[] = [];
let bounds: any;
let markerCluster: any;
let activeCardIndex = 0;
let isPlannerMode = false;
let isUiHidden = false;
let dayPlanItinerary: any[] = [];
let itinerarySummary = "";
let polyline: any = null;

const getEl = <T extends HTMLElement>(id: string) => document.getElementById(id) as T;

function getWeatherIconClass(weather: string): string {
  const w = (weather || '晴').toLowerCase();
  if (w.includes('晴') || w.includes('sun') || w.includes('clear')) return 'fa-sun';
  if (w.includes('雨') || w.includes('rain')) return 'fa-cloud-showers-heavy';
  if (w.includes('雪') || w.includes('snow')) return 'fa-snowflake';
  if (w.includes('雷') || w.includes('thunder')) return 'fa-bolt';
  if (w.includes('阴') || w.includes('overcast') || w.includes('cloudy') || w.includes('云')) return 'fa-cloud';
  if (w.includes('雾') || w.includes('mist') || w.includes('fog')) return 'fa-smog';
  if (w.includes('风') || w.includes('wind')) return 'fa-wind';
  return 'fa-cloud-sun'; 
}

async function initApp() {
  try {
    const { Map } = await google.maps.importLibrary('maps');
    const { LatLngBounds } = await google.maps.importLibrary('core');
    bounds = new LatLngBounds();
    map = new Map(getEl('map'), {
      center: { lat: 34.2658, lng: 108.9424 }, 
      zoom: 12,
      disableDefaultUI: true,
      gestureHandling: 'greedy',
      styles: [
        { "featureType": "all", "elementType": "labels.text.fill", "stylers": [{ "color": "#ffffff" }] },
        { "featureType": "all", "elementType": "labels.text.stroke", "stylers": [{ "color": "#000000" }, { "lightness": 13 }] },
        { "featureType": "administrative", "elementType": "geometry.fill", "stylers": [{ "color": "#000000" }, { "lightness": 20 }] },
        { "featureType": "landscape", "elementType": "geometry", "stylers": [{ "color": "#000000" }, { "lightness": 20 }] },
        { "featureType": "poi", "elementType": "geometry", "stylers": [{ "color": "#000000" }, { "lightness": 21 }] },
        { "featureType": "road.highway", "elementType": "geometry.fill", "stylers": [{ "color": "#000000" }, { "lightness": 17 }] },
        { "featureType": "water", "elementType": "geometry", "stylers": [{ "color": "#0d0d0d" }, { "lightness": 17 }] }
      ]
    });
    markerCluster = new MarkerClusterer({ map, markers: [] });
    setupPopupClass();
    bindEvents();
    setupKeyboardShortcuts();
    getEl('spinner').classList.add('hidden');
  } catch (err) {
    console.error("Map Load Failed", err);
  }
}

function setupPopupClass() {
  (window as any).Popup = class Popup extends google.maps.OverlayView {
    position: any; containerDiv: HTMLDivElement;
    constructor(position: any, content: HTMLElement) {
      super();
      this.position = position;
      this.containerDiv = document.createElement('div');
      this.containerDiv.classList.add('custom-map-popup');
      const bubble = document.createElement('div');
      bubble.classList.add('popup-bubble');
      bubble.appendChild(content);
      this.containerDiv.appendChild(bubble);
      const anchor = document.createElement('div');
      anchor.classList.add('popup-anchor');
      this.containerDiv.appendChild(anchor);
      google.maps.OverlayView.preventMapHitsAndGesturesFrom(this.containerDiv);
    }
    onAdd() { (this as any).getPanes().floatPane.appendChild(this.containerDiv); }
    onRemove() { if (this.containerDiv.parentElement) this.containerDiv.parentElement.removeChild(this.containerDiv); }
    draw() {
      const divPosition = (this as any).getProjection().fromLatLngToDivPixel(this.position);
      if (divPosition) { this.containerDiv.style.left = divPosition.x + 'px'; this.containerDiv.style.top = divPosition.y + 'px'; }
    }
  };
}

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

async function handleRequest() {
  const userInput = (getEl('prompt-input') as HTMLTextAreaElement).value.trim();
  const selectedModel = (getEl('model-selector') as HTMLSelectElement).value;
  if (!userInput) { setStatus("请输入您的旅行计划！", "error"); return; }

  restart();
  getEl('spinner').classList.remove('hidden');
  getEl('spinner-model-info').innerText = `AI 正在协同 MCP 工具(Search/XHS/Maps)规划中...`;
  setStatus(`🗺️ 正在获取实时精准数据...`, "loading");

  try {
    const isDeepSeek = selectedModel.startsWith('deepseek');
    const systemInstruction = `你是一个顶级深度定制旅游规划专家。
    1. **实时性要求**：你必须首先使用 googleSearch 工具搜索目的地当下的天气、最新票价和交通管制信息。
    2. **网红风向标**：如果用户提到“拍照”或“打卡”，请使用 xhs_search 工具搜索小红书上的热门机位。
    3. **输出规范**：将所有搜索到的精准数据填入 location 工具的对应字段。
    4. **严格天数**：用户要求几天就规划几天，每一天必须有详细的 location 标注。`;

    const prompt = `需求：${userInput}。请综合搜索到的实时信息，通过 location 工具产出完整行程。`;

    if (isDeepSeek) {
      await handleDeepSeekRequest(selectedModel, systemInstruction, prompt);
    } else {
      await handleGeminiRequest(selectedModel, systemInstruction, prompt);
    }

    if (dayPlanItinerary.length === 0) throw new Error("AI 未能获取到有效的行程节点。");

    dayPlanItinerary.sort((a, b) => (Number(a.day) - Number(b.day)) || (Number(a.sequence) - Number(b.sequence)));

    createCards();
    if (isPlannerMode) { drawRoute(); createTimeline(); showTimeline(); } 
    else { hideTimeline(); }

    highlightCard(0, true);
    setStatus("", "hidden");
  } catch (e: any) {
    setStatus("⚠️ " + e.message, "error");
    console.error(e);
  } finally {
    getEl('spinner').classList.add('hidden');
  }
}

async function handleGeminiRequest(model: string, system: string, prompt: string) {
  // 同时启用 Google Search 和多个 MCP 函数工具
  const response = await ai.models.generateContent({
    model: model,
    contents: prompt,
    config: {
      thinkingConfig: { thinkingBudget: model.includes('pro') ? 32768 : 0 },
      systemInstruction: system,
      tools: [
        { googleSearch: {} }, 
        { functionDeclarations: [locationTool, xhsSearchTool] }
      ],
    },
  });

  const textPart = response.candidates?.[0]?.content?.parts.find(p => p.text);
  if (textPart) itinerarySummary = textPart.text || "";

  // 处理所有的工具调用循环
  const calls = response.candidates?.[0]?.content?.parts.filter(p => p.functionCall) || [];
  for (const part of calls) {
    const fn = part.functionCall;
    if (fn) {
      if (fn.name === 'location') {
        await setPin(fn.args);
      } else if (fn.name === 'xhs_search') {
        console.log("MCP调用(小红书搜索):", fn.args);
        // 这里可以添加展示“发现热门机位”的小提示 UI
      }
    }
  }

  // 渲染参考来源
  const grounding = response.candidates?.[0]?.groundingMetadata;
  if (grounding && grounding.groundingChunks) displaySources(grounding.groundingChunks);
}

async function handleDeepSeekRequest(model: string, system: string, prompt: string) {
  const apiKey = localStorage.getItem('deepseek_api_key');
  if (!apiKey) throw new Error("请配置 DeepSeek Key。");
  const response = await fetch('https://api.deepseek.com/v1/chat/completions', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiKey}` },
    body: JSON.stringify({
      model: model,
      messages: [{ role: 'system', content: system + "\nJSON 根对象含 'summary' 和 'locations' 数组。" }, { role: 'user', content: prompt }],
      response_format: { type: 'json_object' }
    })
  });
  const data = await response.json();
  const content = JSON.parse(data.choices[0].message.content);
  itinerarySummary = content.summary || "";
  if (content.locations) for (const loc of content.locations) await setPin(loc);
}

function displaySources(chunks: any[]) {
  const list = getEl('source-list');
  const container = getEl('grounding-sources');
  list.innerHTML = '';
  const uniqueUrls = new Set();
  chunks.forEach(chunk => {
    if (chunk.web?.uri && !uniqueUrls.has(chunk.web.uri)) {
      uniqueUrls.add(chunk.web.uri);
      const li = document.createElement('li');
      li.innerHTML = `<a href="${chunk.web.uri}" target="_blank"><i class="fas fa-link"></i> ${chunk.web.title || chunk.web.uri}</a>`;
      list.appendChild(li);
    }
  });
  if (uniqueUrls.size > 0) container.classList.remove('hidden');
}

async function setPin(args: any) {
  const name = args.name || "未命名";
  const lat = parseFloat(args.lat);
  const lng = parseFloat(args.lng);
  if (isNaN(lat) || isNaN(lng)) return;

  const weather = args.weather || "晴";
  const temp = args.temperature || "20°C";
  const pos = { lat, lng };
  bounds.extend(pos);

  const marker = new google.maps.Marker({
    position: pos,
    title: name,
    animation: google.maps.Animation.DROP,
    icon: {
      path: google.maps.SymbolPath.CIRCLE,
      fillColor: args.type === 'FOOD' ? '#FFC107' : args.type === 'TRANSIT' ? '#2196F3' : '#ff5722',
      fillOpacity: 1, strokeWeight: 2, strokeColor: '#fff', scale: 10
    }
  });

  markers.push(marker);
  markerCluster.addMarker(marker);
  map.fitBounds(bounds);

  const weatherIcon = getWeatherIconClass(weather);
  const content = document.createElement('div');
  content.innerHTML = `
    <div style="padding: 5px; min-width: 120px;">
      <strong style="display:block; margin-bottom:5px;">${name}</strong>
      <div style="font-size:11px; color:#ff5722;"><i class="fas ${weatherIcon}"></i> ${temp} ${weather}</div>
    </div>`;
  const popup = new (window as any).Popup(new google.maps.LatLng(pos), content);

  const item = { ...args, name, lat, lng, position: new google.maps.LatLng(pos), popup, marker };
  dayPlanItinerary.push(item);
  popUps.push(item);
  marker.addListener('click', () => highlightCard(dayPlanItinerary.indexOf(item), true));
}

function exportItinerary() {
  if (dayPlanItinerary.length === 0) { alert("尚未生成行程！"); return; }
  let md = `# 🌍 实时精准旅游手册\n\n`;
  if (itinerarySummary) md += `## 💡 规划摘要\n${itinerarySummary}\n\n`;
  let currentDay = -1;
  dayPlanItinerary.forEach((item) => {
    if (item.day !== currentDay) {
      currentDay = item.day;
      md += `\n# --- 🗓️ 第 ${currentDay} 天 (${item.weather || ''} ${item.temperature || ''}) ---\n\n`;
    }
    md += `### 📍 ${item.sequence}. ${item.name} (${item.time || '时间待定'})\n`;
    md += `> **实时状况:** ${item.weather} | ${item.temperature}\n\n`;
    md += `${item.description}\n\n`;
    if (item.transit_hint) md += `🚗 **交通建议:** ${item.transit_hint}\n\n`;
  });

  const blob = new Blob([md], { type: 'text/markdown' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = `行程手册_${new Date().getTime()}.md`;
  a.click();
}

function drawRoute() {
  if (polyline) polyline.setMap(null);
  polyline = new google.maps.Polyline({
    path: dayPlanItinerary.map(i => i.position),
    geodesic: true, strokeColor: '#ff5722', strokeOpacity: 0.8, strokeWeight: 4,
    map: map
  });
}

function createCards() {
  const container = getEl('card-container');
  const indicators = getEl('carousel-indicators');
  const carousel = document.querySelector('.card-carousel');
  container.innerHTML = ''; indicators.innerHTML = '';
  if (dayPlanItinerary.length === 0) { carousel?.classList.add('hidden'); return; }
  carousel?.classList.remove('hidden');
  dayPlanItinerary.forEach((loc, index) => {
    const card = document.createElement('div');
    const weatherIcon = getWeatherIconClass(loc.weather);
    card.className = `location-card type-${loc.type || 'SIGHT'}`;
    card.innerHTML = `
      <div class="card-badge">Day ${loc.day} - ${loc.sequence}</div>
      <div class="card-weather"><i class="fas ${weatherIcon}"></i> ${loc.temperature || ''}</div>
      <div class="card-title">${loc.name}</div>
      <div class="card-description">${loc.description}</div>`;
    card.onclick = () => highlightCard(index, true);
    container.appendChild(card);
    const dot = document.createElement('div');
    dot.className = 'carousel-dot';
    dot.onclick = () => highlightCard(index, true);
    indicators.appendChild(dot);
  });
}

function createTimeline() {
  const t = getEl('timeline');
  t.innerHTML = '';
  let currentDay = -1;
  dayPlanItinerary.forEach((item, index) => {
    if (item.day !== currentDay) {
      currentDay = item.day;
      const header = document.createElement('div');
      header.className = 'day-header';
      header.innerHTML = `<i class="fas fa-calendar-day"></i> <span>第 ${currentDay} 天</span>`;
      t.appendChild(header);
    }
    const div = document.createElement('div');
    div.className = `timeline-item type-${item.type || 'SIGHT'}`;
    div.onclick = () => highlightCard(index, true);
    div.innerHTML = `
      <div class="timeline-time">${item.time || ''}</div>
      <div class="timeline-content">
        <div class="timeline-title">${item.name}</div>
        <div class="timeline-description">${item.description}</div>
      </div>`;
    t.appendChild(div);
  });
}

function highlightCard(index: number, scroll: boolean = false) {
  popUps.forEach(p => p.popup.setMap(null));
  activeCardIndex = Math.max(0, Math.min(index, dayPlanItinerary.length - 1));
  const cards = document.querySelectorAll('.location-card');
  const dots = document.querySelectorAll('.carousel-dot');
  cards.forEach((c, i) => c.classList.toggle('card-active', i === activeCardIndex));
  dots.forEach((d, i) => d.classList.toggle('active', i === activeCardIndex));
  const item = dayPlanItinerary[activeCardIndex];
  if (item) {
    item.popup.setMap(map);
    map.panTo(item.position);
    item.marker.setAnimation(google.maps.Animation.BOUNCE);
    setTimeout(() => item.marker.setAnimation(null), 1200);
  }
  if (scroll && cards[activeCardIndex]) {
    getEl('card-container').scrollTo({ left: (cards[activeCardIndex] as HTMLElement).offsetLeft - 100, behavior: 'smooth' });
  }
}

function setStatus(msg: string, type: 'loading' | 'error' | 'hidden') {
  const err = getEl('error-message');
  if (type === 'hidden') { err.classList.add('hidden'); return; }
  err.innerText = msg; err.className = `error ${type}`; err.classList.remove('hidden');
}

function showTimeline() { getEl('timeline-container').classList.add('visible'); getEl('map-container').classList.add('shifted'); getEl('reopen-timeline').classList.add('hidden'); }
function hideTimeline() { getEl('timeline-container').classList.remove('visible'); getEl('map-container').classList.remove('shifted'); if (dayPlanItinerary.length > 0) getEl('reopen-timeline').classList.remove('hidden'); }

function restart() {
  markers.forEach(m => m.setMap(null));
  popUps.forEach(p => p.popup.setMap(null));
  if (polyline) polyline.setMap(null);
  if (markerCluster) markerCluster.clearMarkers();
  markers = []; popUps = []; dayPlanItinerary = [];
  getEl('card-container').innerHTML = '';
  document.querySelector('.card-carousel')?.classList.add('hidden');
  setStatus("", "hidden"); hideTimeline();
  getEl('reopen-timeline').classList.add('hidden');
  bounds = new google.maps.LatLngBounds();
}

function bindEvents() {
  getEl('planner-mode-toggle').onchange = (e) => {
    isPlannerMode = (e.target as HTMLInputElement).checked;
    getEl('mode-text').innerText = isPlannerMode ? "行程规划模式" : "景点发现模式";
    restart();
  };
  getEl('generate').onclick = handleRequest;
  getEl('reset').onclick = restart;
  getEl('export-btn').onclick = exportItinerary;
  getEl('close-timeline').onclick = hideTimeline;
  getEl('reopen-timeline').onclick = showTimeline;
  getEl('toggle-search-ui').onclick = () => {
    isUiHidden = !isUiHidden;
    getEl('search-container').classList.toggle('ui-hidden', isUiHidden);
  };
  getEl('open-settings').onclick = () => getEl('settings-modal').classList.remove('hidden');
  getEl('close-settings').onclick = () => getEl('settings-modal').classList.add('hidden');
  getEl('save-settings').onclick = () => {
    localStorage.setItem('deepseek_api_key', (getEl('deepseek-key-input') as HTMLInputElement).value.trim());
    getEl('settings-modal').classList.add('hidden');
  };
}

function setupKeyboardShortcuts() {
  window.addEventListener('keydown', (e) => {
    if (["INPUT", "TEXTAREA"].includes(document.activeElement?.tagName || "")) return;
    if (e.key === 'ArrowRight') highlightCard(activeCardIndex + 1, true);
    if (e.key === 'ArrowLeft') highlightCard(activeCardIndex - 1, true);
  });
}

