let isPlannerMode = false;
let isUiHidden = false;
let dayPlanItinerary: any[] = [];
let itinerarySummary = "";
let polyline: any = null;
let xhsNotes: any[] = []; // 存储小红书检索结果
let groundingSources: any[] = []; // Store search grounding URLs

const getEl = <T extends HTMLElement>(id: string) => document.getElementById(id) as T;

function getWeatherIconClass(weather: string): string {
  const w = (weather || '晴').toLowerCase();
  if (w.includes('晴') || w.includes('sun') || w.includes('clear')) return 'fa-sun';
  if (w.includes('雨') || w.includes('rain')) return 'fa-cloud-showers-heavy';
  if (w.includes('雪') || w.includes('snow')) return 'fa-snowflake';
  if (w.includes('雷') || w.includes('thunder')) return 'fa-bolt';
  if (w.includes('阴') || w.includes('overcast') || w.includes('cloudy') || w.includes('云')) return 'fa-cloud';
  return 'fa-cloud-sun'; 
}

/**
 * 调用本地小红书 MCP 服务
 */
async function callXhsMcp(args: any) {
  try {
    const response = await fetch('http://127.0.0.1:9999/mcp', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        keyword: args.keyword,
        note_type: args.note_type || 0,
        sort: args.sort || 'general'
      })
    });
    if (!response.ok) throw new Error("XHS MCP 离线");
    const data = await response.json();
    return data; // 假设返回笔记列表
  } catch (e) {
    console.error("XHS MCP 调用失败:", e);
    return { error: "无法连接到本地小红书 MCP 服务，请确保服务已启动于 9999 端口。" };
  }
}

async function initApp() {
  try {
    const { Map } = await google.maps.importLibrary('maps');
    const { LatLngBounds } = await google.maps.importLibrary('core');
    bounds = new LatLngBounds();
    map = new Map(getEl('map'), {
      center: { lat: 34.2658, lng: 108.9424 }, 
      zoom: 12,
      disableDefaultUI: true,
      styles: [
        { "featureType": "all", "elementType": "labels.text.fill", "stylers": [{ "color": "#ffffff" }] },
        { "featureType": "water", "elementType": "geometry", "stylers": [{ "color": "#0d0d0d" }] }
      ]
    });
    markerCluster = new MarkerClusterer({ map, markers: [] });
    setupPopupClass();
    bindEvents();

    // 初始化时加载已保存的 Key
    const savedKey = localStorage.getItem('deepseek_api_key');
    if (savedKey) {
      (getEl('deepseek-key-input') as HTMLInputElement).value = savedKey;
    }

    getEl('spinner').classList.add('hidden');
  } catch (err) {
    console.error("Map Load Failed", err);
  }
}

function setupPopupClass() {
  (window as any).Popup = class Popup extends google.maps.OverlayView {
    position: any; containerDiv: HTMLDivElement;
    constructor(position: any, content: HTMLElement) {
      super();
      this.position = position;
      this.containerDiv = document.createElement('div');
      this.containerDiv.classList.add('custom-map-popup');
      const bubble = document.createElement('div');
      bubble.classList.add('popup-bubble');
      bubble.appendChild(content);
      this.containerDiv.appendChild(bubble);
      google.maps.OverlayView.preventMapHitsAndGesturesFrom(this.containerDiv);
    }
    onAdd() { (this as any).getPanes().floatPane.appendChild(this.containerDiv); }
    onRemove() { if (this.containerDiv.parentElement) this.containerDiv.parentElement.removeChild(this.containerDiv); }
    draw() {
      const divPosition = (this as any).getProjection().fromLatLngToDivPixel(this.position);
      if (divPosition) { this.containerDiv.style.left = divPosition.x + 'px'; this.containerDiv.style.top = divPosition.y + 'px'; }
    }
  };
}

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

async function handleRequest() {
  const userInput = (getEl('prompt-input') as HTMLTextAreaElement).value.trim();
  const selectedModel = (getEl('model-selector') as HTMLSelectElement).value;
  if (!userInput) return;

  restart();
  getEl('spinner').classList.remove('hidden');
  setStatus(`正在获取实时数据并规划路线...`, "loading");

  try {
    if (selectedModel.startsWith('deepseek')) {
      await handleDeepSeekRequest(selectedModel, userInput);
    } else {
      await handleGeminiRequest(selectedModel, userInput);
    }

    // 渲染 UI
    if (dayPlanItinerary.length === 0) throw new Error("未识别到有效的行程节点。");
    dayPlanItinerary.sort((a, b) => (a.day - b.day) || (a.sequence - b.sequence));

    createCards();
    if (isPlannerMode) { drawRoute(); createTimeline(); showTimeline(); }
    else { hideTimeline(); }

    highlightCard(0, true);
    setStatus("", "hidden");
  } catch (e: any) {
    setStatus("⚠️ " + e.message, "error");
  } finally {
    getEl('spinner').classList.add('hidden');
  }
}

async function handleGeminiRequest(model: string, input: string) {
  const response = await ai.models.generateContent({
    model: model,
    contents: input,
    config: {
      systemInstruction: `你是一个深度旅游专家。
      1. 必须优先调用 googleSearch 获取该目的地的实时天气、票价和交通。
      2. 如果用户提到机位/攻略/拍照，调用 xhs_search。
      3. ${isPlannerMode ? "规划完整的行程路线，为每一天产出多个 location 标记。" : "仅在该地区发现相关打卡点。"}
      4. 通过 location 工具输出地图标记。`,
      tools: [{ googleSearch: {} }, { functionDeclarations: [locationTool, xhsSearchTool] }],
    },
  });

  const functionCalls = response.functionCalls || [];
  for (const fc of functionCalls) {
    const { name, args } = fc;
    getEl('spinner-model-info').innerText = `正在处理工具: ${name}...`;
    if (name === 'xhs_search') {
      const results = await callXhsMcp(args);
      xhsNotes = Array.isArray(results) ? results.slice(0, 3) : [];
    } else if (name === 'location') {
      await setPin(args);
    }
  }
  itinerarySummary = response.text || "";
  groundingSources = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
}

async function handleDeepSeekRequest(model: string, input: string) {
  const apiKey = localStorage.getItem('deepseek_api_key');
  if (!apiKey) throw new Error("请先在设置中配置 DeepSeek API Key。");

  getEl('spinner-model-info').innerText = `正在请求 DeepSeek...`;

  // 简化的 DeepSeek 模拟逻辑，主要通过 JSON 模式返回结构化行程
  const response = await fetch('https://api.deepseek.com/v1/chat/completions', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiKey}` },
    body: JSON.stringify({
      model: model,
      messages: [
        { role: 'system', content: `你是一个导游。请以 JSON 格式返回行程，包含 summary 字符串和 locations 数组。locations 数组项必须包含 name, lat, lng, description, weather, temperature, day, sequence, time。` },
        { role: 'user', content: input }
      ],
      response_format: { type: 'json_object' }
    })
  });

  const data = await response.json();
  if (data.error) throw new Error(data.error.message);

  const content = JSON.parse(data.choices[0].message.content);
  itinerarySummary = content.summary || "";
  if (content.locations) {
    for (const loc of content.locations) {
      await setPin(loc);
    }
  }
}

async function setPin(args: any) {
  const { name, lat, lng, weather, temperature } = args;
  const pos = { lat: parseFloat(lat), lng: parseFloat(lng) };
  if (isNaN(pos.lat) || isNaN(pos.lng)) return;

  bounds.extend(pos);
  const marker = new google.maps.Marker({
    position: pos,
    title: name,
    map: map,
    icon: {
      path: google.maps.SymbolPath.CIRCLE,
      fillColor: '#ff5722', fillOpacity: 1, strokeWeight: 2, strokeColor: '#fff', scale: 10
    }
  });

  const weatherIcon = getWeatherIconClass(weather);
  const content = document.createElement('div');
  content.innerHTML = `<div style="padding:5px;"><strong>${name}</strong><br><small><i class="fas ${weatherIcon}"></i> ${temperature} ${weather}</small></div>`;
  const popup = new (window as any).Popup(new google.maps.LatLng(pos), content);

  const item = { ...args, position: new google.maps.LatLng(pos), popup, marker };
  dayPlanItinerary.push(item);
  popUps.push(item);
  map.fitBounds(bounds);
}

function createTimeline() {
  const t = getEl('timeline');
  t.innerHTML = '';

  if (groundingSources.length > 0) {
    const gBox = document.createElement('div');
    gBox.className = 'grounding-box';
    gBox.innerHTML = `<h4><i class="fas fa-search"></i> 搜索来源</h4><div class="grounding-list"></div>`;
    groundingSources.forEach(chunk => {
      if (chunk.web) {
        const a = document.createElement('a');
        a.href = chunk.web.uri; a.target = '_blank'; a.className = 'grounding-link';
        a.innerText = chunk.web.title || '网页来源';
        gBox.querySelector('.grounding-list')?.appendChild(a);
      }
    });
    t.appendChild(gBox);
  }

  if (xhsNotes.length > 0) {
    const xhsBox = document.createElement('div');
    xhsBox.className = 'xhs-highlights';
    xhsBox.innerHTML = `<h4><i class="fab fa-red-river"></i> 小红书实时灵感</h4><div class="xhs-list"></div>`;
    xhsNotes.forEach(note => {
      const nDiv = document.createElement('div');
      nDiv.className = 'xhs-note-pill';
      nDiv.innerText = note.title || "查看热门笔记";
      xhsBox.querySelector('.xhs-list')?.appendChild(nDiv);
    });
    t.appendChild(xhsBox);
  }

  let currentDay = -1;
  dayPlanItinerary.forEach((item, index) => {
    if (item.day !== currentDay) {
      currentDay = item.day;
      const h = document.createElement('div');
      h.className = 'day-header';
      h.innerHTML = `<span>第 ${currentDay} 天</span> <small>${item.weather} ${item.temperature}</small>`;
      t.appendChild(h);
    }
    const div = document.createElement('div');
    div.className = `timeline-item`;
    div.onclick = () => highlightCard(index, true);
    div.innerHTML = `
      <div class="timeline-time">${item.time}</div>
      <div class="timeline-content">
        <div class="timeline-title">${item.name}</div>
        <div class="timeline-description">${item.description}</div>
        ${item.transit_hint ? `<div class="transit-box"><i class="fas fa-bus"></i> ${item.transit_hint}</div>` : ''}
      </div>`;
    t.appendChild(div);
  });
}

function exportItinerary() {
  if (dayPlanItinerary.length === 0) return;
  let md = `# 📅 行程指南\n\n`;
  dayPlanItinerary.forEach(i => {
    md += `## Day ${i.day}: ${i.name}\n- 天气: ${i.weather} (${i.temperature})\n- 建议: ${i.description}\n\n`;
  });
  const blob = new Blob([md], { type: 'text/markdown' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = `行程手册.md`;
  a.click();
}

function drawRoute() {
  if (polyline) polyline.setMap(null);
  polyline = new google.maps.Polyline({
    path: dayPlanItinerary.map(i => i.position),
    strokeColor: '#ff5722', strokeOpacity: 0.8, strokeWeight: 4, map: map
  });
}

function createCards() {
  const container = getEl('card-container');
  container.innerHTML = '';
  getEl('card-carousel').classList.remove('hidden');
  dayPlanItinerary.forEach((loc, index) => {
    const card = document.createElement('div');
    card.className = `location-card`;
    card.innerHTML = `<div class="card-title">${loc.name}</div><div class="card-weather">${loc.temperature} ${loc.weather}</div>`;
    card.onclick = () => highlightCard(index, true);
    container.appendChild(card);
  });
}

function highlightCard(index: number, scroll: boolean = false) {
  popUps.forEach(p => p.popup.setMap(null));
  activeCardIndex = Math.max(0, Math.min(index, dayPlanItinerary.length - 1));
  const item = dayPlanItinerary[activeCardIndex];
  if (item) {
    item.popup.setMap(map);
    map.panTo(item.position);
  }
}

function restart() {
  markers.forEach(m => m.setMap(null));
  popUps.forEach(p => p.popup.setMap(null));
  if (polyline) polyline.setMap(null);
  markers = []; popUps = []; dayPlanItinerary = []; xhsNotes = []; groundingSources = [];
  getEl('card-container').innerHTML = '';
  getEl('card-carousel').classList.add('hidden');
  getEl('timeline-container').classList.remove('visible');
  bounds = new google.maps.LatLngBounds();
  setStatus("", "hidden");
}

function setStatus(msg: string, type: string) {
  const err = getEl('error-message');
  if (type === 'hidden') { err.classList.add('hidden'); return; }
  err.innerText = msg; err.className = `error ${type}`; err.classList.remove('hidden');
}

function bindEvents() {
  getEl('planner-mode-toggle').onchange = (e) => {
    isPlannerMode = (e.target as HTMLInputElement).checked;
    getEl('mode-text').innerText = isPlannerMode ? "行程规划模式" : "景点发现模式";
    getEl('prompt-input').setAttribute('placeholder', isPlannerMode ? "例如：规划一次北京三日游..." : "搜索打卡点、美食...");
    restart();
  };
  getEl('generate').onclick = handleRequest;
  getEl('reset').onclick = restart;
  getEl('export-btn').onclick = exportItinerary;
  getEl('close-timeline').onclick = hideTimeline;
  getEl('reopen-timeline').onclick = showTimeline;
  getEl('toggle-search-ui').onclick = () => {
    isUiHidden = !isUiHidden;
    getEl('search-container').classList.toggle('ui-hidden', isUiHidden);
    getEl('toggle-search-ui').innerHTML = isUiHidden ? '<i class="fas fa-eye"></i>' : '<i class="fas fa-eye-slash"></i>';
  };

  // 绑定设置相关事件
  getEl('open-settings').onclick = () => getEl('settings-modal').classList.remove('hidden');
  getEl('close-settings').onclick = () => getEl('settings-modal').classList.add('hidden');
  getEl('save-settings').onclick = () => {
    const key = (getEl('deepseek-key-input') as HTMLInputElement).value.trim();
    localStorage.setItem('deepseek_api_key', key);
    getEl('settings-modal').classList.add('hidden');
  };
}

function hideTimeline() { 
  getEl('timeline-container').classList.remove('visible'); 
  if (dayPlanItinerary.length > 0) getEl('reopen-timeline').classList.remove('hidden'); 
}

function showTimeline() { 
  getEl('timeline-container').classList.add('visible'); 
  getEl('reopen-timeline').classList.add('hidden'); 
}

initApp();

@import url(https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css);

:root {
  --primary: #ff5722;
  --primary-hover: #f4511e;
  --glass: rgba(255, 255, 255, 0.85);
  --glass-dark: rgba(20, 20, 20, 0.85);
  --shadow: 0 8px 32px rgba(0,0,0,0.2);
  --radius: 20px;
}

* { box-sizing: border-box; padding: 0; margin: 0; font-family: 'Segoe UI', system-ui, -apple-system, sans-serif; }

html, body { height: 100%; width: 100%; overflow: hidden; background: #000; color: #333; }

.hidden { display: none !important; }

/* 地图容器 */
