  position: fixed; inset: 0; background: rgba(0,0,0,0.7); 
  backdrop-filter: blur(5px); z-index: 9000; display: flex; 
  align-items: center; justify-content: center; 
}
.modal-content { 
  background: white; padding: 30px; border-radius: var(--radius); 
  width: 90%; max-width: 420px; box-shadow: var(--shadow); 
}
.modal-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 20px; }
.close-modal-btn { border: none; background: none; font-size: 24px; cursor: pointer; }
.settings-hint { font-size: 13px; color: #666; margin-bottom: 15px; }
.input-group label { display: block; font-size: 12px; font-weight: 800; margin-bottom: 6px; color: #333; }
