async function handleGeminiRequest(model: string, input: string, preference: string) {
  const prefText = preference === 'budget' ? "【经济性价比偏好】（多使用公共交通、挖掘高性价比美食）" : "【时间宽松偏好】（行程节奏放慢，强调深度体验，避免特种兵式赶路）";

  const response = await ai.models.generateContent({
    model: model,
    contents: input,
    config: {
      systemInstruction: `你是一个顶级深度定制旅游博主。
      任务要求：
