  if (polyline) polyline.setMap(null);
  polyline = new google.maps.Polyline({
    path: dayPlanItinerary.map(i => i.position),
    strokeColor: '#ff5722', strokeOpacity: 0.8, strokeWeight: 4, map: map
  });
}

function restart() {
  markers.forEach(m => m.setMap(null));
  popUps.forEach(p => p.popup.setMap(null));
  if (polyline) polyline.setMap(null);
  markers = []; popUps = []; dayPlanItinerary = []; xhsNotes = []; groundingSources = [];
  getEl('card-container').innerHTML = '';
  getEl('card-carousel').classList.add('hidden');
  getEl('timeline-container').classList.remove('visible');
  bounds = new google.maps.LatLngBounds();
  setStatus("", "hidden");
}

function setStatus(msg: string, type: string) {
  const err = getEl('error-message');
  if (type === 'hidden') { err.classList.add('hidden'); return; }
  err.innerText = msg; err.className = `error ${type}`; err.classList.remove('hidden');
}

function bindEvents() {
  getEl('planner-mode-toggle').onchange = (e) => {
    isPlannerMode = (e.target as HTMLInputElement).checked;
    getEl('mode-text').innerText = isPlannerMode ? "行程规划模式" : "景点发现模式";
    getEl('prompt-input').setAttribute('placeholder', isPlannerMode ? "例如：北京3天深度游，带孩子..." : "搜索周边好吃的或打卡点...");

    // 切换模式时显示/隐藏偏好设置
    const prefGroup = getEl('preference-toggle-group');
    if (isPlannerMode) prefGroup.classList.remove('hidden');
    else prefGroup.classList.add('hidden');

    restart();
  };

  getEl('generate').onclick = handleRequest;
  getEl('reset').onclick = restart;
  getEl('export-btn').onclick = () => {
    let md = `# 📅 行程指南\n\n${itinerarySummary}\n\n`;
    dayPlanItinerary.forEach(i => md += `### Day ${i.day}: ${i.name}\n- 时间: ${i.time}\n- 详情: ${i.description}\n\n`);
    const blob = new Blob([md], { type: 'text/markdown' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = `行程指南.md`;
    a.click();
  };
  getEl('close-timeline').onclick = hideTimeline;
  getEl('reopen-timeline').onclick = showTimeline;
  getEl('toggle-search-ui').onclick = () => {
    isUiHidden = !isUiHidden;
    getEl('search-container').classList.toggle('ui-hidden', isUiHidden);
    getEl('toggle-search-ui').innerHTML = isUiHidden ? '<i class="fas fa-eye"></i>' : '<i class="fas fa-eye-slash"></i>';
  };
  getEl('open-settings').onclick = () => getEl('settings-modal').classList.remove('hidden');
  getEl('close-settings').onclick = () => getEl('settings-modal').classList.add('hidden');
  getEl('save-settings').onclick = () => {
    const key = (getEl('deepseek-key-input') as HTMLInputElement).value.trim();
    localStorage.setItem('deepseek_api_key', key);
    getEl('settings-modal').classList.add('hidden');
  };
}

function hideTimeline() { 
  getEl('timeline-container').classList.remove('visible'); 
  if (dayPlanItinerary.length > 0) getEl('reopen-timeline').classList.remove('hidden'); 
}

function showTimeline() { 
  getEl('timeline-container').classList.add('visible'); 
  getEl('reopen-timeline').classList.add('hidden'); 
}

initApp();

@import url(https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css);

:root {
  --primary: #ff5722;
  --primary-hover: #f4511e;
  --glass: rgba(255, 255, 255, 0.95);
  --glass-dark: rgba(20, 20, 20, 0.85);
  --shadow: 0 10px 40px rgba(0,0,0,0.15);
  --radius: 20px;
}

* { box-sizing: border-box; padding: 0; margin: 0; font-family: 'Segoe UI', system-ui, -apple-system, sans-serif; }

html, body { height: 100%; width: 100%; overflow: hidden; background: #fdfdfd; color: #333; }

.hidden { display: none !important; }

/* 地图容器 */
.map-container { position: relative; height: 100%; width: 100%; }
#map { height: 100%; width: 100%; background: #f0f0f0; }

/* 搜索与控制中心 */
.search-container { 
  position: absolute; top: 24px; left: 50%; transform: translateX(-50%); 
  z-index: 2500; width: 95%; max-width: 720px; 
  transition: all 0.4s cubic-bezier(0.16, 1, 0.3, 1);
}
.search-container.ui-hidden { transform: translate(-50%, -300px); opacity: 0; pointer-events: none; }

/* 顶部控制组 */
.search-header-group { 
  display: flex; justify-content: space-between; align-items: center; 
  margin-bottom: 12px; gap: 10px;
  flex-wrap: wrap;
}

.header-left-controls { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }

.preference-group {
  display: flex;
  align-items: center;
  gap: 10px;
}

.switch { position: relative; display: inline-block; width: 44px; height: 24px; }
.switch input { opacity: 0; width: 0; height: 0; }
.slider { position: absolute; cursor: pointer; top: 0; left: 0; right: 0; bottom: 0; background-color: #ccc; transition: .4s; }
.slider:before { position: absolute; content: ""; height: 18px; width: 18px; left: 3px; bottom: 3px; background-color: white; transition: .4s; }
input:checked + .slider { background-color: var(--primary); }
input:checked + .slider:before { transform: translateX(20px); }
.slider.round { border-radius: 24px; }
.slider.round:before { border-radius: 50%; }

.mode-toggle { 
  background: var(--glass); backdrop-filter: blur(15px); 
  padding: 8px 16px; border-radius: 30px; 
  display: flex; align-items: center; gap: 10px; box-shadow: var(--shadow);
}
.mode-label { font-size: 13px; font-weight: 800; color: #444; min-width: 80px; }

.model-select {
  padding: 8px 16px; border-radius: 30px; border: none; 
  background: var(--glass); backdrop-filter: blur(15px);
  font-size: 13px; font-weight: 700; color: #333; outline: none;
  box-shadow: var(--shadow); cursor: pointer;
}

.icon-btn-small {
  background: var(--glass); border: none; width: 40px; height: 40px; border-radius: 50%;
  cursor: pointer; display: flex; align-items: center; justify-content: center;
  box-shadow: var(--shadow); transition: 0.3s;
}
.icon-btn-small:hover { transform: scale(1.1); background: #fff; }

/* 搜索主栏 */
.search-bar-stack { 
  background: var(--glass); backdrop-filter: blur(20px);
  border-radius: var(--radius); padding: 10px 15px; 
  box-shadow: var(--shadow); border: 1px solid rgba(255,255,255,0.4);
}
.search-bar { display: flex; align-items: center; gap: 12px; }
#prompt-input { 
  flex: 1; border: none; outline: none; font-size: 16px; 
  min-height: 54px; background: transparent; resize: none;
  padding: 12px 0; line-height: 1.5; color: #111;
}
.search-button { 
  background: var(--primary); color: white; border: none; 
  width: 50px; height: 50px; border-radius: 50%; cursor: pointer; 
  display: flex; align-items: center; justify-content: center;
  transition: 0.3s; box-shadow: 0 4px 15px rgba(255,87,34,0.3);
}
.search-button:hover { transform: scale(1.05); background: var(--primary-hover); }

/* 悬浮功能按钮 */
.floating-control-btn { 
  position: absolute; z-index: 2800; width: 54px; height: 54px; border-radius: 50%; 
  background: var(--glass); backdrop-filter: blur(10px); border: none; 
  box-shadow: var(--shadow); cursor: pointer; display: flex; 
  align-items: center; justify-content: center; font-size: 22px;
  transition: 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}
.floating-control-btn:hover { background: #fff; transform: scale(1.1); color: var(--primary); }

.toggle-ui-btn { top: 24px; left: 24px; }
.reopen-timeline-btn { top: 24px; right: 24px; background: var(--primary); color: white; }
.reset-button { bottom: 40px; right: 24px; }

/* 底部卡片轮播 */
.card-carousel { position: absolute; bottom: 40px; width: 100%; z-index: 2200; pointer-events: none; }
.card-container { 
  display: flex; overflow-x: auto; padding: 20px 40px; gap: 20px; 
  scrollbar-width: none; pointer-events: auto; 
  scroll-snap-type: x mandatory;
}
.card-container::-webkit-scrollbar { display: none; }

.location-card { 
  flex: 0 0 280px; background: white; border-radius: var(--radius); padding: 20px; 
  box-shadow: var(--shadow); cursor: pointer; border-left: 8px solid var(--primary); 
  transition: 0.4s cubic-bezier(0.16, 1, 0.3, 1); scroll-snap-align: center;
}
.location-card:hover { transform: translateY(-15px); }
.card-title { font-weight: 800; font-size: 18px; margin-bottom: 10px; color: #111; }
.card-weather { font-size: 13px; color: var(--primary); font-weight: 800; text-transform: uppercase; letter-spacing: 1px; }

/* 时间轴容器 */
.timeline-container { 
  position: fixed; right: 0; top: 0; width: 440px; height: 100%; 
  background: white; z-index: 4000; transform: translateX(100%); 
  transition: 0.6s cubic-bezier(0.16, 1, 0.3, 1); 
  box-shadow: -15px 0 50px rgba(0,0,0,0.1); display: flex; flex-direction: column; 
}
.timeline-container.visible { transform: translateX(0); }
.timeline-header { padding: 30px; border-bottom: 1px solid #f0f0f0; display: flex; justify-content: space-between; align-items: center; }
.timeline { padding: 30px; overflow-y: auto; flex: 1; }

.day-header { padding: 12px 20px; background: #222; color: white; border-radius: 12px; margin: 25px 0 15px; font-weight: 800; font-size: 15px; }
.timeline-item { border-left: 4px solid #f0f0f0; padding-left: 25px; margin-bottom: 25px; cursor: pointer; position: relative; transition: 0.3s; }
.timeline-item:hover { border-color: var(--primary); }
.timeline-time { font-weight: 800; color: var(--primary); font-size: 13px; margin-bottom: 6px; }
.timeline-title { font-size: 18px; font-weight: 800; color: #000; margin-bottom: 6px; }
.timeline-description { color: #555; font-size: 15px; line-height: 1.6; }

.xhs-highlights { background: #fff8f6; border: 1px solid #ffe8e2; border-radius: 18px; padding: 20px; margin-bottom: 25px; }
.xhs-highlights h4 { color: #ff2442; font-size: 15px; font-weight: 900; margin-bottom: 12px; }
.xhs-list { display: flex; flex-wrap: wrap; gap: 10px; }
.xhs-note-pill { background: white; border: 1px solid #ffccd5; padding: 8px 16px; border-radius: 25px; font-size: 13px; color: #ff2442; font-weight: 700; transition: 0.2s; }
.xhs-note-pill:hover { background: #ff2442; color: white; transform: scale(1.05); }

.spinner { position: fixed; inset: 0; background: rgba(255,255,255,0.95); backdrop-filter: blur(10px); z-index: 6000; display: flex; flex-direction: column; align-items: center; justify-content: center; }
.spinner::after { content: ''; width: 60px; height: 60px; border: 5px solid #f0f0f0; border-top-color: var(--primary); border-radius: 50%; animation: spin 0.8s cubic-bezier(0.16, 1, 0.3, 1) infinite; margin-bottom: 25px; }
@keyframes spin { to { transform: rotate(360deg); } }
.loading-text { color: #222; font-weight: 800; font-size: 18px; }

.error { background: #fee2e2; color: #dc2626; padding: 12px 18px; border-radius: 15px; margin-top: 15px; font-size: 14px; font-weight: 700; box-shadow: 0 4px 15px rgba(220,38,38,0.1); }

.popup-bubble { 
  background: white; padding: 12px 18px; border-radius: 15px; 
  box-shadow: var(--shadow); min-width: 160px; 
  position: relative; border-bottom: 4px solid var(--primary);
  font-weight: 700; text-align: center;
}

