@import url(https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css);

:root {
  --primary: #ff5722;
  --primary-hover: #f4511e;
  --glass: rgba(255, 255, 255, 0.95);
  --shadow: 0 4px 12px rgba(0,0,0,0.1);
  --radius: 12px;
}

* { box-sizing: border-box; padding: 0; margin: 0; font-family: 'PingFang SC', system-ui, sans-serif; }

html, body { height: 100%; width: 100%; overflow: hidden; background: #fff; }

.hidden { display: none !important; }

/* 地图全屏 */
.map-container { position: absolute; inset: 0; z-index: 1; }
#map { height: 100%; width: 100%; }

/* 搜索UI */
.search-container { 
  position: absolute; top: 16px; left: 50%; transform: translateX(-50%); 
  z-index: 100; width: 90%; max-width: 600px; 
  transition: all 0.3s ease;
}
.search-container.ui-hidden { transform: translate(-50%, -200px); opacity: 0; pointer-events: none; }

.search-header-group { display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px; gap: 8px; }

.mode-toggle { 
  background: var(--glass); padding: 4px 10px; border-radius: 20px; 
  display: flex; align-items: center; gap: 8px; box-shadow: var(--shadow);
}
.mode-label { font-size: 11px; font-weight: bold; color: #555; }

.switch { position: relative; width: 32px; height: 18px; }
.switch input { opacity: 0; width: 0; height: 0; }
.slider { position: absolute; inset: 0; background-color: #ddd; transition: .3s; border-radius: 20px; cursor: pointer; }
.slider:before { position: absolute; content: ""; height: 14px; width: 14px; left: 2px; bottom: 2px; background-color: white; transition: .3s; border-radius: 50%; }
input:checked + .slider { background-color: var(--primary); }
input:checked + .slider:before { transform: translateX(14px); }

.model-select {
  padding: 4px 10px; border-radius: 20px; border: none; background: var(--glass); 
  font-size: 11px; font-weight: bold; box-shadow: var(--shadow); cursor: pointer; outline: none;
}

.search-bar-stack { background: var(--glass); border-radius: 14px; padding: 4px 10px; box-shadow: var(--shadow); }
.search-bar { display: flex; align-items: center; gap: 8px; }
#prompt-input { flex: 1; border: none; outline: none; font-size: 14px; min-height: 40px; background: transparent; resize: none; padding: 8px 0; }
.search-button { background: var(--primary); color: white; border: none; width: 34px; height: 34px; border-radius: 50%; cursor: pointer; }

/* 极简卡片轮播 - 更小且更不显眼 */
.card-carousel { position: absolute; bottom: 16px; left: 0; right: 0; z-index: 50; pointer-events: none; }
.card-container { display: flex; overflow-x: auto; padding: 8px 16px; gap: 8px; scrollbar-width: none; pointer-events: auto; }
.card-container::-webkit-scrollbar { display: none; }

.location-card { 
  flex: 0 0 auto; min-width: 140px; background: white; border-radius: 30px; 
  padding: 6px 12px; box-shadow: 0 2px 8px rgba(0,0,0,0.1); 
  cursor: pointer; border: 1px solid #f0f0f0; display: flex; gap: 8px;
  align-items: center; transition: 0.2s; white-space: nowrap;
}
.location-card.active { border-color: var(--primary); background: #fff8f6; transform: scale(1.05); }

.card-day-mini { background: var(--primary); color: white; font-size: 9px; font-weight: 900; padding: 1px 5px; border-radius: 10px; }
.card-info-mini { overflow: hidden; }
.card-title-mini { font-weight: bold; font-size: 12px; color: #333; }
.card-time-mini { font-size: 10px; color: #999; }

/* 浮动按钮 */
.floating-control-btn { 
  position: absolute; z-index: 150; width: 40px; height: 40px; border-radius: 50%; 
  background: var(--glass); border: none; box-shadow: var(--shadow); cursor: pointer; 
  display: flex; align-items: center; justify-content: center; font-size: 16px;
}
.toggle-ui-btn { top: 16px; left: 16px; }
.reopen-timeline-btn { top: 16px; right: 16px; background: var(--primary); color: white; }
.reset-button { bottom: 60px; right: 16px; }

/* 时间轴 */
.timeline-container { 
  position: fixed; right: 0; top: 0; width: 320px; height: 100%; 
  background: white; z-index: 500; transform: translateX(100%); 
  transition: 0.3s ease; box-shadow: -4px 0 20px rgba(0,0,0,0.05);
}
.timeline-container.visible { transform: translateX(0); }
.timeline-header { padding: 16px; border-bottom: 1px solid #f0f0f0; display: flex; justify-content: space-between; align-items: center; }
.timeline { padding: 16px; overflow-y: auto; height: calc(100% - 60px); }

.day-header { padding: 6px 10px; background: #444; color: white; border-radius: 6px; margin: 12px 0 8px; font-size: 11px; font-weight: bold; }
.timeline-item { border-left: 2px solid #eee; padding-left: 12px; margin-bottom: 16px; cursor: pointer; }
.timeline-time { font-weight: bold; color: var(--primary); font-size: 11px; margin-bottom: 2px; }
.timeline-title { font-size: 14px; font-weight: bold; }
.timeline-description { color: #666; font-size: 12px; line-height: 1.4; }

/* 气泡 */
.custom-map-popup { position: absolute; transform: translate(-50%, -100%); margin-top: -10px; pointer-events: none; }
.popup-bubble { 
  background: white; padding: 4px 8px; border-radius: 6px; box-shadow: var(--shadow);
  border-bottom: 2px solid var(--primary); font-size: 11px; pointer-events: auto;
}

.spinner { position: fixed; inset: 0; background: rgba(255,255,255,0.8); backdrop-filter: blur(4px); z-index: 1000; display: flex; flex-direction: column; align-items: center; justify-content: center; }
.spinner::after { content: ''; width: 30px; height: 30px; border: 3px solid #eee; border-top-color: var(--primary); border-radius: 50%; animation: spin 1s linear infinite; margin-bottom: 12px; }
@keyframes spin { to { transform: rotate(360deg); } }
.error { background: #fee2e2; color: #ef4444; padding: 8px 12px; border-radius: 8px; margin-top: 8px; font-size: 12px; }

