      model: model,
      messages: [
        { role: 'system', content: `你是一位顶级旅游行程规划专家。请为用户需求规划行程，并针对行程中的每一个具体景点、餐厅、酒店【必须】调用 location 工具进行地图标注。不要只在文本中描述地点，必须确保调用 location 函数。` },
        { role: 'user', content: input }
      ],
      tools: tools,
      tool_choice: "auto"
    })
  });

  if (!response.ok) {
    const errData = await response.json().catch(() => ({}));
    throw new Error(`DeepSeek API 请求失败 (${response.status}): ${errData.error?.message || response.statusText}`);
  }

  const data = await response.json();
  if (!data.choices || data.choices.length === 0) {
    throw new Error("DeepSeek 未返回有效结果。");
  }

  const message = data.choices[0].message;

  // 保存文本内容
  itinerarySummary = message.content || "";

  // 解析并处理工具调用
  if (message.tool_calls && Array.isArray(message.tool_calls)) {
    for (const tc of message.tool_calls) {
      if (tc.type === 'function' && tc.function.name === 'location') {
        try {
          const args = JSON.parse(tc.function.arguments);
          await setPin(args);
        } catch (e) {
          console.error("解析 DeepSeek 工具参数失败:", e, tc.function.arguments);
        }
      }
    }
  }

  // 兜底文本
  if (!itinerarySummary && dayPlanItinerary.length > 0) {
    itinerarySummary = "已为您生成详细的地图标注，请点击下方卡片或查看行程指南。";
  }
}

async function setPin(args: any) {
  const { name, lat, lng } = args;
  const pos = { lat: parseFloat(lat), lng: parseFloat(lng) };
  if (isNaN(pos.lat) || isNaN(pos.lng)) return;

  bounds.extend(pos);
  const marker = new google.maps.Marker({
    position: pos,
    title: name,
    map: map,
    icon: {
      path: google.maps.SymbolPath.CIRCLE,
      fillColor: '#ff5722', fillOpacity: 1, strokeWeight: 2, strokeColor: '#fff', scale: 8
    }
  });

  const content = document.createElement('div');
  content.innerHTML = `<strong style="font-size:11px;">${name}</strong>`;
  const popup = new (window as any).Popup(new google.maps.LatLng(pos), content);

  const item = { ...args, position: new google.maps.LatLng(pos), popup, marker };
  dayPlanItinerary.push(item);
  popUps.push(item);
  map.fitBounds(bounds);
}

function createTimeline() {
  const t = getEl('timeline');
  t.innerHTML = `<div class="itinerary-summary-text">${itinerarySummary}</div>`;

  let currentDay = -1;
  dayPlanItinerary.forEach((item, index) => {
    if (item.day !== currentDay) {
      currentDay = item.day;
      const h = document.createElement('div');
      h.className = 'day-header';
      h.innerHTML = `D${currentDay}`;
      t.appendChild(h);
    }
    const div = document.createElement('div');
    div.className = `timeline-item`;
    div.onclick = () => highlightCard(index, true);
    div.innerHTML = `
      <div class="timeline-time">${item.time}</div>
      <div class="timeline-content">
        <div class="timeline-title">${item.name}</div>
        <div class="timeline-description">${item.description}</div>
      </div>`;
    t.appendChild(div);
  });
}

function createCards() {
  const container = getEl('card-container');
  container.innerHTML = '';
  getEl('card-carousel').classList.remove('hidden');
  dayPlanItinerary.forEach((loc, index) => {
    const card = document.createElement('div');
    card.className = `location-card`;
    card.innerHTML = `
      <div class="card-day-mini">D${loc.day}</div>
      <div class="card-info-mini">
        <div class="card-title-mini">${loc.name}</div>
        <div class="card-time-mini">${loc.time}</div>
      </div>
    `;
    card.onclick = () => highlightCard(index, true);
    container.appendChild(card);
  });
}

function highlightCard(index: number, scroll: boolean = false) {
  popUps.forEach(p => p.popup.setMap(null));
  activeCardIndex = Math.max(0, Math.min(index, dayPlanItinerary.length - 1));
  const item = dayPlanItinerary[activeCardIndex];
  if (item) {
    item.popup.setMap(map);
    map.panTo(item.position);
    if (scroll) {
      const cards = document.querySelectorAll('.location-card');
      cards[activeCardIndex]?.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'center' });
      cards.forEach(c => c.classList.remove('active'));
      cards[activeCardIndex]?.classList.add('active');
    }
  }
}

function drawRoute() {
  if (polyline) polyline.setMap(null);
  polyline = new google.maps.Polyline({
    path: dayPlanItinerary.map(i => i.position),
    strokeColor: '#ff5722', strokeOpacity: 0.6, strokeWeight: 2, map: map
  });
}

function restart() {
  popUps.forEach(p => p.popup.setMap(null));
  if (polyline) polyline.setMap(null);
  dayPlanItinerary = [];
  getEl('card-container').innerHTML = '';
  getEl('card-carousel').classList.add('hidden');
  getEl('timeline-container').classList.remove('visible');
  bounds = new google.maps.LatLngBounds();
  setStatus("", "hidden");
}

function setStatus(msg: string, type: string) {
  const err = getEl('error-message');
  if (type === 'hidden') { err.classList.add('hidden'); return; }
  err.innerText = msg; err.className = `error ${type}`; err.classList.remove('hidden');
}

function bindEvents() {
  getEl('planner-mode-toggle').onchange = (e) => {
    isPlannerMode = (e.target as HTMLInputElement).checked;
    getEl('mode-text').innerText = isPlannerMode ? "行程规划模式" : "景点发现模式";
    const prefGroup = getEl('preference-toggle-group');
    if (isPlannerMode) prefGroup.classList.remove('hidden');
    else prefGroup.classList.add('hidden');
    restart();
  };
  getEl('generate').onclick = handleRequest;
  getEl('reset').onclick = restart;
  getEl('export-btn').onclick = () => {
    let md = `# 行程指南\n\n${itinerarySummary}\n\n`;
    dayPlanItinerary.forEach(i => md += `## Day ${i.day}: ${i.name}\n- 时间: ${i.time}\n- 详情: ${i.description}\n\n`);
    const blob = new Blob([md], { type: 'text/markdown' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = `行程指南.md`;
    a.click();
  };
  getEl('close-timeline').onclick = hideTimeline;
  getEl('reopen-timeline').onclick = showTimeline;
  getEl('toggle-search-ui').onclick = () => {
    isUiHidden = !isUiHidden;
    getEl('search-container').classList.toggle('ui-hidden', isUiHidden);
    getEl('toggle-search-ui').innerHTML = isUiHidden ? '<i class="fas fa-eye"></i>' : '<i class="fas fa-eye-slash"></i>';
  };
  getEl('open-settings').onclick = () => getEl('settings-modal').classList.remove('hidden');
  getEl('close-settings').onclick = () => getEl('settings-modal').classList.add('hidden');
  getEl('save-settings').onclick = () => {
    const val = (getEl('deepseek-key-input') as HTMLInputElement).value.trim();
    localStorage.setItem('deepseek_api_key', val);
    getEl('settings-modal').classList.add('hidden');
  };
}

function hideTimeline() { 
  getEl('timeline-container').classList.remove('visible'); 
  if (dayPlanItinerary.length > 0) getEl('reopen-timeline').classList.remove('hidden'); 
}

function showTimeline() { 
  getEl('timeline-container').classList.add('visible'); 
  getEl('reopen-timeline').classList.add('hidden'); 
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initApp);
} else {
  initApp();
}

@import url(https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css);

:root {
  --primary: #ff5722;
  --primary-hover: #f4511e;
  --glass: rgba(255, 255, 255, 0.95);
  --shadow: 0 4px 12px rgba(0,0,0,0.1);
  --radius: 12px;
}

* { box-sizing: border-box; padding: 0; margin: 0; font-family: 'PingFang SC', system-ui, sans-serif; }

html, body { height: 100%; width: 100%; overflow: hidden; background: #fff; }

.hidden { display: none !important; }

/* 地图全屏 */
.map-container { position: absolute; inset: 0; z-index: 1; }
#map { height: 100%; width: 100%; }

/* 搜索UI */
.search-container { 
  position: absolute; top: 16px; left: 50%; transform: translateX(-50%); 
  z-index: 100; width: 90%; max-width: 600px; 
  transition: all 0.3s ease;
}
.search-container.ui-hidden { transform: translate(-50%, -200px); opacity: 0; pointer-events: none; }

.search-header-group { display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px; gap: 8px; }

.header-left-controls { display: flex; align-items: center; gap: 10px; }

.mode-toggle { 
  background: var(--glass); padding: 4px 10px; border-radius: 20px; 
  display: flex; align-items: center; gap: 8px; box-shadow: var(--shadow);
}
.mode-label { font-size: 11px; font-weight: bold; color: #555; }

.switch { position: relative; width: 32px; height: 18px; }
.switch input { opacity: 0; width: 0; height: 0; }
.slider { position: absolute; inset: 0; background-color: #ddd; transition: .3s; border-radius: 20px; cursor: pointer; }
.slider:before { position: absolute; content: ""; height: 14px; width: 14px; left: 2px; bottom: 2px; background-color: white; transition: .3s; border-radius: 50%; }
input:checked + .slider { background-color: var(--primary); }
input:checked + .slider:before { transform: translateX(14px); }

.model-select {
  padding: 4px 10px; border-radius: 20px; border: none; background: var(--glass); 
  font-size: 11px; font-weight: bold; box-shadow: var(--shadow); cursor: pointer; outline: none;
}

.icon-btn-small { background: var(--glass); border: none; width: 28px; height: 28px; border-radius: 50%; box-shadow: var(--shadow); cursor: pointer; display: flex; align-items: center; justify-content: center; color: #555; }

.search-bar-stack { background: var(--glass); border-radius: 14px; padding: 4px 10px; box-shadow: var(--shadow); }
.search-bar { display: flex; align-items: center; gap: 8px; }
#prompt-input { flex: 1; border: none; outline: none; font-size: 14px; min-height: 40px; background: transparent; resize: none; padding: 8px 0; }
.search-button { background: var(--primary); color: white; border: none; width: 34px; height: 34px; border-radius: 50%; cursor: pointer; transition: 0.2s; }
.search-button:hover { background: var(--primary-hover); transform: scale(1.05); }

/* 极简卡片轮播 */
.card-carousel { position: absolute; bottom: 16px; left: 0; right: 0; z-index: 50; pointer-events: none; }
.card-container { display: flex; overflow-x: auto; padding: 8px 16px; gap: 8px; scrollbar-width: none; pointer-events: auto; }
.card-container::-webkit-scrollbar { display: none; }

.location-card { 
  flex: 0 0 auto; min-width: 140px; background: white; border-radius: 30px; 
  padding: 6px 14px; box-shadow: 0 2px 8px rgba(0,0,0,0.1); 
  cursor: pointer; border: 1px solid #f0f0f0; display: flex; gap: 8px;
  align-items: center; transition: 0.2s; white-space: nowrap;
}
.location-card.active { border-color: var(--primary); background: #fff8f6; transform: scale(1.05); box-shadow: 0 0 15px rgba(255, 87, 34, 0.2); }

.card-day-mini { background: var(--primary); color: white; font-size: 10px; font-weight: 900; padding: 2px 6px; border-radius: 10px; }
.card-info-mini { overflow: hidden; }
.card-title-mini { font-weight: bold; font-size: 13px; color: #333; }
.card-time-mini { font-size: 11px; color: #999; }

/* 浮动按钮 */
.floating-control-btn { 
  position: absolute; z-index: 150; width: 42px; height: 42px; border-radius: 50%; 
  background: var(--glass); border: none; box-shadow: var(--shadow); cursor: pointer; 
  display: flex; align-items: center; justify-content: center; font-size: 18px; color: #333; transition: 0.2s;
}
.floating-control-btn:hover { background: white; transform: translateY(-2px); }
.toggle-ui-btn { top: 16px; left: 16px; }
.reopen-timeline-btn { top: 16px; right: 16px; background: var(--primary); color: white; }
.reset-button { bottom: 65px; right: 16px; }

/* 时间轴侧边栏 */
.timeline-container { 
  position: fixed; right: 0; top: 0; width: 340px; height: 100%; 
  background: white; z-index: 500; transform: translateX(100%); 
  transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1); box-shadow: -4px 0 20px rgba(0,0,0,0.08);
}
.timeline-container.visible { transform: translateX(0); }
.timeline-header { padding: 20px; border-bottom: 1px solid #f0f0f0; display: flex; justify-content: space-between; align-items: center; background: #fafafa; }
.timeline { padding: 20px; overflow-y: auto; height: calc(100% - 70px); }

.itinerary-summary-text { padding: 12px; background: #fff8f6; border-radius: 8px; margin-bottom: 20px; font-size: 13px; line-height: 1.6; color: #555; border-left: 3px solid var(--primary); }

.day-header { padding: 6px 12px; background: #333; color: white; border-radius: 6px; margin: 16px 0 10px; font-size: 11px; font-weight: bold; display: inline-block; }
.timeline-item { border-left: 2px solid #eee; padding-left: 16px; margin-bottom: 24px; cursor: pointer; position: relative; }
.timeline-item:hover { border-left-color: var(--primary); }
.timeline-time { font-weight: bold; color: var(--primary); font-size: 12px; margin-bottom: 4px; }
.timeline-title { font-size: 15px; font-weight: bold; color: #222; margin-bottom: 4px; }
.timeline-description { color: #666; font-size: 12px; line-height: 1.5; }

/* 地图气泡 */
.custom-map-popup { position: absolute; transform: translate(-50%, -100%); margin-top: -10px; pointer-events: none; }
.popup-bubble { 
  background: white; padding: 6px 10px; border-radius: 8px; box-shadow: var(--shadow);
  border-bottom: 3px solid var(--primary); font-size: 12px; pointer-events: auto; white-space: nowrap;
}

/* 加载动画 */
.spinner { position: fixed; inset: 0; background: rgba(255,255,255,0.9); backdrop-filter: blur(5px); z-index: 1000; display: flex; flex-direction: column; align-items: center; justify-content: center; }
.spinner::after { content: ''; width: 40px; height: 40px; border: 4px solid #f3f3f3; border-top: 4px solid var(--primary); border-radius: 50%; animation: spin 0.8s linear infinite; margin-bottom: 15px; }
@keyframes spin { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }
.loading-text { font-size: 14px; color: #444; font-weight: 500; }

.error { background: #fee2e2; color: #dc2626; padding: 10px 14px; border-radius: 10px; margin-top: 10px; font-size: 12px; box-shadow: var(--shadow); }

/* 弹窗 */
.modal-overlay { position: fixed; inset: 0; background: rgba(0,0,0,0.5); z-index: 2000; display: flex; align-items: center; justify-content: center; backdrop-filter: blur(2px); }
.modal-content { background: white; padding: 24px; border-radius: 16px; width: 90%; max-width: 400px; box-shadow: 0 20px 40px rgba(0,0,0,0.2); }
.modal-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 16px; }
.close-modal-btn { background: none; border: none; font-size: 24px; cursor: pointer; color: #999; }
.settings-hint { font-size: 12px; color: #777; margin-bottom: 16px; line-height: 1.5; }
.input-group { margin-bottom: 20px; }
.input-group label { display: block; font-size: 13px; font-weight: bold; margin-bottom: 6px; color: #444; }
.input-group input { width: 100%; padding: 10px 12px; border: 1px solid #ddd; border-radius: 8px; outline: none; transition: 0.2s; }
.input-group input:focus { border-color: var(--primary); box-shadow: 0 0 0 3px rgba(255, 87, 34, 0.1); }
.primary-btn { width: 100%; padding: 12px; background: var(--primary); color: white; border: none; border-radius: 10px; font-weight: bold; cursor: pointer; transition: 0.2s; }
.primary-btn:hover { background: var(--primary-hover); }

