      5. 使用中文回答，表达要极具感染力和专业度。`,
      // 同时开启搜索和函数调用
      tools: [{ googleSearch: {} }, { functionDeclarations: [locationTool] }],
    },
  });

  // 处理参考资料 (Google Search Grounding)
  const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
  if (groundingChunks && groundingChunks.length > 0) {
    displayGroundingSources(groundingChunks);
  }

  // 处理函数调用 (地图打点)
  const functionCalls = response.functionCalls || [];
  console.log(`Gemini 调用了 ${functionCalls.length} 个地图打点工具。`);

  for (const fc of functionCalls) {
    if (fc.name === 'location') {
      await setPin(fc.args);
    }
  }

  itinerarySummary = response.text || "";
  if (!itinerarySummary && dayPlanItinerary.length > 0) {
    itinerarySummary = "我已经根据实时检索的信息为您规划好了完美的行程。";
  }
}

async function handleDeepSeekRequest(model: string, input: string) {
  let apiKey = localStorage.getItem('deepseek_api_key') || 'sk-cadd6ff7f2ba4c60bf538f4eeb85ba11';
  const transformedParameters = transformSchemaToLowercase(locationTool.parameters);

  const tools = [
    {
      type: "function",
      function: {
        name: "location",
        description: "在地图上标注一个具体的行程地点。必须包含描述、经纬度和天气信息。",
        parameters: transformedParameters
      }
    }
  ];

  const response = await fetch('https://api.deepseek.com/chat/completions', {
    method: 'POST',
    headers: { 
      'Content-Type': 'application/json', 
      'Authorization': `Bearer ${apiKey}` 
    },
    body: JSON.stringify({
      model: model,
      messages: [
        { role: 'system', content: `你是一位顶级旅游博主。必须为行程中每一个具体的地点调用 'location' 工具，并提供天气信息。` },
        { role: 'user', content: input }
      ],
