import { GoogleGenAI } from '@google/genai';
import { MarkerClusterer } from "@googlemaps/markerclusterer";
import { locationTool } from './mcp-tools';

declare const google: any;

// Application state
let map: any;
let markers: any[] = [];
let popUps: any[] = [];
let bounds: any;
let markerCluster: any;
let activeCardIndex = 0;
let isPlannerMode = false;
let isUiHidden = false;
let dayPlanItinerary: any[] = [];
let itinerarySummary = "";
let polylines: any[] = []; // 改为数组，存储多天的连线

const getEl = <T extends HTMLElement>(id: string) => document.getElementById(id) as T;

/**
 * 颜色表：用于区分不同天数的路线
 */
const DAY_COLORS = ['#ff5722', '#2196f3', '#4caf50', '#9c27b0', '#ffeb3b', '#00bcd4', '#795548'];

/**
 * 转换 Schema 类型为小写以兼容 OpenAI/DeepSeek 接口
 */
function transformSchemaToLowercase(schema: any): any {
  if (!schema || typeof schema !== 'object') return schema;
  const newSchema = Array.isArray(schema) ? [...schema] : { ...schema };

  if (newSchema.type && typeof newSchema.type === 'string') {
    newSchema.type = newSchema.type.toLowerCase();
  }

  if (newSchema.properties) {
    for (const key in newSchema.properties) {
      newSchema.properties[key] = transformSchemaToLowercase(newSchema.properties[key]);
    }
  }

  if (newSchema.items) {
    newSchema.items = transformSchemaToLowercase(newSchema.items);
  }

  return newSchema;
}

async function initApp() {
  try {
    const { Map } = await google.maps.importLibrary('maps') as any;
    const { LatLngBounds } = await google.maps.importLibrary('core') as any;

    const mapEl = getEl('map');
    if (!mapEl) return;

    bounds = new LatLngBounds();
    map = new Map(mapEl, {
      center: { lat: 39.9042, lng: 116.4074 }, 
      zoom: 12,
      disableDefaultUI: true,
      gestureHandling: 'greedy', 
      mapId: 'DEMO_MAP_ID',
    });

    try {
      markerCluster = new MarkerClusterer({ map, markers: [] });
    } catch (e) {}

    setupPopupClass();
    bindEvents();

    const savedKey = localStorage.getItem('deepseek_api_key');
    if (savedKey) {
      (getEl('deepseek-key-input') as HTMLInputElement).value = savedKey;
    }

    // 尝试从 URL 加载行程
    await loadPlanFromUrl();

    getEl('spinner').classList.add('hidden');
  } catch (err) {
    console.error("Map Initialization Failed", err);
    setStatus("地图初始化失败，请检查网络", "error");
  }
}

function setupPopupClass() {
  (window as any).Popup = class Popup extends google.maps.OverlayView {
    position: any; containerDiv: HTMLDivElement;
    constructor(position: any, content: HTMLElement) {
      super();
      this.position = position;
      this.containerDiv = document.createElement('div');
      this.containerDiv.classList.add('custom-map-popup');
      const bubble = document.createElement('div');
      bubble.classList.add('popup-bubble');
      bubble.appendChild(content);
      this.containerDiv.appendChild(bubble);
      google.maps.OverlayView.preventMapHitsAndGesturesFrom(this.containerDiv);
    }
    onAdd() { (this as any).getPanes().floatPane.appendChild(this.containerDiv); }
    onRemove() { if (this.containerDiv.parentElement) this.containerDiv.parentElement.removeChild(this.containerDiv); }
    draw() {
      const divPosition = (this as any).getProjection().fromLatLngToDivPixel(this.position);
      if (divPosition) { this.containerDiv.style.left = divPosition.x + 'px'; this.containerDiv.style.top = divPosition.y + 'px'; }
    }
  };
}

/**
 * 分享功能：将当前行程编码并加载到 URL
 */
function encodeStateToUrl() {
  if (dayPlanItinerary.length === 0) return null;

  // 仅序列化核心数据字段，避开 marker 和 popup 循环引用
  const simplifiedItinerary = dayPlanItinerary.map(item => ({
    name: item.name,
    description: item.description,
    lat: item.lat,
    lng: item.lng,
    time: item.time,
    day: item.day,
    sequence: item.sequence,
    transit_hint: item.transit_hint,
    weather_icon: item.weather_icon,
    temperature: item.temperature
  }));

  const data = {
    summary: itinerarySummary,
    items: simplifiedItinerary,
    isPlanner: isPlannerMode
  };

  const jsonStr = JSON.stringify(data);
  // 使用 Base64 简单编码
  const base64 = btoa(encodeURIComponent(jsonStr));
  const url = new URL(window.location.href);
  url.searchParams.set('plan', base64);
  return url.toString();
}

async function loadPlanFromUrl() {
  const params = new URLSearchParams(window.location.search);
  const base64 = params.get('plan');
  if (!base64) return;

  try {
    const jsonStr = decodeURIComponent(atob(base64));
    const data = JSON.parse(jsonStr);

    itinerarySummary = data.summary || "";
    isPlannerMode = data.isPlanner || false;

    // 同步 UI 状态
    const toggle = getEl('planner-mode-toggle') as HTMLInputElement;
    if (toggle) {
      toggle.checked = isPlannerMode;
      getEl('mode-text').innerText = isPlannerMode ? "行程规划模式" : "景点发现模式";
      if (isPlannerMode) getEl('preference-toggle-group').classList.remove('hidden');
    }

    // 渲染节点
    for (const item of data.items) {
      await setPin(item);
    }

    if (dayPlanItinerary.length > 0) {
      dayPlanItinerary.sort((a, b) => (a.day - b.day) || (a.sequence - b.sequence));
      createCards();
      if (isPlannerMode) {
        drawRoute();
        createTimeline();
        showTimeline();
      }
      highlightCard(0, true);
    }
  } catch (e) {
    console.error("Failed to load plan from URL", e);
  }
}

async function handleRequest() {
  const userInput = (getEl('prompt-input') as HTMLTextAreaElement).value.trim();
  const selectedModel = (getEl('model-selector') as HTMLSelectElement).value;
  const routePref = (getEl('route-preference') as HTMLSelectElement).value;

  if (!userInput) return;

  restart();
  getEl('spinner').classList.remove('hidden');
  setStatus(`正在深度检索并规划您的完整行程...`, "loading");

  try {
    if (selectedModel.startsWith('deepseek')) {
      await handleDeepSeekRequest(selectedModel, userInput);
    } else {
      await handleGeminiRequest(selectedModel, userInput, routePref);
    }

    if (dayPlanItinerary.length === 0) {
      throw new Error("AI 未能识别地图节点。请尝试提供更明确的地点信息。");
    }

    dayPlanItinerary.sort((a, b) => (a.day - b.day) || (a.sequence - b.sequence));

    createCards();
    if (isPlannerMode) { 
      drawRoute(); 
      createTimeline(); 
      showTimeline(); 
    } else { 
      hideTimeline(); 
    }

    highlightCard(0, true);
    setStatus("", "hidden");
  } catch (e: any) {
    console.error("HandleRequest Error:", e);
    setStatus("⚠️ " + (e.message || "请求失败"), "error");
  } finally {
    getEl('spinner').classList.add('hidden');
  }
}

async function handleGeminiRequest(model: string, input: string, preference: string) {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const prefText = preference === 'budget' ? "注重经济性价比" : "注重时间宽松和深度体验";

  const response = await ai.models.generateContent({
    model: model,
    contents: [{
      role: 'user',
      parts: [{ text: `我需要一个完整的行程规划，目的地需求：${input}。我的偏好：${prefText}。如果是多天行程，请务必规划完整，不要只返回第一天。` }]
    }],
    config: {
      systemInstruction: `你是一位世界顶级的旅游行程规划专家，具备实时联网搜索能力。

      【严格执行规范】:
      1. **实时搜索 (googleSearch)**: 必须先搜索目的地的实时天气、交通（高铁/航班）以及最新的拍照打卡建议。
      2. **全打点要求**: 严禁只返回第一天行程！如果用户需求涉及多天，你必须为【每一天】的【每一个】景点、餐厅和酒店分别调用 'location' 工具。
      3. **函数调用优先级**: 请先执行所有的 'location' 工具调用，确保地图标记覆盖全部行程天数，最后再输出 Markdown 文本总结。
      4. **打点详情**: 
         - weather_icon: 必须使用 Emoji (如 ☀️, 🌧️)。
         - temperature: 基于搜索结果给出气温。
         - description: 包含该地点的“避坑指南”和“独家拍照位”。
      5. **Markdown 攻略**: 文本部分应不少于 800 字，包含每日穿搭建议、交通转场攻略和实时信息。
      6. 使用中文，语言生动形象，充满博主感。`,
      tools: [{ googleSearch: {} }, { functionDeclarations: [locationTool] }],
    },
  });

  // 处理 Grounding 信息
  const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
  if (groundingChunks) {
    displayGroundingSources(groundingChunks);
  }

  // 处理函数调用
  const functionCalls = response.functionCalls || [];
  console.log(`Gemini 返回了 ${functionCalls.length} 个行程节点。`);

  for (const fc of functionCalls) {
    if (fc.name === 'location') {
      await setPin(fc.args);
    }
  }

  itinerarySummary = response.text || "";
  if (!itinerarySummary && dayPlanItinerary.length > 0) {
    itinerarySummary = "根据您的需求和最新的实时搜索结果，我已经为您规划好了完整的行程。请在地图和侧边栏查看每日打卡点、交通及拍照建议。";
  }
}

async function handleDeepSeekRequest(model: string, input: string) {
  let apiKey = localStorage.getItem('deepseek_api_key') || 'sk-cadd6ff7f2ba4c60bf538f4eeb85ba11';
  const transformedParameters = transformSchemaToLowercase(locationTool.parameters);

  const tools = [
    {
      type: "function",
      function: {
        name: "location",
        description: "在地图上标注一个具体的行程地点。必须包含多天完整信息。",
        parameters: transformedParameters
      }
    }
  ];

  const response = await fetch('https://api.deepseek.com/chat/completions', {
    method: 'POST',
    headers: { 
      'Content-Type': 'application/json', 
      'Authorization': `Bearer ${apiKey}` 
    },
    body: JSON.stringify({
      model: model,
      messages: [
        { role: 'system', content: `你是一位顶级旅游博主。必须为行程中每一天的每一个具体地点调用 'location' 工具。严禁只返回第一天！` },
        { role: 'user', content: input }
      ],
      tools: tools,
      tool_choice: "auto"
    })
  });

  if (!response.ok) throw new Error(`DeepSeek 请求失败: ${response.statusText}`);
  const data = await response.json();
  const message = data.choices[0].message;
  itinerarySummary = message.content || "";

  if (message.tool_calls) {
    for (const tc of message.tool_calls) {
      if (tc.function.name === 'location') {
        await setPin(JSON.parse(tc.function.arguments));
      }
    }
  }
}

function displayGroundingSources(chunks: any[]) {
  const sourceList = getEl('source-list');
  const groundingContainer = getEl('grounding-sources');
  sourceList.innerHTML = '';
  const uniqueSources = new Set();
  chunks.forEach(chunk => {
    if (chunk.web && chunk.web.uri) {
      if (!uniqueSources.has(chunk.web.uri)) {
        uniqueSources.add(chunk.web.uri);
        const li = document.createElement('li');
        li.innerHTML = `<a href="${chunk.web.uri}" target="_blank"><i class="fas fa-link"></i> ${chunk.web.title || chunk.web.uri}</a>`;
        sourceList.appendChild(li);
      }
    }
  });
  if (uniqueSources.size > 0) groundingContainer.classList.remove('hidden');
}

async function setPin(args: any) {
  const { name, lat, lng, weather_icon, temperature, day } = args;
  const pos = { lat: parseFloat(lat), lng: parseFloat(lng) };
  if (isNaN(pos.lat) || isNaN(pos.lng)) return;

  bounds.extend(pos);

  // 标记颜色也可以根据天数区分
  const color = DAY_COLORS[(day - 1) % DAY_COLORS.length];

  const marker = new google.maps.Marker({
    position: pos,
    title: name,
    map: map,
    icon: {
      path: google.maps.SymbolPath.CIRCLE,
      fillColor: color, 
      fillOpacity: 1, 
      strokeWeight: 2, 
      strokeColor: '#fff', 
      scale: 8
    }
  });

  const content = document.createElement('div');
  content.innerHTML = `
    <div style="display:flex; align-items:center; gap:4px;">
      <span style="font-size:14px;">${weather_icon || '📍'}</span>
      <strong style="font-size:11px;">${name}</strong>
    </div>
  `;
  const popup = new (window as any).Popup(new google.maps.LatLng(pos), content);

  const item = { ...args, position: new google.maps.LatLng(pos), popup, marker };
  dayPlanItinerary.push(item);
  popUps.push(item);
  map.fitBounds(bounds);
}

/**
 * 拖拽功能实现核心逻辑
 */
let draggedIndex: number | null = null;

function createTimeline() {
  const t = getEl('timeline');
  t.innerHTML = `<div class="itinerary-summary-text">${itinerarySummary.replace(/\n/g, '<br>')}</div>`;

  let currentDay = -1;
  dayPlanItinerary.forEach((item, index) => {
    if (item.day !== currentDay) {
      currentDay = item.day;
      const h = document.createElement('div');
      h.className = 'day-header';
      const color = DAY_COLORS[(currentDay - 1) % DAY_COLORS.length];
      h.style.background = color;
      h.innerHTML = `第 ${currentDay} 天`;
      t.appendChild(h);
    }

    const div = document.createElement('div');
    div.className = `timeline-item draggable-item`;
    div.setAttribute('draggable', 'true');
    div.dataset.index = index.toString();
    div.dataset.day = item.day.toString();

    div.innerHTML = `
      <div class="drag-handle"><i class="fas fa-grip-vertical"></i></div>
      <div class="timeline-time" style="display:flex; justify-content:space-between; align-items:center;">
        <span>${item.time}</span>
        <span class="weather-badge" style="background:#fff2ef; color:#ff5722; padding:2px 8px; border-radius:12px; font-size:11px; font-weight:bold;">
          ${item.weather_icon || '☀️'} ${item.temperature || ''}
        </span>
      </div>
      <div class="timeline-content">
        <div class="timeline-title">${item.name}</div>
        <div class="timeline-description">${item.description}</div>
        ${item.transit_hint ? `<div class="transit-info"><i class="fas fa-bus"></i> ${item.transit_hint}</div>` : ''}
      </div>`;

    // 拖拽事件监听
    div.addEventListener('dragstart', (e: DragEvent) => {
      draggedIndex = index;
      div.classList.add('dragging');
      if (e.dataTransfer) {
        e.dataTransfer.effectAllowed = 'move';
        e.dataTransfer.setData('text/plain', index.toString());
      }
    });

    div.addEventListener('dragend', () => {
      div.classList.remove('dragging');
      draggedIndex = null;
      document.querySelectorAll('.timeline-item').forEach(el => el.classList.remove('drag-over'));
    });

    div.addEventListener('dragover', (e: DragEvent) => {
      e.preventDefault();
      if (e.dataTransfer) e.dataTransfer.dropEffect = 'move';
      div.classList.add('drag-over');
    });

    div.addEventListener('dragleave', () => {
      div.classList.remove('drag-over');
    });

    div.addEventListener('drop', (e: DragEvent) => {
      e.preventDefault();
      const targetIndex = parseInt(div.dataset.index || "0");
      if (draggedIndex !== null && draggedIndex !== targetIndex) {
        reorderItinerary(draggedIndex, targetIndex);
      }
      div.classList.remove('drag-over');
    });

    div.onclick = () => highlightCard(index, true);
    t.appendChild(div);
  });
}

function reorderItinerary(from: number, to: number) {
  const item = dayPlanItinerary.splice(from, 1)[0];
  dayPlanItinerary.splice(to, 0, item);

  createTimeline();
  createCards();
  drawRoute();
  highlightCard(to, true);
}

function createCards() {
  const container = getEl('card-container');
  container.innerHTML = '';
  getEl('card-carousel').classList.remove('hidden');
  dayPlanItinerary.forEach((loc, index) => {
    const card = document.createElement('div');
    card.className = `location-card`;
    card.innerHTML = `
      <div class="card-day-mini" style="background: ${DAY_COLORS[(loc.day - 1) % DAY_COLORS.length]}">D${loc.day}</div>
      <div class="card-info-mini">
        <div class="card-title-mini">${loc.weather_icon || '📍'} ${loc.name}</div>
        <div class="card-time-mini">${loc.time} · ${loc.temperature || ''}</div>
      </div>
    `;
    card.onclick = () => highlightCard(index, true);
    container.appendChild(card);
  });
}

function highlightCard(index: number, scroll: boolean = false) {
  popUps.forEach(p => p.popup.setMap(null));
  activeCardIndex = Math.max(0, Math.min(index, dayPlanItinerary.length - 1));
  const item = dayPlanItinerary[activeCardIndex];
  if (item) {
    item.popup.setMap(map);
    map.panTo(item.position);
    if (scroll) {
      const cards = document.querySelectorAll('.location-card');
      cards[activeCardIndex]?.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'center' });
      cards.forEach(c => c.classList.remove('active'));
      cards[activeCardIndex]?.classList.add('active');
    }
  }
}

/**
 * 按天绘制路径连线
 */
function drawRoute() {
  // 1. 清除旧线条
  polylines.forEach(p => p.setMap(null));
  polylines = [];

  // 2. 按天分组坐标
  const routesByDay: { [key: number]: any[] } = {};
  dayPlanItinerary.forEach(item => {
    if (!routesByDay[item.day]) routesByDay[item.day] = [];
    routesByDay[item.day].push(item.position);
  });

  // 3. 为每一天绘制独立颜色的连线
  Object.keys(routesByDay).forEach(dayStr => {
    const day = parseInt(dayStr);
    const path = routesByDay[day];

    if (path.length < 2) return;

    const color = DAY_COLORS[(day - 1) % DAY_COLORS.length];

    const poly = new google.maps.Polyline({
      path: path,
      strokeColor: color,
      strokeOpacity: 0.8,
      strokeWeight: 4,
      map: map,
      icons: [{
        icon: { path: google.maps.SymbolPath.FORWARD_CLOSED_ARROW },
        offset: '50%',
        repeat: '100px'
      }]
    });

    polylines.push(poly);
  });
}

function restart() {
  popUps.forEach(p => p.popup.setMap(null));
  polylines.forEach(p => p.setMap(null));
  polylines = [];

  dayPlanItinerary.forEach(item => {
    if (item.marker) item.marker.setMap(null);
  });

  dayPlanItinerary = [];
  getEl('card-container').innerHTML = '';
  getEl('card-carousel').classList.add('hidden');
  getEl('timeline-container').classList.remove('visible');
  getEl('grounding-sources').classList.add('hidden');
  getEl('source-list').innerHTML = '';
  bounds = new google.maps.LatLngBounds();

  // 清除 URL 中的 plan 参数
  const url = new URL(window.location.href);
  url.searchParams.delete('plan');
  window.history.replaceState({}, '', url.toString());

  setStatus("", "hidden");
}

function setStatus(msg: string, type: string) {
  const err = getEl('error-message');
  if (type === 'hidden') { err.classList.add('hidden'); return; }
  err.innerText = msg; err.className = `error ${type}`; err.classList.remove('hidden');
}

function bindEvents() {
  getEl('planner-mode-toggle').onchange = (e) => {
    isPlannerMode = (e.target as HTMLInputElement).checked;
    getEl('mode-text').innerText = isPlannerMode ? "行程规划模式" : "景点发现模式";
    const prefGroup = getEl('preference-toggle-group');
    if (isPlannerMode) prefGroup.classList.remove('hidden');
    else prefGroup.classList.add('hidden');
    restart();
  };
  getEl('generate').onclick = handleRequest;
  getEl('reset').onclick = restart;
  getEl('export-btn').onclick = () => {
    let md = `# 行程指南\n\n${itinerarySummary}\n\n`;
    dayPlanItinerary.forEach(i => md += `## 第 ${i.day} 天: ${i.name}\n- 时间: ${i.time}\n- 天气: ${i.weather_icon} ${i.temperature}\n- 详情: ${i.description}\n\n`);
    const blob = new Blob([md], { type: 'text/markdown' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = `行程指南.md`;
    a.click();
  };

  // 分享行程
  getEl('share-btn').onclick = () => {
    const url = encodeStateToUrl();
    if (url) {
      navigator.clipboard.writeText(url).then(() => {
        alert("行程链接已复制到剪贴板！您可以将其发给好友。");
      }).catch(err => {
        console.error('Could not copy text: ', err);
        alert(`行程链接生成失败，但您可以手动复制此地址: ${url}`);
      });
    } else {
      alert("请先生成或规划一段行程。");
    }
  };

  getEl('close-timeline').onclick = hideTimeline;
  getEl('reopen-timeline').onclick = showTimeline;
  getEl('toggle-search-ui').onclick = () => {
    isUiHidden = !isUiHidden;
    getEl('search-container').classList.toggle('ui-hidden', isUiHidden);
    getEl('toggle-search-ui').innerHTML = isUiHidden ? '<i class="fas fa-eye"></i>' : '<i class="fas fa-eye-slash"></i>';
  };
  getEl('open-settings').onclick = () => getEl('settings-modal').classList.remove('hidden');
  getEl('close-settings').onclick = () => getEl('settings-modal').classList.add('hidden');
  getEl('save-settings').onclick = () => {
    const val = (getEl('deepseek-key-input') as HTMLInputElement).value.trim();
    localStorage.setItem('deepseek_api_key', val);
    getEl('settings-modal').classList.add('hidden');
  };
}

function hideTimeline() { 
  getEl('timeline-container').classList.remove('visible'); 
  document.body.classList.remove('timeline-open');
  if (dayPlanItinerary.length > 0) getEl('reopen-timeline').classList.remove('hidden'); 
}

function showTimeline() { 
  getEl('timeline-container').classList.add('visible'); 
  document.body.classList.add('timeline-open');
  getEl('reopen-timeline').classList.add('hidden'); 
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initApp);
} else {
  initApp();
}

@import url(https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css);

:root {
  --primary: #ff5722;
  --primary-hover: #f4511e;
  --glass: rgba(255, 255, 255, 0.95);
  --shadow: 0 4px 12px rgba(0,0,0,0.1);
  --radius: 12px;
}

* { box-sizing: border-box; padding: 0; margin: 0; font-family: 'PingFang SC', system-ui, sans-serif; }

html, body { height: 100%; width: 100%; overflow: hidden; background: #fff; }

.hidden { display: none !important; }

/* 地图全屏 */
.map-container { position: absolute; inset: 0; z-index: 1; }
#map { height: 100%; width: 100%; }

/* 搜索UI */
.search-container { 
  position: absolute; top: 16px; left: 50%; transform: translateX(-50%); 
  z-index: 100; width: 90%; max-width: 600px; 
  transition: all 0.3s ease;
}
.search-container.ui-hidden { transform: translate(-50%, -200px); opacity: 0; pointer-events: none; }

.search-header-group { display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px; gap: 8px; }

.header-left-controls { display: flex; align-items: center; gap: 10px; }

.mode-toggle { 
  background: var(--glass); padding: 4px 10px; border-radius: 20px; 
  display: flex; align-items: center; gap: 8px; box-shadow: var(--shadow);
}
.mode-label { font-size: 11px; font-weight: bold; color: #555; }

.switch { position: relative; width: 32px; height: 18px; }
.switch input { opacity: 0; width: 0; height: 0; }
.slider { position: absolute; inset: 0; background-color: #ddd; transition: .3s; border-radius: 20px; cursor: pointer; }
.slider:before { position: absolute; content: ""; height: 14px; width: 14px; left: 2px; bottom: 2px; background-color: white; transition: .3s; border-radius: 50%; }
input:checked + .slider { background-color: var(--primary); }
input:checked + .slider:before { transform: translateX(14px); }

.model-select {
  padding: 4px 10px; border-radius: 20px; border: none; background: var(--glass); 
  font-size: 11px; font-weight: bold; box-shadow: var(--shadow); cursor: pointer; outline: none;
}

.icon-btn-small { background: var(--glass); border: none; width: 28px; height: 28px; border-radius: 50%; box-shadow: var(--shadow); cursor: pointer; display: flex; align-items: center; justify-content: center; color: #555; }

.search-bar-stack { background: var(--glass); border-radius: 14px; padding: 4px 10px; box-shadow: var(--shadow); }
.search-bar { display: flex; align-items: center; gap: 8px; }
#prompt-input { flex: 1; border: none; outline: none; font-size: 14px; min-height: 40px; background: transparent; resize: none; padding: 8px 0; }
.search-button { background: var(--primary); color: white; border: none; width: 34px; height: 34px; border-radius: 50%; cursor: pointer; transition: 0.2s; }
.search-button:hover { background: var(--primary-hover); transform: scale(1.05); }

/* 极简卡片轮播 */
.card-carousel { 
  position: absolute; bottom: 16px; left: 0; right: 0; 
  z-index: 50; pointer-events: none; 
  transition: right 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

/* 解决卡片被侧边栏遮挡的问题 */
body.timeline-open .card-carousel {
  right: 360px;
}

.card-container { display: flex; overflow-x: auto; padding: 8px 16px; gap: 8px; scrollbar-width: none; pointer-events: auto; }
.card-container::-webkit-scrollbar { display: none; }

.location-card { 
  flex: 0 0 auto; min-width: 140px; background: white; border-radius: 30px; 
  padding: 6px 14px; box-shadow: 0 2px 8px rgba(0,0,0,0.1); 
  cursor: pointer; border: 1px solid #f0f0f0; display: flex; gap: 8px;
  align-items: center; transition: 0.2s; white-space: nowrap;
}
.location-card.active { border-color: var(--primary); background: #fff8f6; transform: scale(1.05); box-shadow: 0 0 15px rgba(255, 87, 34, 0.2); }

.card-day-mini { background: var(--primary); color: white; font-size: 10px; font-weight: 900; padding: 2px 6px; border-radius: 10px; }
.card-info-mini { overflow: hidden; }
.card-title-mini { font-weight: bold; font-size: 13px; color: #333; }
.card-time-mini { font-size: 11px; color: #999; }

/* 浮动按钮 */
.floating-control-btn { 
  position: absolute; z-index: 150; width: 42px; height: 42px; border-radius: 50%; 
  background: var(--glass); border: none; box-shadow: var(--shadow); cursor: pointer; 
  display: flex; align-items: center; justify-content: center; font-size: 18px; color: #333; transition: 0.2s;
}
.floating-control-btn:hover { background: white; transform: translateY(-2px); }
.toggle-ui-btn { top: 16px; left: 16px; }
.reopen-timeline-btn { top: 16px; right: 16px; background: var(--primary); color: white; }
.reset-button { bottom: 65px; right: 16px; }

/* 时间轴侧边栏 */
.timeline-container { 
  position: fixed; right: 0; top: 0; width: 360px; height: 100%; 
  background: white; z-index: 500; transform: translateX(100%); 
  transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1); box-shadow: -4px 0 20px rgba(0,0,0,0.08);
}
.timeline-container.visible { transform: translateX(0); }
.timeline-header { padding: 20px; border-bottom: 1px solid #f0f0f0; display: flex; justify-content: space-between; align-items: center; background: #fafafa; }
.timeline { padding: 20px; overflow-y: auto; height: calc(100% - 70px); }

.itinerary-summary-text { padding: 16px; background: #fffcfb; border-radius: 12px; margin-bottom: 24px; font-size: 14px; line-height: 1.8; color: #444; border: 1px solid #ffebe0; box-shadow: inset 0 2px 4px rgba(255, 87, 34, 0.03); white-space: pre-wrap; }

.day-header { padding: 6px 14px; background: #333; color: white; border-radius: 20px; margin: 24px 0 16px; font-size: 11px; font-weight: bold; display: inline-block; letter-spacing: 1px; }

/* 拖拽排序样式增强 */
.timeline-item { 
  border-left: 2px solid #f0f0f0; padding-left: 28px; margin-bottom: 30px; 
  cursor: pointer; position: relative; transition: all 0.2s ease;
}
.timeline-item:hover { border-left-color: var(--primary); background: rgba(255, 87, 34, 0.02); }

.drag-handle {
  position: absolute; left: 4px; top: 50%; transform: translateY(-50%);
  color: #ccc; cursor: grab; padding: 10px 4px; font-size: 14px;
}
.drag-handle:active { cursor: grabbing; }

.timeline-item.dragging {
  opacity: 0.4;
  border: 1px dashed var(--primary);
  background: #f9f9f9;
}

.timeline-item.drag-over {
  border-left: 4px solid var(--primary);
  padding-left: 26px;
  background: rgba(255, 87, 34, 0.05);
}

.timeline-time { font-weight: bold; color: var(--primary); font-size: 13px; margin-bottom: 6px; }
.timeline-title { font-size: 16px; font-weight: bold; color: #111; margin-bottom: 6px; }
.timeline-description { color: #666; font-size: 13px; line-height: 1.6; }
.transit-info { margin-top: 10px; font-size: 12px; color: #ff5722; background: #fff5f2; padding: 6px 10px; border-radius: 6px; display: inline-flex; align-items: center; gap: 6px; }

/* 溯源资料 */
.grounding-sources { padding: 20px; border-top: 1px solid #f0f0f0; background: #fdfdfd; }
.grounding-sources h4 { font-size: 13px; margin-bottom: 12px; color: #999; text-transform: uppercase; letter-spacing: 0.5px; }
.grounding-sources ul { list-style: none; }
.grounding-sources li { margin-bottom: 8px; font-size: 12px; }
.grounding-sources a { color: #0066cc; text-decoration: none; display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.grounding-sources a:hover { text-decoration: underline; }

/* 地图气泡 */
.custom-map-popup { position: absolute; transform: translate(-50%, -100%); margin-top: -10px; pointer-events: none; }
.popup-bubble { 
  background: white; padding: 6px 12px; border-radius: 8px; box-shadow: var(--shadow);
  border-bottom: 3px solid var(--primary); font-size: 12px; pointer-events: auto; white-space: nowrap; font-weight: bold;
}

/* 加载动画 */
.spinner { position: fixed; inset: 0; background: rgba(255,255,255,0.95); backdrop-filter: blur(10px); z-index: 1000; display: flex; flex-direction: column; align-items: center; justify-content: center; }
.spinner::after { content: ''; width: 48px; height: 48px; border: 4px solid #f3f3f3; border-top: 4px solid var(--primary); border-radius: 50%; animation: spin 1s cubic-bezier(0.4, 0, 0.2, 1) infinite; margin-bottom: 20px; }
@keyframes spin { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }
.loading-text { font-size: 15px; color: #333; font-weight: 500; }

.error { background: #fee2e2; color: #dc2626; padding: 12px 16px; border-radius: 12px; margin-top: 12px; font-size: 13px; box-shadow: var(--shadow); border-left: 4px solid #dc2626; }

