import { GoogleGenAI } from '@google/genai';
import { MarkerClusterer } from "@googlemaps/markerclusterer";
import { locationTool } from './mcp-tools';

declare const google: any;

// Application state
let map: any;
let popUps: any[] = [];
let bounds: any;
let markerCluster: any;
let activeCardIndex = 0;
let isPlannerMode = false;
let isUiHidden = false;
let dayPlanItinerary: any[] = [];
let itinerarySummary = "";
let polylines: any[] = []; 

const getEl = <T extends HTMLElement>(id: string) => document.getElementById(id) as T;
const DAY_COLORS = ['#ff5722', '#2196f3', '#4caf50', '#9c27b0', '#ffeb3b', '#00bcd4', '#795548'];

function transformSchemaToLowercase(schema: any): any {
  if (!schema || typeof schema !== 'object') return schema;
  const newSchema = Array.isArray(schema) ? [...schema] : { ...schema };
  if (newSchema.type && typeof newSchema.type === 'string') newSchema.type = newSchema.type.toLowerCase();
  if (newSchema.properties) {
    for (const key in newSchema.properties) newSchema.properties[key] = transformSchemaToLowercase(newSchema.properties[key]);
  }
  if (newSchema.items) newSchema.items = transformSchemaToLowercase(newSchema.items);
  return newSchema;
}

async function initApp() {
  try {
    const { Map } = await google.maps.importLibrary('maps') as any;
    const { LatLngBounds } = await google.maps.importLibrary('core') as any;
    bounds = new LatLngBounds();
    map = new Map(getEl('map'), {
      center: { lat: 39.9042, lng: 116.4074 }, 
      zoom: 12,
      disableDefaultUI: true,
      gestureHandling: 'greedy', 
      mapId: 'DEMO_MAP_ID',
    });
    try { markerCluster = new MarkerClusterer({ map, markers: [] }); } catch (e) {}
    setupPopupClass();
    bindEvents();
    if (localStorage.getItem('deepseek_api_key')) {
      (getEl('deepseek-key-input') as HTMLInputElement).value = localStorage.getItem('deepseek_api_key')!;
    }
    await loadPlanFromUrl();
    getEl('spinner').classList.add('hidden');
  } catch (err) {
    console.error("Map Initialization Failed", err);
    setStatus("地图初始化失败，请检查网络", "error");
  }
}

function setupPopupClass() {
  (window as any).Popup = class Popup extends google.maps.OverlayView {
    position: any; containerDiv: HTMLDivElement;
    constructor(position: any, content: HTMLElement) {
      super();
      this.position = position;
      this.containerDiv = document.createElement('div');
      this.containerDiv.classList.add('custom-map-popup');
      const bubble = document.createElement('div');
      bubble.classList.add('popup-bubble');
      bubble.appendChild(content);
      this.containerDiv.appendChild(bubble);
      google.maps.OverlayView.preventMapHitsAndGesturesFrom(this.containerDiv);
    }
    onAdd() { (this as any).getPanes().floatPane.appendChild(this.containerDiv); }
    onRemove() { if (this.containerDiv.parentElement) this.containerDiv.parentElement.removeChild(this.containerDiv); }
    draw() {
      const divPosition = (this as any).getProjection().fromLatLngToDivPixel(this.position);
      if (divPosition) { this.containerDiv.style.left = divPosition.x + 'px'; this.containerDiv.style.top = divPosition.y + 'px'; }
    }
  };
}

function encodeStateToUrl() {
  if (dayPlanItinerary.length === 0) return null;
  const data = { 
    summary: itinerarySummary, 
    items: dayPlanItinerary.map(i => ({ name: i.name, description: i.description, lat: i.lat, lng: i.lng, time: i.time, day: i.day, sequence: i.sequence, weather_icon: i.weather_icon, temperature: i.temperature })),
    isPlanner: isPlannerMode 
  };
  return `${window.location.origin}${window.location.pathname}?plan=${btoa(encodeURIComponent(JSON.stringify(data)))}`;
}

async function loadPlanFromUrl() {
  const params = new URLSearchParams(window.location.search);
  const planData = params.get('plan');
  if (!planData) return;
  try {
    const data = JSON.parse(decodeURIComponent(atob(planData)));
    itinerarySummary = data.summary;
    isPlannerMode = data.isPlanner;
    getEl<HTMLInputElement>('planner-mode-toggle').checked = isPlannerMode;
    getEl('mode-text').innerText = isPlannerMode ? "行程规划模式" : "景点发现模式";
    for (const item of data.items) await setPin(item);
    if (dayPlanItinerary.length > 0) {
      dayPlanItinerary.sort((a, b) => (a.day - b.day) || (a.sequence - b.sequence));
      createCards();
      if (isPlannerMode) { drawRoute(); createTimeline(); showTimeline(); }
      highlightCard(0, true);
    }
  } catch (e) { console.error("Plan parsing error", e); }
}

async function handleRequest() {
  const userInput = getEl<HTMLTextAreaElement>('prompt-input').value.trim();
  const selectedModel = getEl<HTMLSelectElement>('model-selector').value;
  if (!userInput) return;
  restart();
  getEl('spinner').classList.remove('hidden');
  setStatus(`AI 专家正在深度规划您的专属行程...`, "loading");
  try {
    if (selectedModel.startsWith('deepseek')) await handleDeepSeekRequest(selectedModel, userInput);
    else await handleGeminiRequest(selectedModel, userInput);
    if (dayPlanItinerary.length === 0) throw new Error("未能识别有效地点，请尝试更详细的描述。");
    dayPlanItinerary.sort((a, b) => (a.day - b.day) || (a.sequence - b.sequence));
    createCards();
    if (isPlannerMode) { drawRoute(); createTimeline(); showTimeline(); } else { hideTimeline(); }
    highlightCard(0, true);
    setStatus("", "hidden");
  } catch (e: any) { setStatus("⚠️ " + (e.message || "服务繁忙"), "error"); }
  finally { getEl('spinner').classList.add('hidden'); }
}

async function handleGeminiRequest(model: string, input: string) {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const response = await ai.models.generateContent({
    model,
    contents: `目的地与偏好：${input}。请为多天行程的【每一天】规划详细节点。`,
    config: {
      systemInstruction: `你是顶级旅游规划专家。必须为多天行程中的【每天】调用 'location' 工具打点。禁止只规划第一天。输出生动的 Markdown 攻略总结。`,
      tools: [{ functionDeclarations: [locationTool] }],
    },
  });
  for (const fc of (response.functionCalls || [])) if (fc.name === 'location') await setPin(fc.args);
  itinerarySummary = response.text || "行程规划完成。";
}

async function handleDeepSeekRequest(model: string, input: string) {
  const apiKey = localStorage.getItem('deepseek_api_key') || '';
  const response = await fetch('https://api.deepseek.com/chat/completions', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiKey}` },
    body: JSON.stringify({
      model,
      messages: [{ role: 'system', content: '顶级旅游规划师。务必为多天行程每一天打点。' }, { role: 'user', content: input }],
      tools: [{ type: "function", function: { name: "location", parameters: transformSchemaToLowercase(locationTool.parameters) } }],
      tool_choice: "auto"
    })
  });
  const data = await response.json();
  const message = data.choices[0].message;
  itinerarySummary = message.content || "";
  if (message.tool_calls) for (const tc of message.tool_calls) await setPin(JSON.parse(tc.function.arguments));
}

async function setPin(args: any) {
  const { name, lat, lng, weather_icon, temperature, day } = args;
  const pos = { lat: parseFloat(lat), lng: parseFloat(lng) };
  if (isNaN(pos.lat)) return;
  bounds.extend(pos);
  const color = DAY_COLORS[(day - 1) % DAY_COLORS.length];
  const marker = new google.maps.Marker({ position: pos, title: name, map: map, icon: { path: google.maps.SymbolPath.CIRCLE, fillColor: color, fillOpacity: 1, strokeWeight: 2, strokeColor: '#fff', scale: 8 } });
  const content = document.createElement('div');
  content.innerHTML = `<strong>${name}</strong>`;
  const popup = new (window as any).Popup(new google.maps.LatLng(pos), content);
  dayPlanItinerary.push({ ...args, position: new google.maps.LatLng(pos), popup, marker });
  map.fitBounds(bounds);
}

/**
 * 艺术海报生成系统 - 深度优化
 */
async function generatePoster() {
  const btn = getEl('generate-poster-btn') as HTMLButtonElement;
  const canvas = getEl('poster-canvas') as HTMLCanvasElement;
  const ctx = canvas.getContext('2d')!;
  btn.disabled = true; btn.innerText = "艺术创作中...";

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const destination = dayPlanItinerary[0]?.name || "目的地";

    // 1. 获取 AI 创作背景
    const imgRes = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: `A professional travel magazine style high-resolution cinematic background for ${destination}, warm light, soft focus, no text.` }] },
      config: { imageConfig: { aspectRatio: "9:16" } }
    });

    let base64 = "";
    for (const p of imgRes.candidates[0].content.parts) if (p.inlineData) base64 = p.inlineData.data;
    if (!base64) throw new Error("Bg failed");

    const img = new Image();
    img.src = `data:image/png;base64,${base64}`;
    img.onload = () => {
      // 2. 动态高度计算：基础高度 + (天数 * 行高)
      const dayGroups = dayPlanItinerary.reduce((acc: any, cur) => {
        if (!acc[cur.day]) acc[cur.day] = [];
        acc[cur.day].push(cur.name);
        return acc;
      }, {});
      const dayCount = Object.keys(dayGroups).length;
      const calculatedHeight = 800 + (dayCount * 120) + (dayPlanItinerary.length * 40);
      canvas.height = Math.max(1200, calculatedHeight);

      // 3. 绘制层叠背景
      ctx.drawImage(img, 0, 0, canvas.width, 600); // 顶部封面
      const bgGrad = ctx.createLinearGradient(0, 500, 0, canvas.height);
      bgGrad.addColorStop(0, '#ffffff00');
      bgGrad.addColorStop(0.1, '#ffffff');
      bgGrad.addColorStop(1, '#ffffff');
      ctx.fillStyle = bgGrad;
      ctx.fillRect(0, 400, canvas.width, canvas.height - 400);

      // 4. 标题艺术化
      ctx.shadowColor = 'rgba(0,0,0,0.3)';
      ctx.shadowBlur = 20;
      ctx.fillStyle = "white";
      ctx.textAlign = "center";
      ctx.font = "bold 80px sans-serif";
      ctx.fillText(destination, canvas.width/2, 280);
      ctx.shadowBlur = 0;

      ctx.font = "30px sans-serif";
      ctx.fillText("V O Y A G E  ·  A I  G U I D E", canvas.width/2, 340);

      // 5. 每日行程渲染
      let currentY = 550;
      Object.keys(dayGroups).forEach(dKey => {
        const dNum = parseInt(dKey);
        ctx.fillStyle = DAY_COLORS[(dNum-1) % DAY_COLORS.length];
        ctx.beginPath();
        ctx.roundRect(60, currentY, 140, 50, 12);
        ctx.fill();

        ctx.fillStyle = "white";
        ctx.textAlign = "center";
        ctx.font = "bold 26px sans-serif";
        ctx.fillText(`Day ${dNum}`, 130, currentY + 35);

        currentY += 70;
        ctx.textAlign = "left";
        ctx.fillStyle = "#1a1a1a";
        ctx.font = "bold 32px sans-serif";

        dayGroups[dKey].forEach((name: string) => {
          ctx.fillStyle = "#ff5722";
          ctx.fillText("•", 70, currentY);
          ctx.fillStyle = "#333";
          ctx.fillText(name, 100, currentY);
          currentY += 50;
        });
        currentY += 40;
      });

      // 6. 页脚
      ctx.fillStyle = "#f5f5f5";
      ctx.fillRect(0, canvas.height - 100, canvas.width, 100);
      ctx.fillStyle = "#999";
      ctx.textAlign = "center";
      ctx.font = "20px sans-serif";
      ctx.fillText("Generated by Voyage AI - 开启您的灵感之旅", canvas.width/2, canvas.height - 45);

      getEl('poster-placeholder').classList.add('hidden');
      getEl('poster-result').classList.remove('hidden');
      btn.disabled = false; btn.innerText = "重新生成";
    };
  } catch (e) { alert("海报生成失败"); btn.disabled = false; }
}

function wrapText(ctx: any, text: string, maxWidth: number) {
  const chars = text.split("");
  let line = "";
  const lines = [];
  for (let n = 0; n < chars.length; n++) {
    const test = line + chars[n];
    if (ctx.measureText(test).width > maxWidth) { lines.push(line); line = chars[n]; } else { line = test; }
  }
  lines.push(line);
  return lines;
}

function highlightCard(index: number, scroll: boolean = false) {
  activeCardIndex = index;
  const item = dayPlanItinerary[index];
  popUps.forEach(p => p.popup.setMap(null));
  if (item) {
    item.popup.setMap(map);
    map.panTo(item.position);
    if (scroll) {
      const cards = document.querySelectorAll('.location-card');
      cards.forEach(c => c.classList.remove('active'));
      cards[index]?.classList.add('active');
      cards[index]?.scrollIntoView({ behavior: 'smooth', inline: 'center', block: 'nearest' });
    }
  }
}

function createTimeline() {
  const t = getEl('timeline');
  t.innerHTML = `<div class="itinerary-summary-text">${itinerarySummary.replace(/\n/g, '<br>')}</div>`;
  let currentDay = -1;
  dayPlanItinerary.forEach((item, index) => {
    if (item.day !== currentDay) {
      currentDay = item.day;
      const h = document.createElement('div'); h.className = 'day-header';
      h.style.background = DAY_COLORS[(currentDay-1) % DAY_COLORS.length];
      h.innerHTML = `第 ${currentDay} 天`; t.appendChild(h);
    }
    const div = document.createElement('div'); div.className = 'timeline-item';
    div.innerHTML = `<div class="timeline-time">${item.time} ${item.weather_icon || '☀️'}</div><div class="timeline-title">${item.name}</div><p>${item.description}</p>`;
    div.onclick = () => highlightCard(index, true);
    t.appendChild(div);
  });
}

function createCards() {
  const container = getEl('card-container'); container.innerHTML = '';
  getEl('card-carousel').classList.remove('hidden');
  dayPlanItinerary.forEach((loc, index) => {
    const card = document.createElement('div'); card.className = 'location-card';
    card.innerHTML = `<div class="card-day-mini" style="background:${DAY_COLORS[(loc.day-1)%DAY_COLORS.length]}">D${loc.day}</div><div><div class="card-title-mini">${loc.name}</div><div class="card-time-mini">${loc.time}</div></div>`;
    card.onclick = () => highlightCard(index, true);
    container.appendChild(card);
  });
}

function drawRoute() {
  polylines.forEach(p => p.setMap(null)); polylines = [];
  const groups: any = {};
  dayPlanItinerary.forEach(i => { if (!groups[i.day]) groups[i.day] = []; groups[i.day].push(i.position); });
  Object.keys(groups).forEach(d => {
    const p = new google.maps.Polyline({ path: groups[d], strokeColor: DAY_COLORS[(parseInt(d)-1)%DAY_COLORS.length], strokeOpacity: 0.8, strokeWeight: 5, map });
    polylines.push(p);
  });
}

function restart() {
  dayPlanItinerary.forEach(i => i.marker.setMap(null));
  popUps.forEach(p => p.popup.setMap(null));
  polylines.forEach(p => p.setMap(null));
  dayPlanItinerary = []; popUps = []; polylines = [];
  getEl('card-container').innerHTML = '';
  getEl('card-carousel').classList.add('hidden');
  getEl('timeline-container').classList.remove('visible');
  bounds = new google.maps.LatLngBounds();
  window.history.replaceState({}, '', window.location.pathname);
}

function setStatus(msg: string, type: string) {
  const err = getEl('error-message');
  if (type === 'hidden') err.classList.add('hidden');
  else { err.innerText = msg; err.className = `error ${type}`; err.classList.remove('hidden'); }
}

function hideTimeline() { getEl('timeline-container').classList.remove('visible'); document.body.classList.remove('timeline-open'); if (dayPlanItinerary.length > 0) getEl('reopen-timeline').classList.remove('hidden'); }
function showTimeline() { getEl('timeline-container').classList.add('visible'); document.body.classList.add('timeline-open'); getEl('reopen-timeline').classList.add('hidden'); }

function bindEvents() {
  getEl('generate').onclick = handleRequest;
  getEl('reset').onclick = restart;
  getEl('share-btn').onclick = () => {
    const url = encodeStateToUrl();
    if (url) { getEl<HTMLInputElement>('share-url-input').value = url; getEl('share-modal').classList.remove('hidden'); }
  };
  getEl('close-share').onclick = () => getEl('share-modal').classList.add('hidden');
  getEl('share-modal').onclick = (e) => { if (e.target === getEl('share-modal')) getEl('share-modal').classList.add('hidden'); };
  getEl('copy-link-btn').onclick = () => { navigator.clipboard.writeText(getEl<HTMLInputElement>('share-url-input').value); alert("链接已复制"); };
  getEl('generate-poster-btn').onclick = generatePoster;
  getEl('download-poster-btn').onclick = () => {
    const l = document.createElement('a'); l.download = 'AI-Trip.png'; l.href = (getEl('poster-canvas') as HTMLCanvasElement).toDataURL(); l.click();
  };
  getEl('planner-mode-toggle').onchange = (e: any) => { isPlannerMode = e.target.checked; getEl('mode-text').innerText = isPlannerMode ? "行程规划模式" : "景点发现模式"; restart(); };
  getEl('close-timeline').onclick = hideTimeline;
  getEl('reopen-timeline').onclick = showTimeline;
  getEl('open-settings').onclick = () => getEl('settings-modal').classList.remove('hidden');
  getEl('close-settings').onclick = () => getEl('settings-modal').classList.add('hidden');
  getEl('save-settings').onclick = () => { localStorage.setItem('deepseek_api_key', getEl<HTMLInputElement>('deepseek-key-input').value); getEl('settings-modal').classList.add('hidden'); };
}

initApp();

@import url(https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css);

:root {
  --primary: #ff5722;
  --primary-hover: #f4511e;
  --glass: rgba(255, 255, 255, 0.95);
  --shadow: 0 4px 12px rgba(0,0,0,0.1);
  --radius: 12px;
}

* { box-sizing: border-box; padding: 0; margin: 0; font-family: 'PingFang SC', system-ui, sans-serif; }

html, body { height: 100%; width: 100%; overflow: hidden; background: #fff; }

.hidden { display: none !important; }

/* 地图全屏 */
.map-container { position: absolute; inset: 0; z-index: 1; }
#map { height: 100%; width: 100%; }

/* 搜索UI */
.search-container { 
  position: absolute; top: 16px; left: 50%; transform: translateX(-50%); 
  z-index: 100; width: 90%; max-width: 600px; 
  transition: all 0.3s ease;
}
.search-container.ui-hidden { transform: translate(-50%, -200px); opacity: 0; pointer-events: none; }

.search-header-group { display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px; gap: 8px; }

.header-left-controls { display: flex; align-items: center; gap: 10px; }

.mode-toggle { 
  background: var(--glass); padding: 4px 10px; border-radius: 20px; 
  display: flex; align-items: center; gap: 8px; box-shadow: var(--shadow);
}
.mode-label { font-size: 11px; font-weight: bold; color: #555; }

.switch { position: relative; width: 32px; height: 18px; }
.switch input { opacity: 0; width: 0; height: 0; }
.slider { position: absolute; inset: 0; background-color: #ddd; transition: .3s; border-radius: 20px; cursor: pointer; }
.slider:before { position: absolute; content: ""; height: 14px; width: 14px; left: 2px; bottom: 2px; background-color: white; transition: .3s; border-radius: 50%; }
input:checked + .slider { background-color: var(--primary); }
input:checked + .slider:before { transform: translateX(14px); }

.model-select {
  padding: 4px 10px; border-radius: 20px; border: none; background: var(--glass); 
  font-size: 11px; font-weight: bold; box-shadow: var(--shadow); cursor: pointer; outline: none;
}

.icon-btn-small { background: var(--glass); border: none; width: 28px; height: 28px; border-radius: 50%; box-shadow: var(--shadow); cursor: pointer; display: flex; align-items: center; justify-content: center; color: #555; }

.search-bar-stack { background: var(--glass); border-radius: 14px; padding: 4px 10px; box-shadow: var(--shadow); }
.search-bar { display: flex; align-items: center; gap: 8px; }
#prompt-input { flex: 1; border: none; outline: none; font-size: 14px; min-height: 40px; background: transparent; resize: none; padding: 8px 0; }
.search-button { background: var(--primary); color: white; border: none; width: 34px; height: 34px; border-radius: 50%; cursor: pointer; transition: 0.2s; }
.search-button:hover { background: var(--primary-hover); transform: scale(1.05); }

/* 轮播卡片 */
.card-carousel { 
  position: absolute; bottom: 16px; left: 0; right: 0; 
  z-index: 50; pointer-events: none; 
  transition: right 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}
body.timeline-open .card-carousel { right: 360px; }

.card-container { display: flex; overflow-x: auto; padding: 8px 16px; gap: 8px; scrollbar-width: none; pointer-events: auto; }
.card-container::-webkit-scrollbar { display: none; }

.location-card { 
  flex: 0 0 auto; min-width: 140px; background: white; border-radius: 30px; 
  padding: 6px 14px; box-shadow: 0 2px 8px rgba(0,0,0,0.1); 
  cursor: pointer; border: 1px solid #f0f0f0; display: flex; gap: 8px;
  align-items: center; transition: 0.2s; white-space: nowrap;
}
.location-card.active { border-color: var(--primary); background: #fff8f6; transform: scale(1.05); box-shadow: 0 0 15px rgba(255, 87, 34, 0.2); }

.card-day-mini { background: var(--primary); color: white; font-size: 10px; font-weight: 900; padding: 2px 6px; border-radius: 10px; }
.card-title-mini { font-weight: bold; font-size: 13px; color: #333; }
.card-time-mini { font-size: 11px; color: #999; }

/* 浮动按钮 */
.floating-control-btn { 
  position: absolute; z-index: 150; width: 42px; height: 42px; border-radius: 50%; 
  background: var(--glass); border: none; box-shadow: var(--shadow); cursor: pointer; 
  display: flex; align-items: center; justify-content: center; font-size: 18px; color: #333; transition: 0.2s;
}
.floating-control-btn:hover { background: white; transform: translateY(-2px); }
.toggle-ui-btn { top: 16px; left: 16px; }
.reopen-timeline-btn { top: 16px; right: 16px; background: var(--primary); color: white; }
.reset-button { bottom: 65px; right: 16px; }

/* 侧边栏 */
.timeline-container { 
  position: fixed; right: 0; top: 0; width: 360px; height: 100%; 
  background: white; z-index: 500; transform: translateX(100%); 
  transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1); box-shadow: -4px 0 20px rgba(0,0,0,0.08);
}
.timeline-container.visible { transform: translateX(0); }
.timeline-header { padding: 20px; border-bottom: 1px solid #f0f0f0; display: flex; justify-content: space-between; align-items: center; background: #fafafa; }
.timeline { padding: 20px; overflow-y: auto; height: calc(100% - 70px); }

.itinerary-summary-text { padding: 16px; background: #fffcfb; border-radius: 12px; margin-bottom: 24px; font-size: 14px; line-height: 1.8; color: #444; border: 1px solid #ffebe0; box-shadow: inset 0 2px 4px rgba(255, 87, 34, 0.03); white-space: pre-wrap; }

.day-header { padding: 6px 14px; background: #333; color: white; border-radius: 20px; margin: 24px 0 16px; font-size: 11px; font-weight: bold; display: inline-block; letter-spacing: 1px; }

.timeline-item { 
  border-left: 2px solid #f0f0f0; padding-left: 28px; margin-bottom: 30px; 
  cursor: pointer; position: relative; transition: all 0.2s ease;
}
.timeline-item:hover { border-left-color: var(--primary); background: rgba(255, 87, 34, 0.02); }

/* 模态框 */
.modal-overlay {
  position: fixed; inset: 0; background: rgba(0,0,0,0.6); 
  z-index: 2000; display: flex; align-items: center; justify-content: center;
  backdrop-filter: blur(5px);
}
.modal-content {
  background: white; border-radius: 20px; width: 90%; max-width: 500px; max-height: 90vh;
  box-shadow: 0 20px 40px rgba(0,0,0,0.2); overflow-y: auto;
}
.modal-header { padding: 20px; border-bottom: 1px solid #f0f0f0; display: flex; justify-content: space-between; align-items: center; }
.modal-body { padding: 20px; }
.close-modal-btn { background: none; border: none; font-size: 24px; cursor: pointer; color: #999; }

.poster-preview-area {
  border: 1px solid #eee; border-radius: 12px; min-height: 300px;
  background: #fafafa; position: relative; margin-top: 15px; overflow: hidden;
}
#poster-canvas { width: 100%; height: auto; display: block; border-radius: 12px; }

.primary-btn { width: 100%; padding: 14px; background: var(--primary); color: white; border: none; border-radius: 10px; font-weight: bold; cursor: pointer; }
.secondary-btn { padding: 10px 20px; background: #f0f0f0; color: #333; border: none; border-radius: 8px; font-weight: bold; cursor: pointer; }

/* 加载 */
.spinner { position: fixed; inset: 0; background: rgba(255,255,255,0.95); backdrop-filter: blur(10px); z-index: 1000; display: flex; flex-direction: column; align-items: center; justify-content: center; }
.spinner::after { content: ''; width: 48px; height: 48px; border: 4px solid #f3f3f3; border-top: 4px solid var(--primary); border-radius: 50%; animation: spin 1s infinite; margin-bottom: 20px; }
@keyframes spin { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }
.loading-text { font-size: 15px; color: #333; font-weight: 500; }

.error { background: #fee2e2; color: #dc2626; padding: 12px 16px; border-radius: 12px; margin-top: 12px; font-size: 13px; }

