}

* { box-sizing: border-box; padding: 0; margin: 0; font-family: 'PingFang SC', system-ui, -apple-system, sans-serif; }

html, body { height: 100%; width: 100%; overflow: hidden; background: var(--bg-light); color: var(--text-main); }

.hidden { display: none !important; }

/* App Shell Layout */
.app-shell { display: flex; height: 100vh; width: 100vw; }

/* Sidebar Styling */
.sidebar-left, .sidebar-right {
  display: flex;
  flex-direction: column;
  background: white;
  z-index: 100;
  transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  box-shadow: 0 0 20px rgba(0,0,0,0.05);
}

.sidebar-left { width: var(--sidebar-w); border-right: 1px solid var(--border-color); flex-shrink: 0; }
.sidebar-left.ui-hidden { transform: translateX(-100%); position: absolute; }

.sidebar-right {
  width: var(--timeline-w);
  border-left: 1px solid var(--border-color);
  position: fixed;
  right: 0;
  top: 0;
  height: 100%;
  transform: translateX(100%);
}
.sidebar-right.visible { transform: translateX(0); }

.sidebar-header {
  padding: 16px 20px;
