import { GoogleGenAI } from '@google/genai';
import { MarkerClusterer } from "@googlemaps/markerclusterer";
import { locationTool } from './mcp-tools';

declare const google: any;

// Application state
let map: any;
let popUps: any[] = [];
let bounds: any;
let markerCluster: any;
let activeCardIndex = 0;
let isPlannerMode = false;
let isUiHidden = false;
let dayPlanItinerary: any[] = [];
let itinerarySummary = "";
let polylines: any[] = []; 
let currentMapType = 'roadmap';

const TDT_DEFAULT_KEY = "97f9870fb795ba80ef201d6edae71d73";

const getEl = <T extends HTMLElement>(id: string) => document.getElementById(id) as T;
const DAY_COLORS = ['#ff5722', '#2196f3', '#4caf50', '#9c27b0', '#ffeb3b', '#00bcd4', '#795548'];

/**
 * 安全同步浏览器地址栏
 */
function safeReplaceState(url: string | URL) {
  try {
    if (window.history && window.history.replaceState) {
      window.history.replaceState({}, '', url);
    }
  } catch (e) {
    console.debug("跳过地址栏同步:", e);
  }
}

/**
 * 天地图图层构造器
 */
function createTiandituMapType(layer: string, tk: string) {
  return new google.maps.ImageMapType({
    getTileUrl: (coord: any, zoom: number) => {
      const sub = (coord.x + coord.y) % 8;
      return `https://t${sub}.tianditu.gov.cn/${layer}_w/wmts?SERVICE=WMTS&REQUEST=GetTile&VERSION=1.0.0&LAYER=${layer}&STYLE=default&TILEMATRIXSET=w&FORMAT=tiles&TILECOL=${coord.x}&TILEROW=${coord.y}&TILEMATRIX=${zoom}&tk=${tk}`;
    },
    tileSize: new google.maps.Size(256, 256),
    name: layer === 'vec' ? '天地图矢量' : '天地图影像',
    maxZoom: 18
  });
}

function createTiandituLabelType(layer: string, tk: string) {
  return new google.maps.ImageMapType({
    getTileUrl: (coord: any, zoom: number) => {
      const sub = (coord.x + coord.y) % 8;
      return `https://t${sub}.tianditu.gov.cn/${layer}_w/wmts?SERVICE=WMTS&REQUEST=GetTile&VERSION=1.0.0&LAYER=${layer}&STYLE=default&TILEMATRIXSET=w&FORMAT=tiles&TILECOL=${coord.x}&TILEROW=${coord.y}&TILEMATRIX=${zoom}&tk=${tk}`;
    },
    tileSize: new google.maps.Size(256, 256),
    name: '天地图注记',
    opacity: 1.0
  });
}

function transformSchemaToLowercase(schema: any): any {
  if (!schema || typeof schema !== 'object') return schema;
  const newSchema = Array.isArray(schema) ? [...schema] : { ...schema };
  if (newSchema.type && typeof newSchema.type === 'string') {
    newSchema.type = newSchema.type.toLowerCase();
  }
  if (newSchema.properties) {
    for (const key in newSchema.properties) {
      newSchema.properties[key] = transformSchemaToLowercase(newSchema.properties[key]);
    }
  }
  if (newSchema.items) {
    newSchema.items = transformSchemaToLowercase(newSchema.items);
  }
  return newSchema;
}

async function initApp() {
  try {
    const { Map } = await google.maps.importLibrary('maps') as any;
    const { LatLngBounds } = await google.maps.importLibrary('core') as any;
    bounds = new LatLngBounds();
    map = new Map(getEl('map'), {
      center: { lat: 39.9042, lng: 116.4074 }, 
      zoom: 12,
      disableDefaultUI: true,
      gestureHandling: 'greedy', 
      mapId: 'DEMO_MAP_ID',
      mapTypeId: 'roadmap'
    });

    // 加载设置并检查默认 Key
    const savedDeepSeekKey = localStorage.getItem('deepseek_api_key');
    let savedTdtKey = localStorage.getItem('tdt_api_key');

    if (!savedTdtKey) {
        savedTdtKey = TDT_DEFAULT_KEY;
        localStorage.setItem('tdt_api_key', TDT_DEFAULT_KEY);
    }

    if (savedDeepSeekKey) {
      const el = getEl<HTMLInputElement>('deepseek-key-input');
      if (el) el.value = savedDeepSeekKey;
    }
    if (savedTdtKey) {
      const el = getEl<HTMLInputElement>('tdt-key-input');
      if (el) el.value = savedTdtKey;
    }

    try { markerCluster = new MarkerClusterer({ map, markers: [] }); } catch (e) {}
    setupPopupClass();
    bindEvents();
    await loadPlanFromUrl();
    getEl('spinner').classList.add('hidden');
  } catch (err) {
    console.error("Map Initialization Failed", err);
  }
}

function setupPopupClass() {
  (window as any).Popup = class Popup extends google.maps.OverlayView {
    position: any; containerDiv: HTMLDivElement;
    constructor(position: any, content: HTMLElement) {
      super();
      this.position = position;
      this.containerDiv = document.createElement('div');
      this.containerDiv.classList.add('custom-map-popup');
      const bubble = document.createElement('div');
      bubble.classList.add('popup-bubble');
      bubble.appendChild(content);
      this.containerDiv.appendChild(bubble);
      google.maps.OverlayView.preventMapHitsAndGesturesFrom(this.containerDiv);
    }
    onAdd() { (this as any).getPanes().floatPane.appendChild(this.containerDiv); }
    onRemove() { if (this.containerDiv.parentElement) this.containerDiv.parentElement.removeChild(this.containerDiv); }
    draw() {
      const divPosition = (this as any).getProjection().fromLatLngToDivPixel(this.position);
      if (divPosition) { this.containerDiv.style.left = divPosition.x + 'px'; this.containerDiv.style.top = divPosition.y + 'px'; }
    }
  };
}

function encodeStateToUrl() {
  if (dayPlanItinerary.length === 0) return null;
  const simplifiedItinerary = dayPlanItinerary.map(item => ({
    name: item.name, description: item.description, lat: item.lat, lng: item.lng,
    time: item.time, day: item.day, sequence: item.sequence, transit_hint: item.transit_hint,
    weather_icon: item.weather_icon, temperature: item.temperature, category: item.category
  }));
  const data = { summary: itinerarySummary, items: simplifiedItinerary, isPlanner: isPlannerMode };
  const jsonStr = JSON.stringify(data);
  const base64 = btoa(encodeURIComponent(jsonStr));
  const url = new URL(window.location.href);
  url.searchParams.set('plan', base64);
  return url.toString();
}

async function loadPlanFromUrl() {
  const params = new URLSearchParams(window.location.search);
  const base64 = params.get('plan');
  if (!base64) return;
  try {
    const jsonStr = decodeURIComponent(atob(base64));
    const data = JSON.parse(jsonStr);
    itinerarySummary = data.summary || "";
    isPlannerMode = data.isPlanner || false;
    const toggle = getEl('planner-mode-toggle') as HTMLInputElement;
    if (toggle) {
      toggle.checked = isPlannerMode;
      const modeText = getEl('mode-text');
      if (modeText) modeText.innerText = isPlannerMode ? "行程规划模式" : "景点发现模式";
      if (isPlannerMode) {
        const prefGroup = getEl('preference-toggle-group');
        if (prefGroup) prefGroup.classList.remove('hidden');
      }
    }
    for (const item of data.items) { await setPin(item); }
    if (dayPlanItinerary.length > 0) {
      dayPlanItinerary.sort((a, b) => (a.day - b.day) || (a.sequence - b.sequence));
      createCards();
      if (isPlannerMode) { drawRoute(); createTimeline(); showTimeline(); }
      highlightCard(0, true);
    }
  } catch (e) { console.error("URL Load Failed", e); }
}

async function handleRequest() {
  const promptInput = getEl<HTMLTextAreaElement>('prompt-input');
  const modelSelector = getEl<HTMLSelectElement>('model-selector');
  const routePreference = getEl<HTMLSelectElement>('route-preference');

  const userInput = promptInput ? promptInput.value.trim() : "";
  const selectedModel = modelSelector ? modelSelector.value : "gemini-3-pro-preview";
  const routePref = routePreference ? routePreference.value : "budget";

  if (!userInput) return;
  restart();
  getEl('spinner').classList.remove('hidden');
  try {
    if (selectedModel.startsWith('deepseek')) {
      await handleDeepSeekRequest(selectedModel, userInput);
    } else {
      await handleGeminiRequest(selectedModel, userInput, routePref);
    }
    if (dayPlanItinerary.length === 0) throw new Error("AI 未能识别地图节点");
    dayPlanItinerary.sort((a, b) => (a.day - b.day) || (a.sequence - b.sequence));
    createCards();
    if (isPlannerMode) { drawRoute(); createTimeline(); showTimeline(); } else { hideTimeline(); }
    highlightCard(0, true);
    const errEl = getEl('error-message');
    if (errEl) errEl.classList.add('hidden');
  } catch (e: any) {
    const errEl = getEl('error-message');
    if (errEl) {
      errEl.innerText = "⚠️ " + (e.message || "请求失败");
      errEl.classList.remove('hidden');
    }
  } finally {
    getEl('spinner').classList.add('hidden');
  }
}

async function handleGeminiRequest(model: string, input: string, preference: string) {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const prefText = preference === 'budget' ? "注重经济性价比" : "注重时间宽松和深度体验";

  const response = await ai.models.generateContent({
    model: model,
    contents: [{
      role: 'user',
      parts: [{ text: `目的地及需求：${input}。偏好：${prefText}。` }]
    }],
    config: {
      systemInstruction: `你是一位世界顶级的旅游行程规划专家，具备实时联网搜索能力。

      【严格执行规范】:
      1. **完整性承诺**: 严禁只返回第一天行程！如果用户需求涉及多天（如“3天2夜”），你必须为【每一天】的【每一个】景点、餐厅和酒店分别调用 'location' 工具。
      2. **实时搜索 (googleSearch)**: 必须先搜索目的地最新的天气、交通（高铁/航班）和避坑指南。
      3. **函数调用优先级**: 先执行所有的 'location' 工具调用，确保地图标记覆盖全部行程，最后再输出 Markdown 文本总结。
      4. **打点要求**: 
         - weather_icon: 必须使用 Emoji (☀️, 🌧️ 等)加温度显示。
         - temperature: 基于搜索结果给出气温。
         - description: 包含该地点的“避坑指南”和“博主拍照位”。
         - category: 必须分类为 SIGHT, FOOD, HOTEL, 或 TRANSIT。
      5. **Markdown 攻略**: 文本部分应不少于 800 字，包含每日穿搭、转场攻略和实时信息。
      6. 使用中文，语言生动形象，充满博主感。`,
      tools: [{ googleSearch: {} }, { functionDeclarations: [locationTool] }],
    },
  });

  const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
  if (groundingChunks) displayGroundingSources(groundingChunks);

  const functionCalls = response.functionCalls || [];
  for (const fc of functionCalls) {
    if (fc.name === 'location') await setPin(fc.args);
  }

  itinerarySummary = response.text || "行程规划已完成。";
}

async function handleDeepSeekRequest(model: string, input: string) {
  let apiKey = localStorage.getItem('deepseek_api_key') || '';
  const tools = [{
    type: "function",
    function: { name: "location", parameters: transformSchemaToLowercase(locationTool.parameters) }
  }];
  const response = await fetch('https://api.deepseek.com/chat/completions', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiKey}` },
    body: JSON.stringify({
      model: model,
      messages: [{ role: 'user', content: input }],
      tools: tools, tool_choice: "auto"
    })
  });
  const data = await response.json();
  const message = data.choices[0].message;
  itinerarySummary = message.content || "";
  if (message.tool_calls) {
    for (const tc of message.tool_calls) {
      if (tc.function.name === 'location') await setPin(JSON.parse(tc.function.arguments));
    }
  }
}

function displayGroundingSources(chunks: any[]) {
  const sourceList = getEl('source-list');
  const groundingContainer = getEl('grounding-sources');
  sourceList.innerHTML = '';
  const uniqueSources = new Set();
  chunks.forEach(chunk => {
    if (chunk.web && chunk.web.uri) {
      if (!uniqueSources.has(chunk.web.uri)) {
        uniqueSources.add(chunk.web.uri);
        const li = document.createElement('li');
        li.innerHTML = `<a href="${chunk.web.uri}" target="_blank">${chunk.web.title || chunk.web.uri}</a>`;
        sourceList.appendChild(li);
      }
    }
  });
  if (uniqueSources.size > 0) groundingContainer.classList.remove('hidden');
}

async function setPin(args: any) {
  const { name, lat, lng, weather_icon, day } = args;
  const pos = { lat: parseFloat(lat), lng: parseFloat(lng) };
  if (isNaN(pos.lat)) return;
  bounds.extend(pos);
  const color = DAY_COLORS[(day - 1) % DAY_COLORS.length];
  const marker = new google.maps.Marker({
    position: pos, title: name, map: map,
    icon: { path: google.maps.SymbolPath.CIRCLE, fillColor: color, fillOpacity: 1, strokeWeight: 2, strokeColor: '#fff', scale: 8 }
  });
  const content = document.createElement('div');
  content.innerHTML = `<div style="display:flex; align-items:center; gap:4px;"><span style="font-size:14px;">${weather_icon || '📍'}</span><strong style="font-size:11px;">${name}</strong></div>`;
  const popup = new (window as any).Popup(new google.maps.LatLng(pos), content);
  const item = { ...args, position: new google.maps.LatLng(pos), popup, marker };
  dayPlanItinerary.push(item);
  popUps.push(item);
  map.fitBounds(bounds);
}

/**
 * 分享指南：生成海报
 */
async function generatePoster() {
  const placeholder = getEl('poster-placeholder');
  const result = getEl('poster-result');
  const btn = getEl('generate-poster-btn') as HTMLButtonElement;
  btn.disabled = true;

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const firstPlace = dayPlanItinerary[0]?.name || "目的地";

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: `A vibrant travel poster for ${firstPlace}, modern layout, cinematic lighting.` }] },
      config: { imageConfig: { aspectRatio: "9:16" } }
    });

    let base64Image = "";
    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) base64Image = part.inlineData.data;
    }

    const canvas = getEl('poster-canvas') as HTMLCanvasElement;
    const ctx = canvas.getContext('2d')!;
    const img = new Image();
    img.src = `data:image/png;base64,${base64Image}`;

    img.onload = () => {
      ctx.drawImage(img, 0, 0, canvas.width, 800);
      ctx.fillStyle = "white";
      ctx.fillRect(0, 800, canvas.width, canvas.height - 800);
      ctx.fillStyle = "#333";
      ctx.textAlign = "center";
      ctx.font = "bold 48px 'PingFang SC'";
      ctx.fillText(firstPlace, canvas.width / 2, 880);

      ctx.font = "24px 'PingFang SC'";
      ctx.fillText("AI 深度旅行指南", canvas.width / 2, 930);

      placeholder.classList.add('hidden');
      result.classList.remove('hidden');
      btn.disabled = false;
    };
  } catch (err) {
    btn.disabled = false;
  }
}

function bindEvents() {
  // 地图工具逻辑
  const toggleMapTypeBtn = getEl('toggle-map-type');
  const mapTypeMenu = getEl('map-type-menu');

  if (toggleMapTypeBtn && mapTypeMenu) {
    toggleMapTypeBtn.onclick = (e) => {
      e.stopPropagation();
      mapTypeMenu.classList.toggle('hidden');
    };

    document.addEventListener('click', () => {
      mapTypeMenu.classList.add('hidden');
    });

    mapTypeMenu.onclick = (e) => e.stopPropagation();
  }

  const menuItems = document.querySelectorAll('.menu-item');
  menuItems.forEach(item => {
    (item as HTMLElement).onclick = function(this: HTMLElement) {
      const type = this.getAttribute('data-type');
      if (!type) return;
      menuItems.forEach(i => i.classList.remove('active'));
      this.classList.add('active');

      const tk = localStorage.getItem('tdt_api_key') || TDT_DEFAULT_KEY;

      if (type.startsWith('tdt')) {
        const layer = type === 'tdt_vec' ? 'vec' : 'img';
        const label = type === 'tdt_vec' ? 'cva' : 'cia';
        map.mapTypes.set(type, createTiandituMapType(layer, tk));
        map.setMapTypeId(type);
        map.overlayMapTypes.clear();
        map.overlayMapTypes.push(createTiandituLabelType(label, tk));
      } else {
        map.setMapTypeId(type);
        map.overlayMapTypes.clear();
      }

      if (mapTypeMenu) mapTypeMenu.classList.add('hidden');
    };
  });

  // 模式切换
  const plannerToggle = getEl<HTMLInputElement>('planner-mode-toggle');
  if (plannerToggle) {
    plannerToggle.onchange = (e) => {
      isPlannerMode = (e.target as HTMLInputElement).checked;
      const modeText = getEl('mode-text');
      if (modeText) modeText.innerText = isPlannerMode ? "行程规划模式" : "景点发现模式";
      const prefGroup = getEl('preference-toggle-group');
      if (prefGroup) {
        if (isPlannerMode) prefGroup.classList.remove('hidden'); else prefGroup.classList.add('hidden');
      }
      restart();
    };
  }

  // UI 显示隐藏
  const toggleUiBtn = getEl('toggle-search-ui');
  if (toggleUiBtn) {
    toggleUiBtn.onclick = () => {
      isUiHidden = !isUiHidden;
      getEl('sidebar-left').classList.toggle('ui-hidden');
      const icon = toggleUiBtn.querySelector('i');
      if (icon) icon.className = isUiHidden ? 'fas fa-compress' : 'fas fa-expand';
    };
  }

  const generateBtn = getEl('generate');
  if (generateBtn) generateBtn.onclick = handleRequest;

  const resetBtn = getEl('reset');
  if (resetBtn) resetBtn.onclick = restart;

  getEl('share-btn').onclick = () => {
    const url = encodeStateToUrl();
    if (url) {
      const shareInput = getEl<HTMLInputElement>('share-url-input');
      if (shareInput) shareInput.value = url;
      getEl('share-modal').classList.remove('hidden');
    }
  };

  getEl('save-settings').onclick = () => {
    const dsKeyInput = getEl<HTMLInputElement>('deepseek-key-input');
    const tdtKeyInput = getEl<HTMLInputElement>('tdt-key-input');
    if (dsKeyInput) localStorage.setItem('deepseek_api_key', dsKeyInput.value.trim());
    if (tdtKeyInput) localStorage.setItem('tdt_api_key', tdtKeyInput.value.trim());
    getEl('settings-modal').classList.add('hidden');
  };

  getEl('open-settings').onclick = () => getEl('settings-modal').classList.remove('hidden');
  getEl('close-settings').onclick = () => getEl('settings-modal').classList.add('hidden');
  getEl('close-share').onclick = () => getEl('share-modal').classList.add('hidden');
  getEl('generate-poster-btn').onclick = generatePoster;
  getEl('close-timeline').onclick = hideTimeline;
  getEl('reopen-timeline').onclick = showTimeline;

  getEl('export-btn').onclick = () => {
    let md = `# AI 深度行程指南\n\n## 攻略总结\n${itinerarySummary}\n\n## 详细路线\n`;
    let currentDay = -1;
    dayPlanItinerary.forEach(item => {
      if (item.day !== currentDay) {
        currentDay = item.day;
        md += `\n### 第 ${currentDay} 天\n`;
      }
      md += `#### ${item.time} - ${item.name} (${item.weather_icon})\n`;
      md += `${item.description}\n\n`;
      if (item.transit_hint) md += `* **交通建议**: ${item.transit_hint}\n\n`;
    });

    const blob = new Blob([md], { type: 'text/markdown' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = `行程指南_${new Date().toLocaleDateString()}.md`;
    a.click();
  };
}

function highlightCard(index: number, scroll: boolean = false) {
  popUps.forEach(p => p.popup.setMap(null));
  activeCardIndex = Math.max(0, Math.min(index, dayPlanItinerary.length - 1));
  const item = dayPlanItinerary[activeCardIndex];
  if (item) {
    item.popup.setMap(map);
    map.panTo(item.position);
    if (scroll) {
      const cards = document.querySelectorAll('.location-card');
      cards.forEach(c => c.classList.remove('active'));
      if (cards[activeCardIndex]) {
        cards[activeCardIndex].classList.add('active');
        cards[activeCardIndex].scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'center' });
      }
      const tlItems = document.querySelectorAll('.timeline-item');
      tlItems.forEach(t => t.classList.remove('active'));
      tlItems[activeCardIndex]?.classList.add('active');
      tlItems[activeCardIndex]?.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }
  }
}

function createTimeline() {
  const t = getEl('timeline');
  t.innerHTML = `<div class="itinerary-summary-text">${itinerarySummary.replace(/\n/g, '<br>')}</div>`;
  let currentDay = -1;
  dayPlanItinerary.forEach((item, index) => {
    if (item.day !== currentDay) {
      currentDay = item.day;
      const h = document.createElement('div');
      h.className = 'day-header';
      h.innerHTML = `<span style="background: ${DAY_COLORS[(currentDay - 1) % DAY_COLORS.length]}">Day ${currentDay}</span>`;
      t.appendChild(h);
    }
    const div = document.createElement('div');
    div.className = `timeline-item`;
    const cat = item.category || 'SIGHT';
    const catLabels: any = { 'SIGHT': '景点', 'FOOD': '美食', 'HOTEL': '住宿', 'TRANSIT': '交通' };

    div.innerHTML = `
      <div class="timeline-content-card">
        <div class="timeline-time-meta">
          <span>${item.time}</span>
          <span class="item-category-tag cat-${cat}">${catLabels[cat] || cat}</span>
        </div>
        <div class="timeline-title">${item.weather_icon || ''} ${item.name}</div>
        <div class="timeline-desc">${item.description}</div>
      </div>`;
    div.onclick = () => highlightCard(index, true);
    t.appendChild(div);
  });
}

function createCards() {
  const container = getEl('card-container');
  container.innerHTML = '';
  getEl('card-carousel').classList.remove('hidden');
  dayPlanItinerary.forEach((loc, index) => {
    const card = document.createElement('div');
    card.className = `location-card`;
    card.innerHTML = `<div class="card-day-mini" style="background: ${DAY_COLORS[(loc.day - 1) % DAY_COLORS.length]}">D${loc.day}</div><div class="card-title-mini">${loc.name}</div>`;
    card.onclick = () => highlightCard(index, true);
    container.appendChild(card);
  });
}

function drawRoute() {
  polylines.forEach(p => p.setMap(null));
  polylines = [];
  const routesByDay: { [key: number]: any[] } = {};
  dayPlanItinerary.forEach(item => { if (!routesByDay[item.day]) routesByDay[item.day] = []; routesByDay[item.day].push(item.position); });
  Object.keys(routesByDay).forEach(dayStr => {
    const day = parseInt(dayStr);
    const poly = new google.maps.Polyline({ path: routesByDay[day], strokeColor: DAY_COLORS[(day - 1) % DAY_COLORS.length], strokeOpacity: 0.8, strokeWeight: 4, map });
    polylines.push(poly);
  });
}

function restart() {
  popUps.forEach(p => p.popup.setMap(null));
  polylines.forEach(p => p.setMap(null));
  polylines = [];
  dayPlanItinerary.forEach(item => { if (item.marker) item.marker.setMap(null); });
  dayPlanItinerary = [];
  getEl('card-container').innerHTML = '';
  getEl('card-carousel').classList.add('hidden');
  getEl('timeline-container').classList.remove('visible');
  bounds = new google.maps.LatLngBounds();
  safeReplaceState(window.location.pathname);
}

function hideTimeline() { getEl('timeline-container').classList.remove('visible'); getEl('reopen-timeline').classList.remove('hidden'); }
function showTimeline() { getEl('timeline-container').classList.add('visible'); getEl('reopen-timeline').classList.add('hidden'); }

initApp();

