@import url(https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css);

:root {
  --primary: #ff5722;
  --primary-hover: #f4511e;
  --bg-dark: #1e293b;
  --bg-light: #f8fafc;
  --border-color: #e2e8f0;
  --text-main: #0f172a;
  --text-muted: #64748b;
  --glass: rgba(255, 255, 255, 0.85);
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.12);
  --shadow-md: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
  --shadow-lg: 0 20px 25px -5px rgba(0, 0, 0, 0.15), 0 10px 10px -5px rgba(0, 0, 0, 0.04);
  --radius: 12px;
  --sidebar-w: 320px;
  --timeline-w: 380px;

  /* Category Colors */
  --color-sight: #3b82f6;
  --color-food: #f59e0b;
  --color-hotel: #10b981;
  --color-transit: #6366f1;
  --color-xhs: #ff2442;
  --color-douyin: #25f4ee;
}

* { box-sizing: border-box; padding: 0; margin: 0; font-family: 'PingFang SC', system-ui, -apple-system, sans-serif; }

html, body { height: 100%; width: 100%; overflow: hidden; background: var(--bg-light); color: var(--text-main); }

.hidden { display: none !important; }

/* App Shell Layout */
.app-shell { display: flex; height: 100vh; width: 100vw; }

/* Sidebar Styling */
.sidebar-left, .sidebar-right {
  display: flex;
  flex-direction: column;
  background: white;
  z-index: 100;
  transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  box-shadow: 0 0 20px rgba(0,0,0,0.05);
}

.sidebar-left { width: var(--sidebar-w); border-right: 1px solid var(--border-color); flex-shrink: 0; }
.sidebar-left.ui-hidden { transform: translateX(-100%); position: absolute; }

.sidebar-right {
  width: var(--timeline-w);
  border-left: 1px solid var(--border-color);
  position: fixed;
  right: 0;
  top: 0;
  height: 100%;
  transform: translateX(100%);
}
.sidebar-right.visible { transform: translateX(0); }

.sidebar-header {
  padding: 16px 20px;
  border-bottom: 1px solid var(--border-color);
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: white;
  min-height: 64px;
}

.brand { display: flex; align-items: center; gap: 10px; font-weight: 800; font-size: 1.1rem; color: var(--primary); }

.sidebar-scroll {
  flex: 1;
  overflow-y: auto;
  padding: 20px;
  scrollbar-width: thin;
}

.sidebar-footer {
  padding: 16px;
  border-top: 1px solid var(--border-color);
  background: var(--bg-light);
}

/* Timeline Styles */
.itinerary-summary-text {
  padding: 18px;
  background: #fffcfb;
  border-radius: 12px;
  border: 1px solid #ffebe0;
