function drawRoute() {
  polylines.forEach(p => p.setMap(null));
  polylines = [];

  const dailyGroups = new Map<number, any[]>();
  dayPlanItinerary.forEach(item => {
    if (!dailyGroups.has(item.day)) dailyGroups.set(item.day, []);
    dailyGroups.get(item.day)!.push(item);
  });

  dailyGroups.forEach((items, day) => {
    items.sort((a, b) => a.sequence - b.sequence);
    const path = items.map(i => i.position);
    const color = DAY_COLORS[(day - 1) % DAY_COLORS.length];

    const polyline = new google.maps.Polyline({
      path: path,
      geodesic: true,
      strokeColor: color,
      strokeOpacity: 0.8,
      strokeWeight: 4,
      map: map
    });
    polylines.push(polyline);
  });
}

function createTimeline() {
  // Use timeline-content to match the HTML structure
  const container = getEl('timeline-content');
  if (!container) return;
  container.innerHTML = `<div style="padding:15px; background:#fff8f6; border-radius:10px; font-size:13px; line-height:1.6; margin-bottom:20px; border:1px solid #ffebe0;">${itinerarySummary.replace(/\n/g, '<br>')}</div>`;

  const dailyGroups = new Map<number, any[]>();
  dayPlanItinerary.forEach(item => {
    if (!dailyGroups.has(item.day)) dailyGroups.set(item.day, []);
    dailyGroups.get(item.day)!.push(item);
  });

  const sortedDays = Array.from(dailyGroups.keys()).sort((a, b) => a - b);

  sortedDays.forEach(day => {
    const dayHeader = document.createElement('div');
    dayHeader.className = 'timeline-day-header';
    dayHeader.style.color = DAY_COLORS[(day - 1) % DAY_COLORS.length];
    dayHeader.innerText = `Day ${day}`;
    container.appendChild(dayHeader);

    const items = dailyGroups.get(day)!;
    items.sort((a, b) => a.sequence - b.sequence);

    items.forEach(item => {
      const entry = document.createElement('div');
      entry.className = 'timeline-entry';
      entry.innerHTML = `
        <div class="timeline-time">${item.time}</div>
        <div class="timeline-dot" style="background: ${DAY_COLORS[(day - 1) % DAY_COLORS.length]}"></div>
        <div class="timeline-details">
          <div class="timeline-title">${item.weather_icon || ''} ${item.name}</div>
          <div style="font-size:11px; color:var(--text-muted); margin-bottom:5px;">${item.weather_condition} · ${item.temperature}</div>
          <div class="timeline-desc">${item.description || ''}</div>
          ${item.transit_hint ? `<div style="margin-top:8px; font-size:11px; color:var(--primary); background:#fff5f2; padding:6px; border-radius:6px;"><i class="fas fa-bus"></i> ${item.transit_hint}</div>` : ''}
        </div>
      `;
      entry.onclick = () => {
        const idx = dayPlanItinerary.indexOf(item);
        if (idx !== -1) highlightCard(idx, true);
      };
      container.appendChild(entry);
    });
  });
}

function restart() {
