import { GoogleGenAI } from '@google/genai';
import { MarkerClusterer } from "@googlemaps/markerclusterer";
import { locationTool, socialRecommendationTool } from './mcp-tools';

declare const google: any;

// Application state
let map: any;
let popUps: any[] = [];
let bounds: any;
let markerCluster: any;
let activeCardIndex = 0;
let isPlannerMode = false;
let isUiHidden = false;
let dayPlanItinerary: any[] = [];
let socialRecommendations: any[] = [];
let itinerarySummary = "";
let polylines: any[] = []; 

// Default Keys
const TDT_DEFAULT_KEY = "97f9870fb795ba80ef201d6edae71d73";

const getEl = <T extends HTMLElement>(id: string) => document.getElementById(id) as T;
const DAY_COLORS = ['#ff5722', '#2196f3', '#4caf50', '#9c27b0', '#ffeb3b', '#00bcd4', '#795548'];

/**
 * 动态加载 Google Maps 脚本
 */
function loadGoogleMapsScript(apiKey: string): Promise<void> {
  return new Promise((resolve, reject) => {
    if ((window as any).google && (window as any).google.maps) {
      resolve();
      return;
    }
    const script = document.createElement('script');
    script.src = `https://maps.googleapis.com/maps/api/js?key=${apiKey}&libraries=maps,core&v=weekly`;
    script.async = true;
    script.defer = true;
    script.onload = () => resolve();
    script.onerror = (e) => reject(e);
    document.head.appendChild(script);
  });
}

/**
 * 天地图图层构造器
 */
function createTiandituMapType(layer: string, tk: string) {
  return new google.maps.ImageMapType({
    getTileUrl: (coord: any, zoom: number) => {
      const sub = (coord.x + coord.y) % 8;
      return `https://t${sub}.tianditu.gov.cn/${layer}_w/wmts?SERVICE=WMTS&REQUEST=GetTile&VERSION=1.0.0&LAYER=${layer}&STYLE=default&TILEMATRIXSET=w&FORMAT=tiles&TILECOL=${coord.x}&TILEROW=${coord.y}&TILEMATRIX=${zoom}&tk=${tk}`;
    },
    tileSize: new google.maps.Size(256, 256),
    name: layer === 'vec' ? '天地图矢量' : '天地图影像',
    maxZoom: 18
  });
}

function createTiandituLabelType(layer: string, tk: string) {
  return new google.maps.ImageMapType({
    getTileUrl: (coord: any, zoom: number) => {
      const sub = (coord.x + coord.y) % 8;
      return `https://t${sub}.tianditu.gov.cn/${layer}_w/wmts?SERVICE=WMTS&REQUEST=GetTile&VERSION=1.0.0&LAYER=${layer}&STYLE=default&TILEMATRIXSET=w&FORMAT=tiles&TILECOL=${coord.x}&TILEROW=${coord.y}&TILEMATRIX=${zoom}&tk=${tk}`;
    },
    tileSize: new google.maps.Size(256, 256),
    name: '天地图注记',
    opacity: 1.0
  });
}

async function initApp() {
  const savedGmapsKey = localStorage.getItem('gmaps_api_key');
  if (!savedGmapsKey) {
    getEl('map-error-overlay').classList.remove('hidden');
    getEl('spinner').classList.add('hidden');
    bindInitialEvents();
    return;
  }

  try {
    await loadGoogleMapsScript(savedGmapsKey);
    const { Map } = await google.maps.importLibrary('maps') as any;
    const { LatLngBounds } = await google.maps.importLibrary('core') as any;

    bounds = new LatLngBounds();
    map = new Map(getEl('map'), {
      center: { lat: 39.9042, lng: 116.4074 }, 
      zoom: 12,
      disableDefaultUI: true,
      gestureHandling: 'greedy', 
      mapId: 'DEMO_MAP_ID'
    });

    // 默认加载天地图
    const tdtKey = localStorage.getItem('tdt_api_key') || TDT_DEFAULT_KEY;
    const tdtType = createTiandituMapType('vec', tdtKey);
    map.mapTypes.set('tdt_vec', tdtType);
    map.setMapTypeId('tdt_vec');
    map.overlayMapTypes.push(createTiandituLabelType('cva', tdtKey));

    window.addEventListener('resize', () => {
      if (map && bounds && !bounds.isEmpty()) {
        map.fitBounds(bounds);
      }
    });

    // 初始化界面值
    const savedDeepSeekKey = localStorage.getItem('deepseek_api_key');
    if (savedDeepSeekKey) (getEl('deepseek-key-input') as HTMLInputElement).value = savedDeepSeekKey;
    (getEl('tdt-key-input') as HTMLInputElement).value = tdtKey;
    (getEl('gmaps-key-input') as HTMLInputElement).value = savedGmapsKey;

    setupPopupClass();
    bindEvents();
    await loadPlanFromUrl();
    getEl('spinner').classList.add('hidden');
  } catch (err) {
    console.error("Map Initialization Failed", err);
    getEl('map-error-overlay').classList.remove('hidden');
    getEl('spinner').classList.add('hidden');
    bindInitialEvents();
  }
}

function setupPopupClass() {
  (window as any).Popup = class Popup extends google.maps.OverlayView {
    position: any; containerDiv: HTMLDivElement;
    constructor(position: any, content: HTMLElement) {
      super();
      this.position = position;
      this.containerDiv = document.createElement('div');
      this.containerDiv.classList.add('custom-map-popup');
      const bubble = document.createElement('div');
      bubble.classList.add('popup-bubble');
      bubble.appendChild(content);
      this.containerDiv.appendChild(bubble);
      google.maps.OverlayView.preventMapHitsAndGesturesFrom(this.containerDiv);
    }
    onAdd() { (this as any).getPanes().floatPane.appendChild(this.containerDiv); }
    onRemove() { if (this.containerDiv.parentElement) this.containerDiv.parentElement.removeChild(this.containerDiv); }
    draw() {
      const divPosition = (this as any).getProjection().fromLatLngToDivPixel(this.position);
      if (divPosition) { this.containerDiv.style.left = divPosition.x + 'px'; this.containerDiv.style.top = divPosition.y + 'px'; }
    }
  };
}

function bindInitialEvents() {
  getEl('open-settings').onclick = () => getEl('settings-modal').classList.remove('hidden');
  getEl('open-settings-error').onclick = () => getEl('settings-modal').classList.remove('hidden');
  getEl('close-settings').onclick = () => getEl('settings-modal').classList.add('hidden');
  getEl('save-settings').onclick = () => {
    localStorage.setItem('gmaps_api_key', (getEl('gmaps-key-input') as HTMLInputElement).value.trim());
    localStorage.setItem('deepseek_api_key', (getEl('deepseek-key-input') as HTMLInputElement).value.trim());
    localStorage.setItem('tdt_api_key', (getEl('tdt-key-input') as HTMLInputElement).value.trim());
    window.location.reload();
  };
}

function bindEvents() {
  bindInitialEvents();

  getEl('toggle-map-type').onclick = (e) => { 
    e.stopPropagation(); 
    getEl('map-type-menu').classList.toggle('hidden'); 
  };

  document.addEventListener('click', () => getEl('map-type-menu').classList.add('hidden'));

  document.querySelectorAll('.menu-item').forEach(item => {
    (item as HTMLElement).onclick = function() {
      const type = (this as HTMLElement).getAttribute('data-type');
      if (!type) return;
      document.querySelectorAll('.menu-item').forEach(i => (i as HTMLElement).classList.remove('active'));
      (this as HTMLElement).classList.add('active');
      const tk = localStorage.getItem('tdt_api_key') || TDT_DEFAULT_KEY;
      map.overlayMapTypes.clear();
      if (type.startsWith('tdt')) {
        const layer = type === 'tdt_vec' ? 'vec' : 'img';
        const label = type === 'tdt_vec' ? 'cva' : 'cia';
        map.mapTypes.set(type, createTiandituMapType(layer, tk));
        map.setMapTypeId(type);
        map.overlayMapTypes.push(createTiandituLabelType(label, tk));
      } else {
        map.setMapTypeId(type);
      }
    };
  });

  getEl('planner-mode-toggle').onchange = (e) => {
    isPlannerMode = (e.target as HTMLInputElement).checked;
    getEl('mode-text').innerText = isPlannerMode ? "行程规划模式" : "景点发现模式";
    if (isPlannerMode) getEl('preference-toggle-group').classList.remove('hidden'); else getEl('preference-toggle-group').classList.add('hidden');
    restart();
  };

  getEl('toggle-search-ui').onclick = () => {
    isUiHidden = !isUiHidden;
    getEl('sidebar-left').classList.toggle('ui-hidden');
    const icon = getEl('toggle-search-ui').querySelector('i');
    if (icon) icon.className = isUiHidden ? 'fas fa-compress' : 'fas fa-expand';
    setTimeout(() => google.maps.event.trigger(map, "resize"), 400);
  };

  getEl('generate').onclick = handleRequest;
  getEl('reset').onclick = restart;
  getEl('close-share').onclick = () => getEl('share-modal').classList.add('hidden');
  getEl('close-timeline').onclick = hideTimeline;
  getEl('reopen-timeline').onclick = showTimeline;
  getEl('share-btn').onclick = () => {
    const url = encodeStateToUrl();
    if (url) { (getEl('share-url-input') as HTMLInputElement).value = url; getEl('share-modal').classList.remove('hidden'); }
  };
}

async function handleRequest() {
  const userInput = (getEl('prompt-input') as HTMLTextAreaElement).value.trim();
  if (!userInput) return;
  restart();
  getEl('spinner').classList.remove('hidden');
  try {
    const selectedModel = (getEl('model-selector') as HTMLSelectElement).value;
    const routePref = (getEl('route-preference') as HTMLSelectElement).value;
    if (selectedModel.startsWith('deepseek')) {
      await handleDeepSeekRequest(selectedModel, userInput);
    } else {
      await handleGeminiRequest(selectedModel, userInput, routePref);
    }
    dayPlanItinerary.sort((a, b) => (a.day - b.day) || (a.sequence - b.sequence));
    createCards();
    if (isPlannerMode) { drawRoute(); createTimeline(); showTimeline(); }
    renderSocialRecommendations();
    highlightCard(0, true);
  } catch (e: any) {
    const errEl = getEl('error-message');
    errEl.innerText = "⚠️ " + (e.message || "请求失败");
    errEl.classList.remove('hidden');
  } finally {
    getEl('spinner').classList.add('hidden');
  }
}

async function handleGeminiRequest(model: string, input: string, preference: string) {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const response = await ai.models.generateContent({
    model: model,
    contents: [{ role: 'user', parts: [{ text: `目的地及需求：${input}。偏好：${preference === 'budget' ? "性价比" : "深度游"}。` }] }],
    config: {
      systemInstruction: `你是一位顶级旅游专家。必须调用 'get_social_recommendations' 整合趋势。必须为每一处景点调用 'location'。分类：SIGHT, FOOD, HOTEL, TRANSIT。`,
      tools: [{ functionDeclarations: [locationTool, socialRecommendationTool] }],
    },
  });
  const functionCalls = (response.functionCalls || []) as any[];
  for (const fc of functionCalls) {
    if (fc.name === 'location') await setPin(fc.args);
    if (fc.name === 'get_social_recommendations') socialRecommendations = fc.args.recommendations || [];
  }
  itinerarySummary = response.text || "";
}

async function handleDeepSeekRequest(model: string, input: string) {
  let apiKey = localStorage.getItem('deepseek_api_key') || '';
  const response = await fetch('https://api.deepseek.com/chat/completions', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiKey}` },
    body: JSON.stringify({ model: model, messages: [{ role: 'user', content: input }], 
    tools: [{ type: "function", function: { name: "location", parameters: transformSchemaToLowercase(locationTool.parameters) } }], tool_choice: "auto" })
  });
  const data = await response.json();
  const message = data.choices[0].message;
  itinerarySummary = message.content || "";
  if (message.tool_calls) {
    for (const tc of message.tool_calls) {
      if (tc.function.name === 'location') await setPin(JSON.parse(tc.function.arguments));
    }
  }
}

async function setPin(args: any) {
  const { name, lat, lng, weather_icon, weather_condition, temperature, day } = args;
  const pos = { lat: parseFloat(lat), lng: parseFloat(lng) };
  if (isNaN(pos.lat)) return;
  bounds.extend(pos);
  const color = DAY_COLORS[(day - 1) % DAY_COLORS.length];
  const marker = new google.maps.Marker({
    position: pos, title: name, map: map,
    icon: { path: google.maps.SymbolPath.CIRCLE, fillColor: color, fillOpacity: 1, strokeWeight: 2, strokeColor: '#fff', scale: 8 }
  });
  const content = document.createElement('div');
  content.innerHTML = `<div style="font-weight:800; font-size:14px; color:#ff5722;">${name}</div><div style="font-size:12px;">${weather_icon} ${weather_condition} ${temperature}</div>`;
  const popup = new (window as any).Popup(new google.maps.LatLng(pos), content);
  const item = { ...args, position: new google.maps.LatLng(pos), popup, marker };
  dayPlanItinerary.push(item);
  popUps.push(item);
  map.fitBounds(bounds);
}

function createCards() {
  const container = getEl('card-container');
  container.innerHTML = '';
  getEl('card-carousel').classList.remove('hidden');
  dayPlanItinerary.forEach((loc, index) => {
    const card = document.createElement('div');
    card.className = `location-card`;
    card.innerHTML = `<div class="card-day-mini" style="background:${DAY_COLORS[(loc.day-1)%DAY_COLORS.length]}">D${loc.day}</div><div class="card-title-mini">${loc.name}</div>`;
    card.onclick = () => highlightCard(index, true);
    container.appendChild(card);
  });
}

function highlightCard(index: number, scroll: boolean = false) {
  popUps.forEach(p => p.popup.setMap(null));
  activeCardIndex = Math.max(0, Math.min(index, dayPlanItinerary.length - 1));
  const item = dayPlanItinerary[activeCardIndex];
  if (item) {
    item.popup.setMap(map);
    map.panTo(item.position);
    if (scroll) {
      const cards = document.querySelectorAll('.location-card');
      cards.forEach(c => c.classList.remove('active'));
      if (cards[activeCardIndex]) {
        cards[activeCardIndex].classList.add('active');
        cards[activeCardIndex].scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'center' });
      }
    }
  }
}

function drawRoute() {
  polylines.forEach(p => p.setMap(null)); polylines = [];
  const dailyGroups = new Map<number, any[]>();
  dayPlanItinerary.forEach(item => {
    if (!dailyGroups.has(item.day)) dailyGroups.set(item.day, []);
    dailyGroups.get(item.day)!.push(item);
  });
  dailyGroups.forEach((items, day) => {
    const path = items.sort((a,b)=>a.sequence-b.sequence).map(i => i.position);
    polylines.push(new google.maps.Polyline({ path, strokeColor: DAY_COLORS[(day-1)%DAY_COLORS.length], strokeOpacity: 0.8, strokeWeight: 4, map }));
  });
}

function createTimeline() {
  const container = getEl('timeline-content');
  if (!container) return;
  container.innerHTML = `<div style="padding:15px; background:#fff8f6; border-radius:10px; font-size:13px; line-height:1.6; margin-bottom:20px; border:1px solid #ffebe0;">${itinerarySummary.replace(/\n/g, '<br>')}</div>`;
  const sorted = [...dayPlanItinerary].sort((a,b)=>(a.day-b.day)||(a.sequence-b.sequence));
  let curDay = -1;
  sorted.forEach(item => {
    if (item.day !== curDay) {
      curDay = item.day;
      const h = document.createElement('div'); h.className = 'timeline-day-header';
      h.style.color = DAY_COLORS[(curDay-1)%DAY_COLORS.length]; h.innerText = `Day ${curDay}`;
      container.appendChild(h);
    }
    const entry = document.createElement('div'); entry.className = 'timeline-entry';
    entry.innerHTML = `<div class="timeline-time">${item.time}</div><div class="timeline-dot" style="background:${DAY_COLORS[(curDay-1)%DAY_COLORS.length]}"></div><div class="timeline-details"><div class="timeline-title">${item.name}</div><div class="timeline-desc">${item.description}</div></div>`;
    entry.onclick = () => highlightCard(dayPlanItinerary.indexOf(item), true);
    container.appendChild(entry);
  });
}

function renderSocialRecommendations() {
  const list = getEl('social-recs-list'); list.innerHTML = '';
  if (socialRecommendations.length > 0) {
    getEl('social-recs-section').classList.remove('hidden');
    socialRecommendations.forEach(rec => {
      const card = document.createElement('div'); card.style.background = '#f8fafc'; card.style.padding = '12px'; card.style.borderRadius = '10px'; card.style.marginBottom = '10px'; card.style.border = '1px solid var(--border-color)';
      card.innerHTML = `<div style="display:flex; justify-content:space-between; margin-bottom:6px;"><span style="font-weight:900; color:var(--primary);">#${rec.rank}</span><span style="font-size:10px; background:#ddd; padding:2px 6px; border-radius:4px;">${rec.platform}</span></div><div style="font-weight:700; font-size:14px; margin-bottom:4px;">${rec.title}</div><div style="font-size:12px; color:var(--text-muted); line-height:1.4;">${rec.reason}</div>`;
      list.appendChild(card);
    });
  }
}

/**
 * Updates URL state safely without reloading
 */
function safeReplaceState(url: string) {
  try {
    window.history.replaceState({}, '', url);
  } catch (e) {
    console.error('Failed to update URL state:', e);
  }
}

function restart() {
  popUps.forEach(p => p.popup.setMap(null)); polylines.forEach(p => p.setMap(null)); polylines = [];
  dayPlanItinerary.forEach(item => item.marker.setMap(null));
  dayPlanItinerary = []; socialRecommendations = [];
  getEl('card-container').innerHTML = ''; getEl('card-carousel').classList.add('hidden');
  getEl('social-recs-section').classList.add('hidden'); getEl('timeline-container').classList.remove('visible');
  bounds = new google.maps.LatLngBounds(); safeReplaceState(window.location.pathname);
}

function hideTimeline() { getEl('timeline-container').classList.remove('visible'); getEl('reopen-timeline').classList.remove('hidden'); }
function showTimeline() { getEl('timeline-container').classList.add('visible'); getEl('reopen-timeline').classList.add('hidden'); }

function transformSchemaToLowercase(schema: any) {
  if (!schema || typeof schema !== 'object') return schema;
  const newSchema = Array.isArray(schema) ? [...schema] : { ...schema };
  if (newSchema.type) newSchema.type = newSchema.type.toLowerCase();
  if (newSchema.properties) for (const k in newSchema.properties) newSchema.properties[k] = transformSchemaToLowercase(newSchema.properties[k]);
  if (newSchema.items) newSchema.items = transformSchemaToLowercase(newSchema.items);
  return newSchema;
}

/**
 * Encodes current itinerary state into a Base64 string for URL sharing
 */
function encodeStateToUrl(): string | null {
  if (dayPlanItinerary.length === 0) return null;
  const state = {
    plan: dayPlanItinerary.map(i => ({
      name: i.name,
      description: i.description,
      lat: i.lat,
      lng: i.lng,
      time: i.time,
      day: i.day,
      sequence: i.sequence,
      transit_hint: i.transit_hint,
      category: i.category,
      weather_icon: i.weather_icon,
      weather_condition: i.weather_condition,
      temperature: i.temperature
    })),
    summary: itinerarySummary
  };
  try {
    const json = JSON.stringify(state);
    const encoded = btoa(encodeURIComponent(json));
    return `${window.location.origin}${window.location.pathname}?p=${encoded}`;
  } catch (e) {
    console.error("Encoding failed", e);
    return null;
  }
}

/**
 * Decodes itinerary state from URL and restores the view
 */
async function loadPlanFromUrl() {
  const params = new URLSearchParams(window.location.search);
  const p = params.get('p');
  if (!p) return;
  try {
    const decoded = JSON.parse(decodeURIComponent(atob(p)));
    if (decoded.plan && Array.isArray(decoded.plan)) {
      itinerarySummary = decoded.summary || "";
      for (const item of decoded.plan) {
        await setPin(item);
      }
      dayPlanItinerary.sort((a, b) => (a.day - b.day) || (a.sequence - b.sequence));
      createCards();
      if (isPlannerMode) { drawRoute(); createTimeline(); showTimeline(); }
      highlightCard(0, true);
    }
  } catch (e) {
    console.error("Failed to load plan from URL", e);
  }
}

initApp();

