import { GoogleGenAI } from '@google/genai';
import L from 'leaflet';
import 'leaflet.markercluster';
import { locationTool, socialRecommendationTool } from './mcp-tools';

// Application state
let map: L.Map;
let markerCluster: any;
let dayPlanItinerary: any[] = [];
let socialRecommendations: any[] = [];
let itinerarySummary = "";
let polylines: L.Polyline[] = [];
let tdtLayer: L.TileLayer;
let tdtAnnoLayer: L.TileLayer;

// Default Keys
const TDT_DEFAULT_KEY = "97f9870fb795ba80ef201d6edae71d73";
const DAY_COLORS = ['#ff5722', '#2196f3', '#4caf50', '#9c27b0', '#ffeb3b', '#00bcd4', '#795548'];

const getEl = <T extends HTMLElement>(id: string) => document.getElementById(id) as T;

function initApp() {
  // Initialize Leaflet Map - No key required!
  map = L.map('map', {
    center: [39.9042, 116.4074],
    zoom: 12,
    zoomControl: false,
    attributionControl: false
  });

  const savedTdtKey = localStorage.getItem('tdt_api_key') || TDT_DEFAULT_KEY;
  const savedDeepSeekKey = localStorage.getItem('deepseek_api_key') || "";

  (getEl('tdt-key-input') as HTMLInputElement).value = savedTdtKey;
  (getEl('deepseek-key-input') as HTMLInputElement).value = savedDeepSeekKey;

  // Set initial layers (Tianditu)
  switchTDT('tdt_vec', savedTdtKey);

  bindEvents();
  getEl('spinner').classList.add('hidden');
}

function switchTDT(type: string, tk: string) {
  if (tdtLayer) map.removeLayer(tdtLayer);
  if (tdtAnnoLayer) map.removeLayer(tdtAnnoLayer);

  const layer = type === 'tdt_vec' ? 'vec_w' : 'img_w';
  const anno = type === 'tdt_vec' ? 'cva_w' : 'cia_w';

  tdtLayer = L.tileLayer(`https://t{s}.tianditu.gov.cn/${layer}/wmts?SERVICE=WMTS&REQUEST=GetTile&VERSION=1.0.0&LAYER=${layer.split('_')[0]}&STYLE=default&TILEMATRIXSET=w&FORMAT=tiles&TILECOL={x}&TILEROW={y}&TILEMATRIX={z}&tk=${tk}`, {
    subdomains: ['0', '1', '2', '3', '4', '5', '6', '7']
  }).addTo(map);

  tdtAnnoLayer = L.tileLayer(`https://t{s}.tianditu.gov.cn/${anno}/wmts?SERVICE=WMTS&REQUEST=GetTile&VERSION=1.0.0&LAYER=${anno.split('_')[0]}&STYLE=default&TILEMATRIXSET=w&FORMAT=tiles&TILECOL={x}&TILEROW={y}&TILEMATRIX={z}&tk=${tk}`, {
    subdomains: ['0', '1', '2', '3', '4', '5', '6', '7']
  }).addTo(map);
}

function bindEvents() {
  getEl('open-settings').onclick = () => getEl('settings-modal').classList.remove('hidden');
  getEl('close-settings').onclick = () => getEl('settings-modal').classList.add('hidden');

  getEl('save-settings').onclick = () => {
    localStorage.setItem('deepseek_api_key', (getEl('deepseek-key-input') as HTMLInputElement).value.trim());
    localStorage.setItem('tdt_api_key', (getEl('tdt-key-input') as HTMLInputElement).value.trim());
    window.location.reload();
  };

  getEl('toggle-map-type').onclick = (e) => {
    e.stopPropagation();
    getEl('map-type-menu').classList.toggle('hidden');
  };

  document.querySelectorAll('.menu-item').forEach(item => {
    (item as HTMLElement).onclick = function() {
      const type = (this as HTMLElement).getAttribute('data-type')!;
      document.querySelectorAll('.menu-item').forEach(i => i.classList.remove('active'));
      (this as HTMLElement).classList.add('active');
      switchTDT(type, localStorage.getItem('tdt_api_key') || TDT_DEFAULT_KEY);
    };
  });

  getEl('planner-mode-toggle').onchange = (e) => {
    const isPlanner = (e.target as HTMLInputElement).checked;
    getEl('mode-text').innerText = isPlanner ? "行程规划模式" : "景点发现模式";
    getEl('preference-toggle-group').classList.toggle('hidden', !isPlanner);
    restart();
  };

  getEl('toggle-search-ui').onclick = () => {
    getEl('sidebar-left').classList.toggle('ui-hidden');
    setTimeout(() => map.invalidateSize(), 400);
  };

  getEl('generate').onclick = handleRequest;
  getEl('reset').onclick = restart;
  getEl('close-timeline').onclick = () => getEl('timeline-container').classList.remove('visible');
  getEl('close-share').onclick = () => getEl('share-modal').classList.add('hidden');
}

async function handleRequest() {
  const userInput = (getEl('prompt-input') as HTMLTextAreaElement).value.trim();
  if (!userInput) return;

  restart();
  getEl('spinner').classList.remove('hidden');

  try {
    const model = (getEl('model-selector') as HTMLSelectElement).value;
    if (model.startsWith('deepseek')) {
      await handleDeepSeekRequest(model, userInput);
    } else {
      await handleGeminiRequest(model, userInput);
    }

    renderAll();
  } catch (e: any) {
    const errEl = getEl('error-message');
    errEl.innerText = "⚠️ " + (e.message || "请求失败");
    errEl.classList.remove('hidden');
  } finally {
    getEl('spinner').classList.add('hidden');
  }
}

async function handleGeminiRequest(model: string, input: string) {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const response = await ai.models.generateContent({
    model: model,
    contents: [{ role: 'user', parts: [{ text: input }] }],
    config: {
      systemInstruction: `你是一位顶级旅游专家。必须整合趋势并为每一处景点调用 'location' 工具打点。分类：SIGHT, FOOD, HOTEL, TRANSIT。`,
      tools: [{ functionDeclarations: [locationTool, socialRecommendationTool] }],
    },
  });

  const functionCalls = (response.functionCalls || []) as any[];
  for (const fc of functionCalls) {
    if (fc.name === 'location') addItineraryItem(fc.args);
    if (fc.name === 'get_social_recommendations') socialRecommendations = fc.args.recommendations || [];
  }
  itinerarySummary = response.text || "";
}

async function handleDeepSeekRequest(model: string, input: string) {
  const apiKey = localStorage.getItem('deepseek_api_key');
  const response = await fetch('https://api.deepseek.com/chat/completions', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiKey}` },
    body: JSON.stringify({ 
      model: model, 
      messages: [{ role: 'user', content: input }],
      tools: [{ type: "function", function: { name: "location", parameters: transformSchema(locationTool.parameters) } }] 
    })
  });
  const data = await response.json();
  const message = data.choices[0].message;
  itinerarySummary = message.content || "";
  if (message.tool_calls) {
    message.tool_calls.forEach((tc: any) => addItineraryItem(JSON.parse(tc.function.arguments)));
  }
}

function addItineraryItem(args: any) {
  dayPlanItinerary.push(args);
}

function renderAll() {
  dayPlanItinerary.sort((a, b) => (a.day - b.day) || (a.sequence - b.sequence));

  const points: L.LatLng[] = [];
  dayPlanItinerary.forEach((item, idx) => {
    const latlng = L.latLng(parseFloat(item.lat), parseFloat(item.lng));
    points.push(latlng);

    const color = DAY_COLORS[(item.day - 1) % DAY_COLORS.length];
    const marker = L.circleMarker(latlng, {
      radius: 10,
      fillColor: color,
      color: "#fff",
      weight: 2,
      fillOpacity: 1
    }).addTo(map);

    marker.bindPopup(`
      <div style="font-family:sans-serif;">
        <b style="color:${color}">${item.name}</b><br>
        <span style="font-size:12px;">${item.weather_icon} ${item.weather_condition} ${item.temperature}</span><br>
        <p style="font-size:11px; margin-top:5px;">${item.description}</p>
      </div>
    `);

    item._marker = marker;
  });

  if (points.length > 0) map.fitBounds(L.latLngBounds(points), { padding: [50, 50] });

  createCards();
  createTimeline();
  renderSocialRecs();

  const isPlanner = (getEl('planner-mode-toggle') as HTMLInputElement).checked;
  if (isPlanner) {
    drawRoutes();
    getEl('timeline-container').classList.add('visible');
  }
}

function createCards() {
  const container = getEl('card-container');
  container.innerHTML = '';
  getEl('card-carousel').classList.remove('hidden');
  dayPlanItinerary.forEach((loc, index) => {
    const card = document.createElement('div');
    card.className = `location-card`;
    card.innerHTML = `<div class="card-day-mini" style="background:${DAY_COLORS[(loc.day-1)%DAY_COLORS.length]}">D${loc.day}</div><div class="card-title-mini">${loc.name}</div>`;
    card.onclick = () => {
      document.querySelectorAll('.location-card').forEach(c => c.classList.remove('active'));
      card.classList.add('active');
      map.setView(loc._marker.getLatLng(), 15);
      loc._marker.openPopup();
    };
    container.appendChild(card);
  });
}

function createTimeline() {
  const container = getEl('timeline-content');
  container.innerHTML = `<div style="padding:15px; background:#fff8f6; border-radius:10px; font-size:13px; margin-bottom:20px;">${itinerarySummary.replace(/\n/g, '<br>')}</div>`;

  let curDay = -1;
  dayPlanItinerary.forEach(item => {
    if (item.day !== curDay) {
      curDay = item.day;
      const h = document.createElement('div'); h.className = 'timeline-day-header';
      h.style.color = DAY_COLORS[(curDay-1)%DAY_COLORS.length]; h.innerText = `Day ${curDay}`;
      container.appendChild(h);
    }
    const entry = document.createElement('div'); entry.className = 'timeline-entry';
    entry.innerHTML = `<div class="timeline-time">${item.time}</div><div class="timeline-dot" style="background:${DAY_COLORS[(curDay-1)%DAY_COLORS.length]}"></div><div class="timeline-details"><div class="timeline-title">${item.name}</div><div class="timeline-desc">${item.description}</div></div>`;
    entry.onclick = () => {
      map.setView(item._marker.getLatLng(), 15);
      item._marker.openPopup();
    };
    container.appendChild(entry);
  });
}

function drawRoutes() {
  const dailyPath = new Map<number, L.LatLng[]>();
  dayPlanItinerary.forEach(item => {
    if (!dailyPath.has(item.day)) dailyPath.set(item.day, []);
    dailyPath.get(item.day)!.push(L.latLng(item.lat, item.lng));
  });
  dailyPath.forEach((path, day) => {
    const poly = L.polyline(path, { color: DAY_COLORS[(day-1)%DAY_COLORS.length], weight: 4, opacity: 0.6 }).addTo(map);
    polylines.push(poly);
  });
}

function renderSocialRecs() {
  const list = getEl('social-recs-list'); list.innerHTML = '';
  if (socialRecommendations.length > 0) {
    getEl('social-recs-section').classList.remove('hidden');
    socialRecommendations.forEach(rec => {
      const card = document.createElement('div'); 
      card.style.cssText = 'background:#f8fafc; padding:12px; border-radius:10px; margin-bottom:10px; border:1px solid #e2e8f0;';
      card.innerHTML = `<div style="display:flex; justify-content:space-between; margin-bottom:4px;"><span style="color:var(--primary); font-weight:900;">#${rec.rank}</span><span style="font-size:10px; background:#ddd; padding:2px 5px; border-radius:3px;">${rec.platform}</span></div><div style="font-weight:700;">${rec.title}</div><div style="font-size:12px; color:#64748b;">${rec.reason}</div>`;
      list.appendChild(card);
    });
  }
}

function restart() {
  dayPlanItinerary.forEach(item => { if (item._marker) map.removeLayer(item._marker); });
  polylines.forEach(p => map.removeLayer(p));
  dayPlanItinerary = []; socialRecommendations = []; polylines = [];
  getEl('card-container').innerHTML = '';
  getEl('card-carousel').classList.add('hidden');
  getEl('social-recs-section').classList.add('hidden');
  getEl('timeline-container').classList.remove('visible');
}

function transformSchema(s: any) {
  const n = JSON.parse(JSON.stringify(s));
  if (n.type) n.type = n.type.toLowerCase();
  if (n.properties) for (const k in n.properties) n.properties[k] = transformSchema(n.properties[k]);
  if (n.items) n.items = transformSchema(n.items);
  return n;
}

initApp();

@import url(https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css);

:root {
  --primary: #ff5722;
  --primary-hover: #f4511e;
  --bg-light: #f8fafc;
  --border-color: #e2e8f0;
  --text-main: #0f172a;
  --text-muted: #64748b;
  --radius: 14px;
  --sidebar-w: 340px;
  --timeline-w: 400px;
  --shadow-lg: 0 20px 25px -5px rgba(0, 0, 0, 0.1);
}

* { box-sizing: border-box; padding: 0; margin: 0; font-family: 'PingFang SC', system-ui, sans-serif; }

html, body { height: 100%; width: 100%; overflow: hidden; background: var(--bg-light); color: var(--text-main); }

.hidden { display: none !important; }

/* App Layout */
.app-shell { display: flex; height: 100vh; width: 100vw; position: relative; }

/* Sidebar - Left */
.sidebar-left {
  display: flex;
  flex-direction: column;
  background: white;
  z-index: 1001; /* Higher than leaflet */
  width: var(--sidebar-w);
  border-right: 1px solid var(--border-color);
  flex-shrink: 0;
  transition: transform 0.4s ease;
}
.sidebar-left.ui-hidden { transform: translateX(-100%); position: absolute; }

.sidebar-header {
  padding: 16px 20px;
  border-bottom: 1px solid var(--border-color);
  display: flex;
  justify-content: space-between;
  align-items: center;
  min-height: 64px;
}

.brand { display: flex; align-items: center; gap: 12px; font-weight: 800; font-size: 1.2rem; color: var(--primary); }

.sidebar-scroll {
  flex: 1;
  overflow-y: auto;
  padding: 24px 20px;
}

/* Sidebar - Right */
.sidebar-right {
  display: flex;
  flex-direction: column;
  background: white;
  z-index: 1001;
  width: var(--timeline-w);
  border-left: 1px solid var(--border-color);
  position: absolute;
  right: 0; top: 0; height: 100%;
  transform: translateX(100%);
  transition: transform 0.4s ease;
  box-shadow: -10px 0 30px rgba(0,0,0,0.05);
}
.sidebar-right.visible { transform: translateX(0); }

/* Form Elements */
.control-section { margin-bottom: 24px; }
.section-label { 
  display: block; font-size: 0.8rem; text-transform: uppercase; 
  letter-spacing: 0.05em; color: var(--text-muted); margin-bottom: 10px; font-weight: 700;
}
.form-select {
  width: 100%; padding: 12px; border-radius: var(--radius); border: 1px solid var(--border-color);
  background: white; font-size: 14px; outline: none;
}
#prompt-input {
  width: 100%; min-height: 120px; padding: 16px; border: 1px solid var(--border-color);
  border-radius: var(--radius); font-size: 14px; line-height: 1.6; resize: none;
  background: #fff; outline: none;
}
.primary-action-btn {
  background: var(--primary); color: white; border: none; padding: 16px; width: 100%;
  border-radius: var(--radius); font-weight: 700; cursor: pointer; margin-top: 10px;
}

/* Map Canvas */
.main-canvas { flex: 1; position: relative; background: #eaeff2; z-index: 1; }
#map { height: 100%; width: 100%; z-index: 10; }

.map-tool-stack { position: absolute; top: 24px; left: 24px; display: flex; flex-direction: column; gap: 12px; z-index: 500; }
.map-tool-btn {
  width: 48px; height: 48px; background: white; border: 1px solid var(--border-color);
  border-radius: 12px; display: flex; align-items: center; justify-content: center;
  font-size: 20px; cursor: pointer; box-shadow: 0 4px 10px rgba(0,0,0,0.1);
}

.map-type-menu {
  position: absolute; left: 60px; top: 0; background: white; border-radius: 12px;
  box-shadow: 0 4px 20px rgba(0,0,0,0.1); width: 150px; padding: 10px;
}
.menu-item {
  width: 100%; padding: 8px; border: none; background: transparent; text-align: left;
  border-radius: 6px; cursor: pointer; font-size: 13px;
}
.menu-item.active { color: var(--primary); font-weight: 700; background: #fff5f2; }

/* Timeline UI */
.timeline-day-header { font-size: 1.2rem; font-weight: 900; margin: 24px 0 16px; border-bottom: 2px solid currentColor; }
.timeline-entry { display: flex; gap: 15px; padding: 10px; cursor: pointer; border-radius: 8px; }
.timeline-entry:hover { background: #f8fafc; }
.timeline-time { width: 50px; font-size: 12px; font-weight: 700; color: var(--text-muted); }
.timeline-dot { width: 10px; height: 10px; border-radius: 50%; margin-top: 6px; position: relative; }
.timeline-details { flex: 1; }
.timeline-title { font-weight: 800; font-size: 14px; margin-bottom: 4px; }
.timeline-desc { font-size: 13px; color: var(--text-muted); }

/* Switch UI */
.switch { position: relative; display: inline-block; width: 44px; height: 24px; }
.switch input { opacity: 0; width: 0; height: 0; }
.slider { position: absolute; cursor: pointer; top: 0; left: 0; right: 0; bottom: 0; background-color: #ccc; border-radius: 34px; transition: .4s; }
.slider:before { position: absolute; content: ""; height: 18px; width: 18px; left: 3px; bottom: 3px; background-color: white; border-radius: 50%; transition: .4s; }
input:checked + .slider { background-color: var(--primary); }
input:checked + .slider:before { transform: translateX(20px); }

/* Carousel UI */
.card-carousel { position: absolute; bottom: 20px; left: 50%; transform: translateX(-50%); z-index: 400; width: auto; max-width: 90%; pointer-events: none; }
.card-container {
  display: flex; gap: 10px; padding: 10px 20px; background: rgba(255,255,255,0.9);
  backdrop-filter: blur(5px); border-radius: 100px; box-shadow: var(--shadow-lg);
  overflow-x: auto; scrollbar-width: none; pointer-events: auto;
}
.location-card { flex-shrink: 0; padding: 8px 20px; background: white; border-radius: 50px; border: 1px solid #ddd; cursor: pointer; display: flex; align-items: center; gap: 8px; font-size: 13px; }
.location-card.active { border-color: var(--primary); background: #fff5f2; color: var(--primary); font-weight: 700; }

/* Modal UI */
.modal-overlay { position: fixed; inset: 0; background: rgba(0,0,0,0.5); z-index: 2000; display: flex; align-items: center; justify-content: center; padding: 20px; }
.modal-content { background: white; border-radius: 20px; width: 100%; max-width: 450px; overflow: hidden; }
.modal-header { padding: 15px 20px; border-bottom: 1px solid #eee; display: flex; justify-content: space-between; align-items: center; }
.modal-body { padding: 20px; display: flex; flex-direction: column; gap: 15px; }
.input-group { display: flex; flex-direction: column; gap: 5px; }
.input-group input { padding: 10px; border: 1px solid #ddd; border-radius: 8px; }
.primary-btn-full { padding: 12px; background: var(--primary); color: white; border: none; border-radius: 10px; font-weight: 700; cursor: pointer; }

/* Spinner */
.spinner { position: fixed; inset: 0; background: rgba(255,255,255,0.9); z-index: 3000; display: flex; flex-direction: column; align-items: center; justify-content: center; }
.loading-animation { width: 40px; height: 40px; border: 4px solid #eee; border-top: 4px solid var(--primary); border-radius: 50%; animation: spin 1s infinite linear; margin-bottom: 10px; }
@keyframes spin { to { transform: rotate(360deg); } }

