async function handleDeepSeekRequest(model: string, input: string, pref: string) {
  const apiKey = localStorage.getItem('deepseek_api_key');
  if (!apiKey) throw new Error("请先在设置中配置 DeepSeek API Key");

  const systemPrompt = `你是一位世界顶级的旅游规划专家。
  1. 必须优先调用 'get_social_recommendations' 获取打卡趋势。
  2. 针对行程中的每一个地点，必须调用 'location' 进行精准标注。
  3. 严禁在 lat 或 lng 中返回 "未知"、"NaN" 或空值。必须返回真实的十进制地理坐标字符串。
  4. 回复语言为中文。`;

  const response = await fetch('https://api.deepseek.com/chat/completions', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiKey}` },
    body: JSON.stringify({ 
      model: model, 
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: `我的需求是：${input}。我更倾向于${pref === 'budget' ? '节省开支的经济游' : '时间充裕的深度体验'}。` }
      ],
      tools: [
        { type: "function", function: { name: "location", parameters: transformSchema(locationTool.parameters) } },
        { type: "function", function: { name: "get_social_recommendations", parameters: transformSchema(socialRecommendationTool.parameters) } }
      ],
      tool_choice: "auto"
    })
  });

  const data = await response.json();
  if (data.error) throw new Error(data.error.message);

  const message = data.choices[0].message;
  itinerarySummary = message.content || "行程规划完成";

  if (message.tool_calls) {
    for (const tc of message.tool_calls) {
      const args = JSON.parse(tc.function.arguments);
      if (tc.function.name === 'location') addValidItem(args);
      if (tc.function.name === 'get_social_recommendations') socialRecommendations = args.recommendations || [];
    }
  }
}

/**
 * 增加合法性校验，防止 NaN 坐标进入数组
 */
function addValidItem(args: any) {
  const lat = parseFloat(args.lat);
  const lng = parseFloat(args.lng);
  if (!isNaN(lat) && !isNaN(lng)) {
    dayPlanItinerary.push(args);
  } else {
    console.warn(`跳过无效坐标地点: ${args.name}`, args);
  }
}

function renderAll() {
  dayPlanItinerary.sort((a, b) => (a.day - b.day) || (a.sequence - b.sequence));

  const points: L.LatLng[] = [];
  dayPlanItinerary.forEach((item) => {
    const lat = parseFloat(item.lat);
    const lng = parseFloat(item.lng);

    // 二次校验，防止渲染崩溃
    if (isNaN(lat) || isNaN(lng)) return;

    const latlng = L.latLng(lat, lng);
    points.push(latlng);

    const color = DAY_COLORS[(item.day - 1) % DAY_COLORS.length];
    const marker = L.circleMarker(latlng, {
      radius: 10, fillColor: color, color: "#fff", weight: 2, fillOpacity: 1
    }).addTo(map);

    marker.bindPopup(`
      <div style="min-width:150px;">
        <b style="color:${color}; font-size:14px;">${item.name}</b><br>
        <span style="font-size:12px;">📍 ${item.weather_condition || '目的地'} ${item.temperature || ''}</span><br>
        <p style="font-size:11px; margin-top:5px; color:#444;">${item.description}</p>
        <p style="font-size:10px; color:var(--primary); margin-top:3px;">🚌 ${item.transit_hint}</p>
      </div>
    `);
    item._marker = marker;
  });

  if (points.length > 0) map.fitBounds(L.latLngBounds(points), { padding: [50, 50] });

  createCards();
  createTimeline();
  renderSocialRecs();

  if ((getEl('planner-mode-toggle') as HTMLInputElement).checked) {
    drawRoutes();
    getEl('timeline-container').classList.add('visible');
  }
}

function createCards() {
  const container = getEl('card-container');
  container.innerHTML = '';
  if (dayPlanItinerary.length === 0) return;
  getEl('card-carousel').classList.remove('hidden');
  dayPlanItinerary.forEach((loc, index) => {
    const card = document.createElement('div');
    card.className = `location-card`;
    card.innerHTML = `<div class="card-day-mini" style="background:${DAY_COLORS[(loc.day-1)%DAY_COLORS.length]}">D${loc.day}</div><div class="card-title-mini">${loc.name}</div>`;
    card.onclick = () => {
      document.querySelectorAll('.location-card').forEach(c => c.classList.remove('active'));
      card.classList.add('active');
      if (loc._marker) {
        map.setView(loc._marker.getLatLng(), 15);
        loc._marker.openPopup();
      }
    };
    container.appendChild(card);
  });
}

function createTimeline() {
  const container = getEl('timeline-content');
  container.innerHTML = `<div style="padding:15px; background:#fff8f6; border-radius:10px; font-size:13px; margin-bottom:20px; border:1px solid #ffebe0;">${itinerarySummary.replace(/\n/g, '<br>')}</div>`;

  let curDay = -1;
  dayPlanItinerary.forEach(item => {
    if (item.day !== curDay) {
      curDay = item.day;
      const h = document.createElement('div'); h.className = 'timeline-day-header';
      h.style.color = DAY_COLORS[(curDay-1)%DAY_COLORS.length]; h.innerText = `Day ${curDay}`;
      container.appendChild(h);
    }
    const entry = document.createElement('div'); entry.className = 'timeline-entry';
    entry.innerHTML = `<div class="timeline-time">${item.time}</div><div class="timeline-dot" style="background:${DAY_COLORS[(curDay-1)%DAY_COLORS.length]}"></div><div class="timeline-details"><div class="timeline-title">${item.name}</div><div class="timeline-desc">${item.description}</div></div>`;
    entry.onclick = () => {
      if (item._marker) {
        map.setView(item._marker.getLatLng(), 15);
        item._marker.openPopup();
      }
    };
    container.appendChild(entry);
  });
}

function drawRoutes() {
  const dailyPath = new Map<number, L.LatLng[]>();
  dayPlanItinerary.forEach(item => {
    const lat = parseFloat(item.lat);
    const lng = parseFloat(item.lng);
    if (!isNaN(lat) && !isNaN(lng)) {
      if (!dailyPath.has(item.day)) dailyPath.set(item.day, []);
      dailyPath.get(item.day)!.push(L.latLng(lat, lng));
    }
  });
  dailyPath.forEach((path, day) => {
    if (path.length > 1) {
      const poly = L.polyline(path, { color: DAY_COLORS[(day-1)%DAY_COLORS.length], weight: 4, opacity: 0.6, dashArray: '5, 10' }).addTo(map);
      polylines.push(poly);
    }
  });
}

function renderSocialRecs() {
  const list = getEl('social-recs-list'); list.innerHTML = '';
  if (socialRecommendations.length > 0) {
    getEl('social-recs-section').classList.remove('hidden');
    socialRecommendations.forEach(rec => {
      const card = document.createElement('div'); 
      card.style.cssText = 'background:#f8fafc; padding:12px; border-radius:10px; margin-bottom:10px; border:1px solid #e2e8f0;';
      card.innerHTML = `<div style="display:flex; justify-content:space-between; margin-bottom:4px;"><span style="color:var(--primary); font-weight:900;">#${rec.rank}</span><span style="font-size:10px; background:#ddd; padding:2px 5px; border-radius:3px;">${rec.platform}</span></div><div style="font-weight:700;">${rec.title}</div><div style="font-size:12px; color:#64748b;">${rec.reason}</div>`;
      list.appendChild(card);
    });
  }
}

async function generatePoster() {
  const btn = getEl('generate-poster-btn');
  btn.innerText = "生成中...";
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const target = dayPlanItinerary[0]?.name || "奇妙旅行";
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: `A stylish, cinematic travel poster for ${target}, minimalist layout, vibrant colors.` }] },
      config: { imageConfig: { aspectRatio: "9:16" } }
    });

    let base64 = "";
    for (const part of response.candidates[0].content.parts) { if (part.inlineData) base64 = part.inlineData.data; }

    const canvas = getEl('poster-canvas') as HTMLCanvasElement;
    const ctx = canvas.getContext('2d')!;
    const img = new Image();
    img.src = `data:image/png;base64,${base64}`;
    img.onload = () => {
      ctx.drawImage(img, 0, 0, 800, 1422);
      ctx.fillStyle = "rgba(0,0,0,0.5)"; ctx.fillRect(0, 1200, 800, 222);
      ctx.fillStyle = "white"; ctx.font = "bold 60px sans-serif"; ctx.textAlign = "center";
      ctx.fillText(target, 400, 1300);
      ctx.font = "30px sans-serif"; ctx.fillText("AI 深度旅行探索", 400, 1360);
      getEl('poster-placeholder').classList.add('hidden');
      getEl('poster-result').classList.remove('hidden');
    };
  } catch (e) {
    btn.innerText = "生成失败，重试";
  }
}

function restart() {
  dayPlanItinerary.forEach(item => { if (item._marker) map.removeLayer(item._marker); });
  polylines.forEach(p => map.removeLayer(p));
  dayPlanItinerary = []; socialRecommendations = []; polylines = [];
  getEl('card-container').innerHTML = '';
  getEl('card-carousel').classList.add('hidden');
  getEl('social-recs-section').classList.add('hidden');
  getEl('timeline-container').classList.remove('visible');
}

function transformSchema(s: any) {
  const n = JSON.parse(JSON.stringify(s));
  if (n.type) n.type = n.type.toLowerCase();
  if (n.properties) for (const k in n.properties) n.properties[k] = transformSchema(n.properties[k]);
  if (n.items) n.items = transformSchema(n.items);
  return n;
}

