}
.form-select:focus { border-color: var(--primary); box-shadow: 0 0 0 3px rgba(255, 87, 34, 0.1); }

/* Main Question Area (Prompt Box) */
.prompt-container {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.textarea-wrapper {
  position: relative;
  background: #fff;
  border: 1.5px solid var(--border-color);
  border-radius: var(--radius);
  transition: all 0.2s;
  overflow: hidden;
  box-shadow: var(--shadow-sm);
}
.textarea-wrapper:focus-within {
  border-color: var(--primary);
  box-shadow: 0 0 0 4px rgba(255, 87, 34, 0.1);
}

#prompt-input {
  width: 100%;
  min-height: 140px;
  padding: 16px;
  border: none;
  font-size: 15px;
  line-height: 1.6;
  resize: none;
  outline: none;
  color: var(--text-main);
  background: transparent;
}

.primary-action-btn {
  background: var(--primary);
  color: white;
  border: none;
  padding: 16px;
  width: 100%;
  border-radius: var(--radius);
  font-weight: 700;
  font-size: 16px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  box-shadow: 0 4px 12px rgba(255, 87, 34, 0.25);
  transition: all 0.2s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}
.primary-action-btn:hover { background: var(--primary-hover); transform: translateY(-1px); }
.primary-action-btn:active { transform: scale(0.98); }

/* Error Handling */
.error-box {
  background: #fef2f2;
  border: 1px solid #fee2e2;
  border-radius: 12px;
  padding: 12px 16px;
  color: #b91c1c;
  font-size: 13px;
  display: flex;
  gap: 10px;
  align-items: flex-start;
  margin-top: 16px;
}

/* Sidebar Right (Timeline) */
.sidebar-right {
  display: flex; flex-direction: column; background: white; z-index: var(--z-ui); width: var(--timeline-w);
  border-left: 1px solid var(--border-color); position: absolute; right: 0; top: 0; height: 100%;
  transform: translateX(100%); transition: transform 0.4s cubic-bezier(0.4, 0, 0.2, 1);
  box-shadow: -10px 0 30px rgba(0,0,0,0.05);
}
.sidebar-right.visible { transform: translateX(0); }

/* Map Canvas */
.main-canvas { flex: 1; position: relative; z-index: var(--z-map); height: 100%; }
#map { height: 100%; width: 100%; }

/* Tools & Menus */
.icon-btn {
  width: 40px; height: 40px; border-radius: 10px; border: 1px solid var(--border-color);
  background: white; display: flex; align-items: center; justify-content: center;
  cursor: pointer; color: var(--text-muted); transition: all 0.2s;
}
.icon-btn:hover { color: var(--primary); border-color: var(--primary); background: #fff5f2; }

/* Modals */
.modal-overlay {
  position: fixed; inset: 0; background: rgba(15, 23, 42, 0.6);
  z-index: var(--z-modal); display: flex; align-items: center; justify-content: center;
  padding: 20px; backdrop-filter: blur(4px); transition: opacity 0.3s;
}
.modal-content {
  background: white; border-radius: 24px; width: 100%; max-width: 460px;
  max-height: 85vh; overflow: hidden; box-shadow: 0 25px 50px -12px rgba(0,0,0,0.25);
  display: flex; flex-direction: column; animation: modalIn 0.3s ease-out;
}
@keyframes modalIn { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }

.modal-header { padding: 20px 24px; border-bottom: 1px solid var(--border-color); display: flex; justify-content: space-between; align-items: center; }
.modal-body { padding: 24px; overflow-y: auto; flex: 1; display: flex; flex-direction: column; gap: 20px; }

/* Mode Toggle Styling */
.mode-toggle-group { display: flex; justify-content: space-between; align-items: center; }
.mode-text { font-size: 14px; font-weight: 700; color: var(--text-main); }

.switch { position: relative; display: inline-block; width: 44px; height: 24px; }
.switch input { opacity: 0; width: 0; height: 0; }
.slider { position: absolute; cursor: pointer; top: 0; left: 0; right: 0; bottom: 0; background-color: #cbd5e1; border-radius: 34px; transition: .3s; }
.slider:before { position: absolute; content: ""; height: 18px; width: 18px; left: 3px; bottom: 3px; background-color: white; border-radius: 50%; transition: .3s; }
input:checked + .slider { background-color: var(--primary); }
input:checked + .slider:before { transform: translateX(20px); }

/* Loader */
.spinner { position: fixed; inset: 0; background: rgba(255,255,255,0.95); z-index: var(--z-spinner); display: flex; flex-direction: column; align-items: center; justify-content: center; backdrop-filter: blur(10px); }
.loading-animation { width: 60px; height: 60px; border: 5px solid #f1f5f9; border-top: 5px solid var(--primary); border-radius: 50%; animation: spin 1s infinite linear; margin-bottom: 24px; }
@keyframes spin { to { transform: rotate(360deg); } }

/* Mobile Adaptation */
@media (max-width: 768px) {
  :root { --sidebar-w: 100%; --timeline-w: 100%; }
  .sidebar-left { position: absolute; left: 0; top: 0; height: 100%; transform: translateX(0); z-index: 1010; }
  .sidebar-left.ui-hidden { transform: translateX(-100%); }
  .sidebar-right { z-index: 1020; width: 100%; }
  .modal-content { width: 95%; margin: auto; }
  .primary-action-btn { padding: 18px; font-size: 18px; }
}

