    card.innerHTML = `
      <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:8px;">
        <span style="padding:4px 10px; background:${color}; color:white; border-radius:8px; font-size:11px; font-weight:900;">D${item.day} · ${item.time}</span>
        <span style="font-size:18px;">${item.weather_icon || '☀️'}</span>
      </div>
      <h4 style="font-weight:900; color:var(--text-title); margin-bottom:6px;">${item.name}</h4>
      <p style="font-size:13px; opacity:0.8;">${item.description.substring(0, 60)}...</p>
    `;

    card.onclick = () => {
      document.querySelectorAll('.timeline-card').forEach(c => c.classList.remove('active'));
      card.classList.add('active');
      map.flyTo(latlng, 15, { duration: 1.5 });
      marker.openPopup();
    };
    container.appendChild(card);
  });

  // 如果是规划模式，绘制连线
  if ((getEl('planner-mode-toggle') as HTMLInputElement).checked) {
    drawRoutes();
  }

  if (points.length > 0) map.fitBounds(L.latLngBounds(points), { padding: [100, 100] });
}

function drawRoutes() {
  const dailyPath = new Map<number, L.LatLng[]>();
  dayPlanItinerary.forEach(item => {
    if (!dailyPath.has(item.day)) dailyPath.set(item.day, []);
    dailyPath.get(item.day)!.push(L.latLng(parseFloat(item.lat), parseFloat(item.lng)));
  });

  dailyPath.forEach((path, day) => {
    if (path.length > 1) {
      const poly = L.polyline(path, {
        color: DAY_COLORS[(day-1) % DAY_COLORS.length],
        weight: 4,
        opacity: 0.6,
        dashArray: '8, 12'
      }).addTo(map);
      polylines.push(poly);
    }
  });
}

function restart() {
  map.eachLayer(layer => { 
    if (layer instanceof L.CircleMarker || layer instanceof L.Polyline) map.removeLayer(layer); 
  });
  dayPlanItinerary = [];
  socialRecommendations = [];
  polylines = [];
  getEl('timeline-content').innerHTML = '';
  getEl('hud-toggle-itinerary').classList.remove('pulse');
}

function renderHistoryList() {
  const container = getEl('history-list');
  container.innerHTML = `<div style="text-align:center; padding:40px; opacity:0.5;">暂无本地缓存方案</div>`;
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initApp);
} else {
  initApp();
}

@import url(https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css);

:root {
  --primary: #ff5722;
  --primary-glow: rgba(255, 87, 34, 0.2);
  --bg-app: #f8fafc;
  --bg-card: rgba(255, 255, 255, 0.92);
  --glass: saturate(180%) blur(25px);
  --text-title: #0f172a;
  --text-body: #475569;
  --border-light: rgba(226, 232, 240, 0.8);
  --radius-xl: 28px;
  --radius-lg: 18px;
  --shadow-premium: 0 20px 25px -5px rgba(0, 0, 0, 0.05), 0 8px 10px -6px rgba(0, 0, 0, 0.05);
  --sidebar-w: 400px;
}

* { box-sizing: border-box; margin: 0; padding: 0; font-family: 'Inter', 'PingFang SC', system-ui, -apple-system, sans-serif; }

body { height: 100vh; width: 100vw; overflow: hidden; background: var(--bg-app); color: var(--text-body); }

@keyframes slideDown {
  from { opacity: 0; transform: translateY(-10px); }
  to { opacity: 1; transform: translateY(0); }
}

/* App Layout */
.app-shell { display: flex; height: 100%; width: 100%; position: relative; }

/* Map */
.main-canvas { flex: 1; position: relative; z-index: 1; height: 100%; background: #e5e7eb; }
#map { height: 100%; width: 100%; }

/* Sidebar Left (Control Console) */
.sidebar-left {
  position: absolute; left: 24px; top: 24px; bottom: 24px;
  width: var(--sidebar-w); z-index: 100;
  background: var(--bg-card); backdrop-filter: var(--glass);
  border-radius: var(--radius-xl); border: 1px solid var(--border-light);
  box-shadow: var(--shadow-premium);
  display: flex; flex-direction: column;
  transition: transform 0.6s cubic-bezier(0.34, 1.56, 0.64, 1), opacity 0.4s;
}
.sidebar-left.ui-hidden { transform: translateX(calc(-100% - 48px)); opacity: 0; pointer-events: none; }

.sidebar-header {
  padding: 28px 24px; border-bottom: 1px solid var(--border-light);
  display: flex; justify-content: space-between; align-items: center;
}
.brand { display: flex; align-items: center; gap: 14px; font-weight: 900; color: var(--primary); font-size: 1.5rem; letter-spacing: -0.5px; }

.sidebar-scroll { flex: 1; overflow-y: auto; padding: 24px; scrollbar-width: none; }
.sidebar-scroll::-webkit-scrollbar { display: none; }

/* Prompt Box */
.prompt-box-v3 {
  background: white; border-radius: var(--radius-lg); border: 1px solid var(--border-light);
  box-shadow: 0 4px 6px -1px rgba(0,0,0,0.01); transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  display: flex; flex-direction: column; overflow: hidden;
}
.prompt-box-v3:focus-within { border-color: var(--primary); box-shadow: 0 0 0 5px var(--primary-glow); transform: translateY(-2px); }

#prompt-input {
  width: 100%; border: none; padding: 20px; font-size: 16px; min-height: 160px;
  resize: none; outline: none; line-height: 1.6; color: var(--text-title);
}

.action-bar { padding: 12px 16px 16px; display: flex; justify-content: flex-end; align-items: center; gap: 12px; }

.btn-generate {
  background: var(--primary); color: white; border: none; padding: 14px 28px;
  border-radius: 14px; font-weight: 800; cursor: pointer; display: flex; align-items: center; gap: 10px;
  box-shadow: 0 10px 15px -3px rgba(255, 87, 34, 0.3); transition: all 0.3s;
}
.btn-generate:hover { transform: translateY(-2px) scale(1.02); filter: brightness(1.1); }
.btn-generate:active { transform: scale(0.98); }

/* Switch Style */
.switch { position: relative; display: inline-block; width: 44px; height: 24px; }
.switch input { opacity: 0; width: 0; height: 0; }
.slider { position: absolute; cursor: pointer; top: 0; left: 0; right: 0; bottom: 0; background-color: #cbd5e1; border-radius: 24px; transition: .3s; }
.slider:before { position: absolute; content: ""; height: 18px; width: 18px; left: 3px; bottom: 3px; background-color: white; border-radius: 50%; transition: .3s; }
input:checked + .slider { background-color: var(--primary); }
input:checked + .slider:before { transform: translateX(20px); }

/* HUD Controls */
.hud-controls {
  position: absolute; right: 24px; top: 24px; display: flex; flex-direction: column; gap: 16px; z-index: 500;
}
.hud-btn {
  width: 56px; height: 56px; background: var(--bg-card); backdrop-filter: var(--glass);
  border: 1px solid var(--border-light); border-radius: 20px;
  display: flex; align-items: center; justify-content: center; font-size: 22px;
  cursor: pointer; box-shadow: var(--shadow-premium); color: var(--text-title);
  transition: all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
}
.hud-btn:hover { transform: scale(1.1); color: var(--primary); border-color: var(--primary); }
.hud-btn.active { background: var(--primary); color: white; border-color: var(--primary); }
.hud-btn.pulse { animation: hudPulse 2s infinite; }

@keyframes hudPulse {
  0% { box-shadow: 0 0 0 0 rgba(255, 87, 34, 0.4); }
  70% { box-shadow: 0 0 0 15px rgba(255, 87, 34, 0); }
  100% { box-shadow: 0 0 0 0 rgba(255, 87, 34, 0); }
}

/* Itinerary Drawer */
.sidebar-right {
  position: absolute; right: 24px; top: 100px; bottom: 24px;
  width: 440px; z-index: 400;
  background: var(--bg-card); backdrop-filter: var(--glass);
  border-radius: var(--radius-xl); border: 1px solid var(--border-light);
  box-shadow: var(--shadow-premium);
  display: flex; flex-direction: column;
  transform: translateX(calc(100% + 48px));
  transition: all 0.6s cubic-bezier(0.34, 1.56, 0.64, 1);
}
.sidebar-right.visible { transform: translateX(0); }

/* Loader Overlay */
.spinner-v2 {
  position: fixed; inset: 0; z-index: 3000;
  background: rgba(248, 250, 252, 0.95); backdrop-filter: blur(10px);
  display: none; flex-direction: column; align-items: center; justify-content: center;
}
.spinner-v2.active { display: flex; }

.loader {
  width: 64px; height: 64px; border: 5px solid var(--primary-glow); border-top: 5px solid var(--primary);
  border-radius: 50%; animation: spin 0.8s infinite cubic-bezier(0.6, 0.2, 0.4, 0.8);
}
@keyframes spin { to { transform: rotate(360deg); } }

/* Modals */
.modal-overlay {
  position: fixed; inset: 0; background: rgba(15,23,42,0.4); backdrop-filter: blur(10px);
  z-index: 2000; display: none; align-items: center; justify-content: center;
}
.modal-overlay.active { display: flex; }
.modal-content {
  background: white; border-radius: 36px; width: 100%; max-width: 520px;
  padding: 40px; box-shadow: 0 30px 60px -12px rgba(0,0,0,0.2);
  animation: modalEnter 0.5s cubic-bezier(0.34, 1.56, 0.64, 1);
}
@keyframes modalEnter { from { opacity: 0; transform: scale(0.9) translateY(40px); } to { opacity: 1; transform: scale(1) translateY(0); } }

.settings-group { margin-bottom: 24px; }
.settings-group label { display: block; font-weight: 800; margin-bottom: 10px; font-size: 14px; color: var(--text-title); }
.settings-group input, .settings-group select {
  width: 100%; padding: 16px; border: 1.5px solid #e2e8f0; border-radius: 16px; outline: none; transition: 0.2s;
  font-size: 15px; background: #f8fafc;
}
.settings-group input:focus { border-color: var(--primary); background: white; }

/* Timeline Entries */
.timeline-card {
  background: white; padding: 20px; border-radius: 20px;
  border: 1px solid var(--border-light); margin-bottom: 16px; transition: all 0.3s;
  cursor: pointer; position: relative;
}
.timeline-card:hover { transform: translateX(8px); border-color: var(--primary); box-shadow: 0 10px 15px -3px rgba(0,0,0,0.04); }
.timeline-card.active { border-left: 6px solid var(--primary); background: #fff9f8; }

.hidden { display: none !important; }

/* Responsive Mobile */
@media (max-width: 768px) {
  .sidebar-left { left: 12px; right: 12px; width: auto; bottom: auto; top: 12px; }
  .sidebar-right { left: 12px; right: 12px; top: 12px; width: auto; bottom: 80px; z-index: 600; }
  .hud-controls { right: 12px; top: auto; bottom: 24px; flex-direction: row; width: calc(100% - 24px); justify-content: space-around; }
  .hud-btn { width: 50px; height: 50px; border-radius: 15px; }
  .modal-content { width: 92%; padding: 24px; border-radius: 24px; }
}

