/**
 * 鉴权逻辑
 */
function checkAuth() {
  const session = localStorage.getItem(AUTH_KEY);
  if (session) {
    getEl('login-overlay').classList.add('hidden');
    getEl('main-app').classList.remove('blur-content');
  } else {
    getEl('login-overlay').classList.remove('hidden');
    getEl('main-app').classList.add('blur-content');
  }
}

function bindAuthEvents() {
  // Tab 切换
  getEl('tab-phone').onclick = () => {
    getEl('tab-phone').classList.add('active');
    getEl('tab-wechat').classList.remove('active');
    getEl('panel-phone').classList.remove('hidden');
    getEl('panel-wechat').classList.add('hidden');
  };

  getEl('tab-wechat').onclick = async () => {
    getEl('tab-wechat').classList.add('active');
    getEl('tab-phone').classList.remove('active');
    getEl('panel-wechat').classList.remove('hidden');
    getEl('panel-phone').classList.add('hidden');

    // 模拟微信扫码自动轮询登录
    const result: any = await api.checkWechatAuth();
    getEl('qr-mask').classList.remove('hidden');
    setTimeout(() => {
      loginSuccess(result);
    }, 1000);
  };

  // 手机登录
  getEl('get-code-btn').onclick = async () => {
    const phone = (getEl('phone-input') as HTMLInputElement).value;
    if (!/^1[3-9]\d{9}$/.test(phone)) return alert("请输入正确手机号");

    // Fix: Explicitly cast to HTMLButtonElement to access 'disabled' property
    const btn = getEl<HTMLButtonElement>('get-code-btn');
    btn.innerText = "已发送";
    btn.disabled = true;
    await api.sendCode(phone);
  };

  getEl('phone-login-btn').onclick = async () => {
    const phone = (getEl('phone-input') as HTMLInputElement).value;
    const code = (getEl('code-input') as HTMLInputElement).value;
    if (!phone || !code) return alert("请补全信息");

    getEl('phone-login-btn').innerText = "登录中...";
    const result: any = await api.loginWithPhone(phone, code);
    loginSuccess(result);
  };

  getEl('logout-btn').onclick = () => {
    localStorage.removeItem(AUTH_KEY);
    window.location.reload();
  };
}

function loginSuccess(session: any) {
  localStorage.setItem(AUTH_KEY, JSON.stringify(session));
  getEl('login-overlay').classList.add('fade-out');
  setTimeout(() => {
    getEl('login-overlay').classList.add('hidden');
    getEl('main-app').classList.remove('blur-content');
  }, 500);
}

// 其余业务代码逻辑保持一致 (bindHUD, bindEvents, handleRequest, renderAll, etc...)
