.login-btn:hover { transform: translateY(-1px); }

/* QR Code Section */
.qr-container { padding: 10px 0; }
#qr-code-box {
  width: 180px;
  height: 180px;
  margin: 0 auto 16px;
  border: 1px solid #e2e8f0;
