  padding: 14px;
  border-radius: 16px;
  border: 1px solid #f1f5f9;
  margin-bottom: 8px;
}
.social-item span { display: inline-block; font-size: 10px; padding: 2px 6px; background: #000; color: white; border-radius: 4px; margin-right: 6px; }
.social-item b { font-size: 13px; }
.social-item p { font-size: 12px; color: #64748b; margin-top: 4px; }

/* Toast Notification */
.toast-container {
  position: fixed;
  top: 20px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 6000;
  pointer-events: none;
}

.toast {
  background: rgba(0, 0, 0, 0.8);
  color: white;
  padding: 10px 20px;
  border-radius: 20px;
  font-size: 14px;
  margin-bottom: 10px;
  opacity: 0;
  transform: translateY(-20px);
  transition: 0.3s;
}

.toast.show {
  opacity: 1;
  transform: translateY(0);
}

