@import url(https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css);

/* --- Global Reset & Variables --- */
:root {
  --primary: #007AFF; /* iOS Blue */
  --primary-glow: rgba(0, 122, 255, 0.3);
  --danger: #FF3B30;
  --bg-app: #F2F2F7;
  --bg-card: rgba(255, 255, 255, 0.85);
  --glass: saturate(180%) blur(20px);
  --text-title: #000000;
  --text-body: #3C3C43;
  --border-color: rgba(60, 60, 67, 0.1);
  --radius-l: 22px;
  --radius-m: 14px;
}

* { box-sizing: border-box; margin: 0; padding: 0; -webkit-tap-highlight-color: transparent; }

/* 关键修复：强制全屏高度，防止 flex 布局塌陷导致地图不显示 */
html, body { 
  width: 100%; 
  height: 100%; 
  overflow: hidden; 
}

body { 
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Helvetica Neue", Arial, sans-serif; 
  background: var(--bg-app); 
  color: var(--text-body); 
}

/* --- App Shell --- */
.app-shell {
  width: 100%; height: 100%; position: relative;
  display: flex; flex-direction: column;
}
.app-shell.blur-content { filter: blur(20px); pointer-events: none; }

.main-canvas { flex: 1; position: relative; z-index: 0; }
#map { width: 100%; height: 100%; background: #e0e0e0; /* Fallback color */ }

/* --- Glassmorphism Utilities --- */
.glass-panel {
  background: rgba(255, 255, 255, 0.75);
  backdrop-filter: var(--glass);
  -webkit-backdrop-filter: var(--glass);
  border: 1px solid rgba(255, 255, 255, 0.4);
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.05);
}

/* --- Top Bar --- */
.top-bar {
  position: absolute;
  top: 16px; left: 16px; right: 16px;
  height: 56px;
  border-radius: 28px;
  z-index: 100;
  display: flex;
  align-items: center;
  padding: 0 6px 0 20px;
  justify-content: space-between;
  max-width: 600px;
  margin: 0 auto; /* Center on desktop */
}

.top-search-trigger {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 10px;
  color: #8E8E93;
  font-size: 16px;
  cursor: pointer;
}

.user-avatar-mini {
  width: 44px; height: 44px;
  border-radius: 50%;
  overflow: hidden;
  border: 2px solid white;
  cursor: pointer;
  box-shadow: 0 2px 8px rgba(0,0,0,0.1);
}
.user-avatar-mini img { width: 100%; height: 100%; object-fit: cover; }

/* --- Bottom Dock --- */
.bottom-dock {
  position: absolute;
  bottom: 24px;
  left: 20px; right: 20px;
  height: 80px;
  border-radius: 30px;
  z-index: 1000;
  display: flex;
  justify-content: space-around;
  align-items: center;
  padding-bottom: 5px; /* Visual balance */
  max-width: 500px;
  margin: 0 auto;
}

.dock-item {
  background: none; border: none;
  display: flex; flex-direction: column; align-items: center; gap: 4px;
  color: #8E8E93;
  font-size: 10px; font-weight: 500;
  cursor: pointer;
  transition: all 0.2s;
  width: 60px;
}
.dock-item i { font-size: 22px; margin-bottom: 2px; transition: transform 0.2s; }
.dock-item.active { color: var(--primary); }
.dock-item.active i { transform: translateY(-2px); }
.dock-item:active i { transform: scale(0.9); }

/* --- Sheets (Panels) --- */
.sheet-panel {
  position: absolute;
  z-index: 900;
  background: #F2F2F7;
  display: flex; flex-direction: column;
  transition: transform 0.4s cubic-bezier(0.32, 0.72, 0, 1);
  box-shadow: 0 -10px 40px rgba(0,0,0,0.1);
}

/* Mobile: Bottom Sheet style */
@media (max-width: 768px) {
  .sheet-panel {
    bottom: 0; left: 0; right: 0;
    height: 85vh;
    border-radius: 24px 24px 0 0;
    transform: translateY(110%); /* Hidden */
  }
  .sheet-panel.active { transform: translateY(0); }
  .sheet-handle {
    width: 36px; height: 5px;
    background: #C7C7CC;
    border-radius: 2.5px;
    margin: 12px auto;
  }
}

/* Desktop: Floating Panel style */
@media (min-width: 769px) {
  .sheet-panel {
    top: 80px; bottom: 120px;
    width: 380px;
    border-radius: 24px;
    background: rgba(255, 255, 255, 0.95);
    backdrop-filter: blur(20px);
    transform: translateX(-120%);
    box-shadow: 0 10px 40px rgba(0,0,0,0.1);
  }
  #sheet-explore { left: 24px; }
  #sheet-plan { right: 24px; transform: translateX(120%); }

  #sheet-explore.active { transform: translateX(0); }
  #sheet-plan.active { transform: translateX(0); }

  .sheet-handle { display: none; }
}

.sheet-header {
  padding: 10px 24px 10px;
  display: flex; justify-content: space-between; align-items: center;
}
