@import url(https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css);

/* --- Global Design Tokens --- */
:root {
  /* Colors */
  --primary: #007AFF;
  --primary-dark: #0062cc;
  --primary-glow: rgba(0, 122, 255, 0.3);
  --danger: #FF3B30;

  /* Backgrounds */
  --bg-app: #F2F2F7;
  --bg-card: rgba(255, 255, 255, 0.95);
  --bg-input: #F2F2F7;

  /* Glass Effects */
  --glass: blur(20px) saturate(180%);

  /* Text */
  --text-title: #1C1C1E;
  --text-body: #3C3C43;
  --text-secondary: #8E8E93;

  /* Shapes */
  --radius-l: 24px;
  --radius-m: 14px;
  --radius-s: 8px;

  /* Shadows */
  --shadow-card: 0 12px 32px rgba(0, 0, 0, 0.08), 0 2px 6px rgba(0, 0, 0, 0.04);
  --shadow-float: 0 8px 20px rgba(0, 0, 0, 0.12);
}

* { box-sizing: border-box; margin: 0; padding: 0; -webkit-tap-highlight-color: transparent; }

/* Fullscreen Layout Fix */
html, body { 
  width: 100%; 
  height: 100%; 
  overflow: hidden; 
  background: var(--bg-app); 
}

body { 
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Helvetica Neue", Arial, sans-serif; 
  color: var(--text-body);
}

/* --- App Shell --- */
.app-shell {
  width: 100%; height: 100%; position: relative;
  display: flex; flex-direction: column;
}
.app-shell.blur-content { filter: blur(12px); pointer-events: none; transition: filter 0.3s; }

.main-canvas { flex: 1; position: relative; z-index: 0; }
#map { width: 100%; height: 100%; background: #E5E5EA; }

/* --- Glass Panels (Unified) --- */
.glass-panel {
  background: rgba(255, 255, 255, 0.85);
  backdrop-filter: var(--glass);
  -webkit-backdrop-filter: var(--glass);
  border: 1px solid rgba(255, 255, 255, 0.4);
  box-shadow: var(--shadow-float);
}

/* --- Top Bar --- */
.top-bar {
  position: absolute;
  top: 16px; left: 16px; right: 16px;
  height: 56px;
  border-radius: 28px;
  z-index: 100;
  display: flex;
  align-items: center;
  padding: 0 8px 0 20px;
  justify-content: space-between;
  max-width: 600px;
  margin: 0 auto;
}

.top-search-trigger {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 12px;
  color: var(--text-secondary);
  font-size: 16px;
  cursor: pointer;
}

.user-avatar-mini {
  width: 40px; height: 40px;
  border-radius: 50%;
  overflow: hidden;
  border: 2px solid white;
  cursor: pointer;
  box-shadow: 0 2px 8px rgba(0,0,0,0.1);
  transition: transform 0.2s;
}
.user-avatar-mini:active { transform: scale(0.95); }
.user-avatar-mini img { width: 100%; height: 100%; object-fit: cover; }

/* --- Bottom Dock --- */
.bottom-dock {
  position: absolute;
  bottom: 30px;
  left: 20px; right: 20px;
  height: 72px;
  border-radius: 36px;
  z-index: 1000;
  display: flex;
  justify-content: space-around;
  align-items: center;
  max-width: 500px;
  margin: 0 auto;
}

.dock-item {
  background: none; border: none;
  display: flex; flex-direction: column; align-items: center; gap: 5px;
  color: #999999;
  font-size: 10px; font-weight: 600;
  cursor: pointer;
  transition: all 0.2s;
  width: 64px;
}
.dock-item i { font-size: 22px; margin-bottom: 2px; transition: transform 0.2s; }
.dock-item.active { color: var(--primary); }
.dock-item.active i { transform: translateY(-3px); }

/* --- Sheets (Panels) --- */
.sheet-panel {
  position: absolute;
  z-index: 900;
  background: var(--bg-app);
  display: flex; flex-direction: column;
  transition: transform 0.45s cubic-bezier(0.32, 0.72, 0, 1);
  box-shadow: var(--shadow-card);
}

/* Mobile: Bottom Sheet */
@media (max-width: 768px) {
  .sheet-panel {
    bottom: 0; left: 0; right: 0;
    height: 90vh;
    border-radius: var(--radius-l) var(--radius-l) 0 0;
    transform: translateY(110%);
  }
  .sheet-panel.active { transform: translateY(0); }
  .sheet-handle {
    width: 36px; height: 5px;
    background: #D1D1D6;
    border-radius: 3px;
    margin: 12px auto;
  }
}

/* Desktop: Floating Panel */
@media (min-width: 769px) {
  .sheet-panel {
    top: 88px; bottom: 40px;
    width: 400px;
    border-radius: var(--radius-l);
    background: rgba(255, 255, 255, 0.9);
    backdrop-filter: var(--glass);
    transform: translateX(-120%);
    border: 1px solid rgba(255,255,255,0.5);
  }
  #sheet-explore { left: 24px; }
  #sheet-plan { right: 24px; transform: translateX(120%); }

  #sheet-explore.active { transform: translateX(0); }
  #sheet-plan.active { transform: translateX(0); }

  .sheet-handle { display: none; }
}

.sheet-header {
  padding: 16px 24px;
  display: flex; justify-content: space-between; align-items: center;
}
.sheet-header .brand { font-size: 22px; font-weight: 700; color: var(--text-title); display: flex; align-items: center; gap: 8px; }
.sheet-header .brand i { color: var(--primary); }

.sheet-content {
  flex: 1; overflow-y: auto; padding: 10px 24px 120px 24px;
}

/* --- Common UI Components (Matching Auth Style) --- */

/* Buttons */
.icon-btn, .close-sheet-btn, .close-modal-btn {
  width: 36px; height: 36px;
  border-radius: 50%;
  background: rgba(118, 118, 128, 0.08);
  border: none;
  color: var(--text-body);
  display: flex; align-items: center; justify-content: center;
  cursor: pointer;
  transition: background 0.2s;
}
.icon-btn:hover { background: rgba(118, 118, 128, 0.15); }

/* Unified Input Style */
.ios-input, textarea, .ios-select-wrapper select {
  width: 100%;
  padding: 14px 16px;
  border-radius: var(--radius-m);
  border: 1px solid transparent;
  background: var(--bg-input);
  font-size: 16px;
  color: var(--text-title);
  outline: none;
  transition: all 0.2s;
  font-family: inherit;
}

.ios-input:focus, textarea:focus, .ios-select-wrapper select:focus {
  background: #FFFFFF;
  border-color: var(--primary);
  box-shadow: 0 0 0 4px rgba(0, 122, 255, 0.1);
}

.ios-select-wrapper { position: relative; }
.ios-select-wrapper i {
  position: absolute; right: 16px; top: 50%; transform: translateY(-50%);
  color: var(--text-secondary); pointer-events: none;
}
.ios-select-wrapper select { appearance: none; }

/* Primary Action Buttons */
.btn-generate, .btn-primary-ios {
  width: 100%; padding: 16px;
  border-radius: 16px;
  background: linear-gradient(135deg, #007AFF, #0062cc);
  color: white; border: none;
  font-size: 17px; font-weight: 600;
  cursor: pointer;
  box-shadow: 0 6px 16px var(--primary-glow);
  transition: transform 0.1s, box-shadow 0.2s;
  display: flex; align-items: center; justify-content: center; gap: 8px;
}
.btn-generate:active, .btn-primary-ios:active { transform: scale(0.98); box-shadow: 0 2px 8px var(--primary-glow); }

.btn-danger-ios {
  width: 100%; padding: 14px; background: white; color: var(--danger);
  border-radius: 14px; border: 1px solid rgba(0,0,0,0.05);
  font-size: 16px; font-weight: 600; cursor: pointer;
  margin-top: 16px;
  box-shadow: 0 2px 8px rgba(0,0,0,0.03);
}

/* Cards & Groups */
.settings-group { margin-bottom: 20px; }
.settings-group label {
  display: block; font-size: 13px; font-weight: 600; color: var(--text-secondary);
  margin-bottom: 8px; margin-left: 4px; text-transform: uppercase; letter-spacing: 0.5px;
}

.card-group {
  background: white; padding: 18px; border-radius: var(--radius-m);
  box-shadow: 0 2px 12px rgba(0,0,0,0.03);
}

.flex-row-center { display: flex; justify-content: space-between; align-items: center; }

/* Timeline Cards */
.timeline-card {
  background: white; padding: 20px; border-radius: 20px;
  margin-bottom: 20px; position: relative;
  box-shadow: 0 4px 16px rgba(0,0,0,0.04);
  border-left: 6px solid transparent;
  transition: transform 0.2s, box-shadow 0.2s;
  cursor: pointer;
}
.timeline-card:active { transform: scale(0.98); }
.timeline-card.active { box-shadow: 0 8px 24px rgba(0,0,0,0.08); background: #FDFDFD; }

/* Modals (Matching Auth Glass Style) */
.modal-overlay {
  position: fixed; inset: 0; background: rgba(0,0,0,0.4); backdrop-filter: blur(8px);
  z-index: 2000; display: flex; align-items: center; justify-content: center;
  opacity: 0; pointer-events: none; transition: opacity 0.3s;
}
.modal-overlay.active { opacity: 1; pointer-events: auto; }

.modal-content {
  background: rgba(255, 255, 255, 0.92);
  backdrop-filter: saturate(180%) blur(20px);
  width: 90%; max-width: 420px; max-height: 85vh;
  border-radius: 28px; padding: 32px; overflow-y: auto;
  box-shadow: 0 24px 60px rgba(0,0,0,0.2);
  border: 1px solid rgba(255,255,255,0.6);
}
.modal-header h3 { font-size: 24px; font-weight: 800; }

/* Switch Toggle */
.switch { position: relative; display: inline-block; width: 52px; height: 32px; }
.switch input { opacity: 0; width: 0; height: 0; }
.slider {
  position: absolute; cursor: pointer; top: 0; left: 0; right: 0; bottom: 0;
  background-color: #E9E9EA; transition: .3s; border-radius: 34px;
}
.slider:before {
  position: absolute; content: ""; height: 28px; width: 28px; left: 2px; bottom: 2px;
  background-color: white; transition: .3s cubic-bezier(0.2, 0.8, 0.3, 1); border-radius: 50%;
  box-shadow: 0 2px 6px rgba(0,0,0,0.15);
}
input:checked + .slider { background-color: #34C759; }
input:checked + .slider:before { transform: translateX(20px); }

/* Loading State */
.loading-overlay { 
  position: fixed; inset: 0; background: rgba(255,255,255,0.7); backdrop-filter: blur(20px); 
  z-index: 9999; display: flex; justify-content: center; align-items: center; 
  opacity: 0; pointer-events: none; transition: 0.3s; 
}
.loading-overlay.active { opacity: 1; pointer-events: auto; }
.loading-icon { font-size: 48px; color: var(--primary); margin-bottom: 16px; }
.loading-text h3 { font-size: 18px; font-weight: 600; color: var(--text-title); margin: 0; }

