  --shadow-card: 0 8px 24px rgba(0, 0, 0, 0.06), 0 1px 4px rgba(0,0,0,0.04);
  --shadow-float: 0 12px 32px rgba(0, 0, 0, 0.12);
}

* { box-sizing: border-box; margin: 0; padding: 0; -webkit-tap-highlight-color: transparent; }

html, body { 
  width: 100%; 
  height: 100%; 
  overflow: hidden; 
  background: var(--bg-app); 
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Helvetica Neue", Arial, sans-serif; 
  color: var(--text-body);
}

/* --- App Shell --- */
.app-shell {
  width: 100%; height: 100%; position: relative;
  display: flex; flex-direction: column;
}
.app-shell.blur-content { filter: blur(10px); pointer-events: none; }

.main-canvas { flex: 1; position: relative; z-index: 0; }
#map { width: 100%; height: 100%; background: #E5E5EA; }

/* --- Glass Panels --- */
.glass-panel {
  background: rgba(255, 255, 255, 0.88);
  backdrop-filter: var(--glass);
  -webkit-backdrop-filter: var(--glass);
  border: 0.5px solid rgba(255, 255, 255, 0.4);
  box-shadow: var(--shadow-float);
}

/* --- Top Bar --- */
.top-bar {
  position: absolute;
  top: 16px; left: 16px; right: 16px;
  height: 52px;
  border-radius: 26px;
  z-index: 100;
  display: flex;
  align-items: center;
  padding: 0 6px 0 16px;
  justify-content: space-between;
  max-width: 600px;
  margin: 0 auto;
}

.top-search-trigger {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--text-secondary);
  font-size: 15px;
  cursor: pointer;
}

.user-avatar-mini {
  width: 38px; height: 38px;
  border-radius: 50%;
  overflow: hidden;
  border: 2px solid white;
  cursor: pointer;
  box-shadow: 0 2px 8px rgba(0,0,0,0.1);
}
.user-avatar-mini img { width: 100%; height: 100%; object-fit: cover; }

/* --- Bottom Dock --- */
.bottom-dock {
  position: absolute;
  bottom: 30px;
  left: 20px; right: 20px;
  height: 68px;
  border-radius: 34px;
  z-index: 1000;
  display: flex;
  justify-content: space-around;
  align-items: center;
  max-width: 500px;
  margin: 0 auto;
}

.dock-item {
  background: none; border: none;
  display: flex; flex-direction: column; align-items: center; gap: 4px;
  color: #999;
  font-size: 10px; font-weight: 500;
  cursor: pointer;
  width: 64px;
}
.dock-item i { font-size: 20px; margin-bottom: 2px; transition: transform 0.2s; }
.dock-item.active { color: var(--primary); }
.dock-item.active i { transform: translateY(-2px); }

/* --- Sheets --- */
.sheet-panel {
  position: absolute;
  z-index: 900;
  background: var(--bg-app);
  display: flex; flex-direction: column;
  transition: transform 0.4s cubic-bezier(0.19, 1, 0.22, 1);
