}

@media (max-width: 768px) {
  .sheet-panel {
    bottom: 0; left: 0; right: 0;
    height: 85vh;
    border-radius: 24px 24px 0 0;
    transform: translateY(110%);
  }
  .sheet-panel.active { transform: translateY(0); }
  .sheet-handle {
    width: 40px; height: 5px;
    background: #D1D1D6;
    border-radius: 3px;
    margin: 12px auto 8px auto;
